import React, { useEffect, useState } from 'react'
import { Spinner } from '@persona-framework/ui'

const STORAGE_KEYS = {
  ACCESS_TOKEN: 'wraith_access_token',
  REFRESH_TOKEN: 'wraith_refresh_token',
  TOKEN_TYPE: 'wraith_token_type',
}

/**
 * Parse OAuth callback parameters from URL
 */
function parseOAuthCallback(url: string) {
  const urlObj = new URL(url)
  const params = new URLSearchParams(urlObj.search)

  return {
    accessToken: params.get('access_token'),
    refreshToken: params.get('refresh_token'),
    tokenType: params.get('token_type'),
    error: params.get('error'),
    errorMessage: params.get('error_description') || params.get('error_message'),
  }
}

export function OAuthCallbackPage() {
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    const handleCallback = async () => {
      try {
        const fullUrl = window.location.href
        const params = parseOAuthCallback(fullUrl)

        if (params.error) {
          const errorMsg = params.errorMessage || 'OAuth authentication failed'
          setError(errorMsg)
          if (window.opener) {
            setTimeout(() => window.close(), 3000)
          }
          return
        }

        if (!params.accessToken || !params.refreshToken) {
          setError('Missing authentication tokens')
          return
        }

        localStorage.setItem(STORAGE_KEYS.ACCESS_TOKEN, params.accessToken)
        localStorage.setItem(STORAGE_KEYS.REFRESH_TOKEN, params.refreshToken)
        localStorage.setItem(STORAGE_KEYS.TOKEN_TYPE, params.tokenType || 'Bearer')

        if (window.opener) {
          window.opener.postMessage({ type: 'OAUTH_SUCCESS' }, window.location.origin)
          window.close()
        } else {
          window.location.href = '/'
        }
      } catch (err: any) {
        setError(err.message || 'Failed to complete OAuth login')
      }
    }

    handleCallback()
  }, [])

  if (error) {
    return (
      <div className="flex flex-col items-center justify-center h-screen gap-6">
        <p className="text-base text-destructive text-center max-w-[500px]">{error}</p>
        {window.opener && (
          <p className="text-base text-muted-foreground">This window will close automatically...</p>
        )}
      </div>
    )
  }

  return (
    <div className="flex flex-col items-center justify-center h-screen gap-6">
      <Spinner size="lg" />
      <p className="text-base text-muted-foreground">Please wait while we complete your authentication</p>
    </div>
  )
}

import React from 'react'
import { Button } from '@persona-framework/ui'

interface GitHubSignInButtonProps {
  disabled?: boolean
  size?: 'sm' | 'default' | 'lg'
}

export function GitHubSignInButton({ disabled, size = 'lg' }: GitHubSignInButtonProps) {
  const handleClick = () => {
    const apiBaseUrl = import.meta.env.VITE_API_BASE_URL || 'http://localhost:8989'
    const authUrl = `${apiBaseUrl}/api/auth/oauth2/authorize/github`
    window.open(authUrl, 'oauth-popup', 'width=500,height=600')
  }

  return (
    <Button
      className="w-full bg-[#24292e] text-white border border-border hover:bg-[#2c3237] active:bg-[#1c2024]"
      size={size}
      onClick={handleClick}
      disabled={disabled}
      data-testid="github-signin-button"
    >
      <div className="flex items-center justify-center">
        <svg className="w-[18px] h-[18px] mr-2" viewBox="0 0 16 16" xmlns="http://www.w3.org/2000/svg">
          <path
            fill="#ffffff"
            fillRule="evenodd"
            d="M8 0C3.58 0 0 3.58 0 8c0 3.54 2.29 6.53 5.47 7.59.4.07.55-.17.55-.38 0-.19-.01-.82-.01-1.49-2.01.37-2.53-.49-2.69-.94-.09-.23-.48-.94-.82-1.13-.28-.15-.68-.52-.01-.53.63-.01 1.08.58 1.23.82.72 1.21 1.87.87 2.33.66.07-.52.28-.87.51-1.07-1.78-.2-3.64-.89-3.64-3.95 0-.87.31-1.59.82-2.15-.08-.2-.36-1.02.08-2.12 0 0 .67-.21 2.2.82.64-.18 1.32-.27 2-.27.68 0 1.36.09 2 .27 1.53-1.04 2.2-.82 2.2-.82.44 1.1.16 1.92.08 2.12.51.56.82 1.27.82 2.15 0 3.07-1.87 3.75-3.65 3.95.29.25.54.73.54 1.48 0 1.07-.01 1.93-.01 2.2 0 .21.15.46.55.38A8.013 8.013 0 0016 8c0-4.42-3.58-8-8-8z"
