  '.lock': { icon: <Lock size={14} />, color: '#6d8086' },

  // Log files
  '.log': { icon: <FileText size={14} />, color: '#6d8086' },
}

const FILENAME_ICONS: Record<string, FileIconConfig> = {
  'Dockerfile': { icon: <Ship size={14} />, color: '#384d54' },
  'Makefile': { icon: <Cog size={14} />, color: '#6d8086' },
  'package.json': { icon: <Box size={14} />, color: '#cb3837' },
  'package-lock.json': { icon: <Lock size={14} />, color: '#cb3837' },
  'yarn.lock': { icon: <Lock size={14} />, color: '#2c8ebb' },
  'pnpm-lock.yaml': { icon: <Lock size={14} />, color: '#f9ad00' },
  'tsconfig.json': { icon: <FileCode size={14} />, color: '#3178c6' },
  'vite.config.ts': { icon: <Cog size={14} />, color: '#646cff' },
  'vite.config.js': { icon: <Cog size={14} />, color: '#646cff' },
  '.gitignore': { icon: <Settings size={14} />, color: '#f14e32' },
  '.npmrc': { icon: <Settings size={14} />, color: '#cb3837' },
  '.prettierrc': { icon: <Settings size={14} />, color: '#56b3b4' },
  '.eslintrc': { icon: <Settings size={14} />, color: '#4b32c3' },
  '.eslintrc.js': { icon: <Settings size={14} />, color: '#4b32c3' },
  '.eslintrc.json': { icon: <Settings size={14} />, color: '#4b32c3' },
  'README.md': { icon: <Book size={14} />, color: '#083fa1' },
  'LICENSE': { icon: <FileText size={14} />, color: '#d4af37' },
  'Cargo.toml': { icon: <Cog size={14} />, color: '#dea584' },
  'Cargo.lock': { icon: <Lock size={14} />, color: '#dea584' },
  'build.gradle': { icon: <Cog size={14} />, color: '#02303a' },
  'settings.gradle': { icon: <Cog size={14} />, color: '#02303a' },
}

const DEFAULT_ICON: FileIconConfig = { icon: <File size={14} />, color: '#6d8086' }

export function getFileIcon(fileName: string): FileIconConfig {
  // Check exact filename match first
  if (FILENAME_ICONS[fileName]) {
    return FILENAME_ICONS[fileName]
  }

  // Check for extension
  const lastDot = fileName.lastIndexOf('.')
  if (lastDot !== -1) {
    const ext = fileName.slice(lastDot).toLowerCase()

    // Check for .d.ts special case
    if (fileName.endsWith('.d.ts')) {
      return EXTENSION_ICONS['.d.ts']
    }

    if (EXTENSION_ICONS[ext]) {
      return EXTENSION_ICONS[ext]
    }
  }

  return DEFAULT_ICON
}

interface FileIconProps {
  fileName: string
  size?: number
  className?: string
}

export function FileIcon({ fileName, size = 14, className }: FileIconProps) {
  const { icon, color } = getFileIcon(fileName)

  return (
    <span className={className} style={{ color }}>
      {React.cloneElement(icon as React.ReactElement, { size })}
    </span>
  )
}

import React, { Component, ErrorInfo, ReactNode } from 'react'
import { AlertTriangle, RefreshCw, ChevronDown, ChevronUp } from 'lucide-react'
import { Button } from '@persona-framework/ui'

interface Props {
  children: ReactNode
  fallback?: ReactNode
  onError?: (error: Error, errorInfo: ErrorInfo) => void
}

interface State {
  hasError: boolean
  error: Error | null
  errorInfo: ErrorInfo | null
  showDetails: boolean
}

export class ErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null,
    errorInfo: null,
    showDetails: false,
  }

  public static getDerivedStateFromError(error: Error): Partial<State> {
    return { hasError: true, error }
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    this.setState({ errorInfo })
    this.props.onError?.(error, errorInfo)
  }

  private handleReset = () => {
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
      showDetails: false,
    })
  }

  private handleReload = () => {
    window.location.reload()
  }

  private toggleDetails = () => {
    this.setState(prev => ({ showDetails: !prev.showDetails }))
  }

  public render() {
    if (this.state.hasError) {
      if (this.props.fallback) {
        return this.props.fallback
      }

      return (
        <div className="flex items-center justify-center min-h-[200px] p-6 bg-[#1e1e1e]">
          <div className="max-w-lg w-full bg-[#252526] border border-[#3c3c3c] rounded-lg p-6">
            <div className="flex items-start gap-4">
              <div className="p-2 bg-[#5a1d1d] rounded-lg">
                <AlertTriangle className="w-6 h-6 text-[#f48771]" />
              </div>
              <div className="flex-1">
                <h2 className="text-lg font-semibold text-[#cccccc] mb-2">
                  Something went wrong
                </h2>
                <p className="text-sm text-[#858585] mb-4">
                  An unexpected error occurred while rendering this component.
                  You can try to recover by clicking the button below.
                </p>

                <div className="flex flex-wrap gap-2 mb-4">
                  <Button
                    onClick={this.handleReset}
                    size="sm"
                    className="h-8"
                  >
                    <RefreshCw className="w-4 h-4 mr-1.5" />
                    Try Again
                  </Button>
                  <Button
                    onClick={this.handleReload}
                    variant="outline"
                    size="sm"
                    className="h-8"
                  >
                    Reload Page
                  </Button>
                </div>

                <button
                  onClick={this.toggleDetails}
                  className="flex items-center gap-1 text-xs text-[#4fc3f7] hover:text-[#81d4fa]"
                >
                  {this.state.showDetails ? (
                    <ChevronUp className="w-3 h-3" />
                  ) : (
                    <ChevronDown className="w-3 h-3" />
                  )}
                  {this.state.showDetails ? 'Hide' : 'Show'} error details
                </button>

                {this.state.showDetails && (
                  <div className="mt-3 p-3 bg-[#1e1e1e] rounded border border-[#3c3c3c] overflow-auto max-h-[200px]">
                    <div className="text-xs font-mono">
                      <div className="text-[#f48771] font-semibold mb-2">
                        {this.state.error?.name}: {this.state.error?.message}
                      </div>
                      {this.state.errorInfo?.componentStack && (
                        <pre className="text-[#858585] whitespace-pre-wrap text-[11px] leading-relaxed">
                          {this.state.errorInfo.componentStack}
                        </pre>
                      )}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      )
    }

    return this.props.children
  }
}

interface ErrorBoundaryWrapperProps {
  children: ReactNode
  name?: string
}

export function withErrorBoundary<P extends object>(
  WrappedComponent: React.ComponentType<P>,
  name?: string
) {
  return function WithErrorBoundary(props: P) {
    return (
      <ErrorBoundary>
        <WrappedComponent {...props} />
      </ErrorBoundary>
    )
  }
}

import React from 'react'
import { ChevronRight, FileText } from 'lucide-react'

interface BreadcrumbsProps {
  filePath?: string | null
  onNavigate?: (path: string) => void
}

export function Breadcrumbs({ filePath, onNavigate }: BreadcrumbsProps) {
  if (!filePath) {
    return (
      <div className="flex items-center gap-1 px-3 py-1.5 bg-[#252526] border-b border-[#3c3c3c] text-xs text-[#cccccc] overflow-hidden whitespace-nowrap">
        <FileText className="w-3.5 h-3.5 mr-1 text-[#007acc]" />
        <span className="text-[#858585]">No file selected</span>
      </div>
    )
  }

  const segments = filePath.split('/').filter(Boolean)
  const paths = segments.map((_, index) => '/' + segments.slice(0, index + 1).join('/'))

  return (
    <div className="flex items-center gap-1 px-3 py-1.5 bg-[#252526] border-b border-[#3c3c3c] text-xs text-[#cccccc] overflow-hidden whitespace-nowrap">
      <FileText className="w-3.5 h-3.5 mr-1 text-[#007acc]" />

      {segments.map((segment, index) => {
        const isLast = index === segments.length - 1
        return (
          <React.Fragment key={index}>
            {index > 0 && <ChevronRight className="w-3 h-3 text-[#858585]" />}
            <div
              className={`inline-flex items-center px-1.5 py-0.5 rounded transition-colors ${
                isLast
                  ? 'font-semibold cursor-default'
                  : 'cursor-pointer hover:bg-[#2a2d2e]'
              }`}
              onClick={() => !isLast && onNavigate?.(paths[index])}
              title={paths[index]}
            >
              {segment}
            </div>
          </React.Fragment>
        )
      })}
    </div>
  )
}

