import React from 'react'
import { PanelHeader } from '../molecules'
import { ResizeHandle } from '../molecules'
import { Skeleton } from '../atoms'

export interface PanelContainerProps {
  title: string
  icon?: React.ReactNode
  children: React.ReactNode
  side: 'left' | 'right'
  width: number
  minWidth?: number
  maxWidth?: number
  isNarrow?: boolean
  loading?: boolean
  onClose: () => void
  onCollapse: () => void
  onResize: (delta: number) => void
  className?: string
}

export const PanelContainer: React.FC<PanelContainerProps> = ({
  title,
  icon,
  children,
  side,
  width,
  minWidth = 200,
  maxWidth = 500,
  isNarrow = false,
  loading = false,
  onClose,
  onCollapse,
  onResize,
  className = '',
}) => {
  const handleResize = (delta: number) => {
    // For right panel, invert the delta
    const adjustedDelta = side === 'right' ? -delta : delta
    onResize(adjustedDelta)
  }

  return (
    <div
      className={`flex flex-col overflow-hidden transition-[width,opacity] duration-300 ${
        isNarrow
          ? 'absolute top-12 left-0 right-0 h-[40vh] w-auto max-w-none z-[100] border-b-2 shadow-[var(--shadow-panel)]'
          : 'relative'
      } ${side === 'right' ? 'border-l border-[var(--border-primary)]' : ''} ${className}`}
      style={isNarrow ? {} : { width: `${width}px`, minWidth: `${minWidth}px`, maxWidth: `${maxWidth}px` }}
    >
      {/* Resize handle */}
      {!isNarrow && (
        <ResizeHandle
          direction="horizontal"
          onResize={handleResize}
          className={`absolute top-0 bottom-0 ${side === 'left' ? 'right-0' : 'left-0'}`}
        />
      )}

      <div className="flex flex-col flex-1 overflow-hidden">
        <PanelHeader
          title={title}
          icon={icon}
          onClose={onClose}
          onCollapse={onCollapse}
        />

        <div className="flex-1 overflow-auto bg-[var(--bg-primary)]">
          {loading ? (
            <div className="p-4">
              <Skeleton variant="text" className="mb-2" />
              <Skeleton variant="text" className="mb-2" width="80%" />
              <Skeleton variant="text" width="60%" />
            </div>
          ) : (
            children
          )}
        </div>
      </div>
    </div>
  )
}

