import React, { useRef, useCallback } from 'react'
import { IconTrayItem } from '../molecules'

export interface PanelConfig {
  id: string
  name: string
  icon: React.ReactNode
}

export interface IconTrayProps {
  panels: PanelConfig[]
  activePanel: string | null
  side: 'left' | 'right'
  isNarrow?: boolean
  onPanelClick: (panelId: string) => void
  onPanelReorder?: (fromIndex: number, toIndex: number) => void
  dragOverTray?: boolean
  onTrayDragOver?: (e: React.DragEvent) => void
  onTrayDragLeave?: (e: React.DragEvent) => void
}

export const IconTray: React.FC<IconTrayProps> = ({
  panels,
  activePanel,
  side,
  isNarrow = false,
  onPanelClick,
  onPanelReorder,
  dragOverTray = false,
  onTrayDragOver,
  onTrayDragLeave,
}) => {
  const draggedIndex = useRef<number | null>(null)
  const dragOverIndex = useRef<number | null>(null)

  const handleDragStart = useCallback((index: number) => (e: React.DragEvent) => {
    draggedIndex.current = index
    e.dataTransfer.effectAllowed = 'move'
  }, [])

  const handleDragOver = useCallback((index: number) => (e: React.DragEvent) => {
    e.preventDefault()
    e.dataTransfer.dropEffect = 'move'
    dragOverIndex.current = index
  }, [])

  const handleDrop = useCallback((toIndex: number) => (e: React.DragEvent) => {
    e.preventDefault()
    if (draggedIndex.current !== null && draggedIndex.current !== toIndex) {
      onPanelReorder?.(draggedIndex.current, toIndex)
    }
    draggedIndex.current = null
    dragOverIndex.current = null
  }, [onPanelReorder])

  const handleDragEnd = useCallback(() => {
    draggedIndex.current = null
    dragOverIndex.current = null
  }, [])

  const handleKeyDown = useCallback((index: number, panelId: string) => (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') {
      e.preventDefault()
      const prevIndex = index > 0 ? index - 1 : panels.length - 1
      const prevElement = document.querySelector(`[data-tray-index="${prevIndex}"]`) as HTMLElement
      prevElement?.focus()
    } else if (e.key === 'ArrowDown' || e.key === 'ArrowRight') {
      e.preventDefault()
      const nextIndex = index < panels.length - 1 ? index + 1 : 0
      const nextElement = document.querySelector(`[data-tray-index="${nextIndex}"]`) as HTMLElement
      nextElement?.focus()
    } else if (e.key === 'Escape') {
      if (activePanel === panelId) {
        onPanelClick(panelId) // Toggle off
      }
    }
  }, [panels.length, activePanel, onPanelClick])

  return (
    <div
      data-testid={`${side}-icon-tray`}
      role="toolbar"
      aria-label={`${side} panel toolbar`}
      aria-orientation={isNarrow ? 'horizontal' : 'vertical'}
      onDragOver={onTrayDragOver}
      onDragLeave={onTrayDragLeave}
      className={`
        flex bg-[var(--bg-secondary)] transition-colors duration-200
        ${isNarrow
          ? 'w-full h-[var(--icon-tray-width)] flex-row border-b overflow-x-auto overflow-y-hidden'
          : 'w-[var(--icon-tray-width)] min-w-[var(--icon-tray-width)] flex-col overflow-y-auto'
        }
        ${side === 'left' ? 'border-r' : 'border-l'} border-[var(--border-primary)]
        ${dragOverTray ? 'bg-[var(--accent-hover)] shadow-[inset_0_0_0_2px_var(--accent-primary)]' : ''}
      `}
    >
      {panels.map((panel, index) => (
        <div key={panel.id} data-tray-index={index}>
          <IconTrayItem
            icon={panel.icon}
            label={panel.name}
            active={activePanel === panel.id}
            side={side}
            onClick={() => onPanelClick(panel.id)}
            onDragStart={handleDragStart(index)}
            onDragOver={handleDragOver(index)}
            onDrop={handleDrop(index)}
            onDragEnd={handleDragEnd}
            onKeyDown={handleKeyDown(index, panel.id)}
          />
        </div>
      ))}
    </div>
  )
}

import React from 'react'
import { ExtensionCard } from '../molecules'

export interface Extension {
  id: string
  name: string
  description: string
  icon: React.ReactNode
  category: string
}

export interface ExtensionsPanelProps {
  extensions: Extension[]
  enabledExtensions: string[]
  onToggleExtension: (extensionId: string) => void
  className?: string
}

export const ExtensionsPanel: React.FC<ExtensionsPanelProps> = ({
  extensions,
  enabledExtensions,
  onToggleExtension,
  className = '',
}) => {
  // Group extensions by category
  const categories = [...new Set(extensions.map((e) => e.category))]

  const enabledCount = enabledExtensions.length
  const totalCount = extensions.length

  return (
    <div className={`p-3 space-y-4 ${className}`}>
      <div className="flex items-center justify-between">
        <p className="text-xs text-[var(--text-secondary)]">
          Enable extensions to add functionality
        </p>
        <span className="text-xs text-[var(--text-muted)]">
          {enabledCount}/{totalCount} enabled
        </span>
      </div>

      {categories.map((category) => {
        const categoryExtensions = extensions.filter((e) => e.category === category)
        if (categoryExtensions.length === 0) return null

        return (
          <div key={category}>
            <h3 className="text-xs font-semibold text-[var(--text-secondary)] uppercase tracking-wider mb-2">
              {category}
            </h3>
            <div className="space-y-1">
              {categoryExtensions.map((ext) => (
                <ExtensionCard
                  key={ext.id}
                  id={ext.id}
                  name={ext.name}
                  description={ext.description}
                  icon={ext.icon}
                  enabled={enabledExtensions.includes(ext.id)}
                  onToggle={() => onToggleExtension(ext.id)}
                />
              ))}
            </div>
          </div>
        )
      })}
    </div>
  )
}

