import React from 'react'
import { GitBranch, AlertTriangle } from 'lucide-react'
import { StatusBarItem } from '../molecules'

export interface StatusBarProps {
  filePath?: string
  tabSize: number
  insertSpaces: boolean
  encoding?: string
  onGitClick?: () => void
  onProblemsClick?: () => void
  leftItems?: React.ReactNode
  rightItems?: React.ReactNode
  className?: string
}

export const StatusBar: React.FC<StatusBarProps> = ({
  filePath,
  tabSize,
  insertSpaces,
  encoding = 'UTF-8',
  onGitClick,
  onProblemsClick,
  leftItems,
  rightItems,
  className = '',
}) => {
  return (
    <div
      role="status"
      aria-label="Status bar"
      className={`h-[var(--statusbar-height)] flex items-center justify-between px-3 bg-[var(--statusbar-bg)] select-none ${className}`}
    >
      <div className="flex items-center gap-3">
        {onGitClick && (
          <StatusBarItem icon={<GitBranch />} onClick={onGitClick} tooltip="Source Control">
            <span className="sr-only">Source Control</span>
          </StatusBarItem>
        )}
        {onProblemsClick && (
          <StatusBarItem icon={<AlertTriangle />} onClick={onProblemsClick} tooltip="Problems">
            <span className="sr-only">Problems</span>
          </StatusBarItem>
        )}
        {leftItems}
        {filePath && (
          <StatusBarItem tooltip={filePath}>
            <span className="truncate max-w-[300px]">{filePath}</span>
          </StatusBarItem>
        )}
      </div>

      <div className="flex items-center gap-3">
        {rightItems}
        <StatusBarItem>
          {insertSpaces ? 'Spaces' : 'Tabs'}: {tabSize}
        </StatusBarItem>
        <StatusBarItem>{encoding}</StatusBarItem>
      </div>
    </div>
  )
}

