import React, { useState } from 'react'
import { X, Pin } from 'lucide-react'

export interface TabItemProps {
  id: string
  title: string
  icon?: React.ReactNode
  active?: boolean
  pinned?: boolean
  modified?: boolean
  onClick?: () => void
  onClose?: () => void
  onPin?: () => void
  onContextMenu?: (e: React.MouseEvent) => void
}

export const TabItem: React.FC<TabItemProps> = ({
  title,
  icon,
  active = false,
  pinned = false,
  modified = false,
  onClick,
  onClose,
  onPin,
  onContextMenu,
}) => {
  const [isHovered, setIsHovered] = useState(false)

  const showActions = isHovered || active

  return (
    <div
      role="tab"
      aria-selected={active}
      tabIndex={active ? 0 : -1}
      onClick={onClick}
      onContextMenu={onContextMenu}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      className={`group relative flex items-center gap-2 px-3 h-[var(--tab-height)] cursor-pointer select-none border-r border-[var(--border-primary)] transition-colors ${
        active
          ? 'bg-[var(--bg-primary)] text-[var(--text-primary)]'
          : 'bg-[var(--bg-secondary)] text-[var(--text-secondary)] hover:text-[var(--text-primary)]'
      }`}
    >
      {icon && <span className="flex-shrink-0 [&>svg]:h-4 [&>svg]:w-4">{icon}</span>}

      <span className="text-xs truncate max-w-[120px]">{title}</span>

      {modified && !showActions && (
        <span className="w-2 h-2 rounded-full bg-[var(--text-secondary)]" />
      )}

      {/* Action buttons - shown on hover or when active */}
      <div
        className={`flex items-center gap-0.5 ml-1 transition-opacity ${
          showActions ? 'opacity-100' : 'opacity-0'
        }`}
      >
        {onPin && (
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation()
              onPin()
            }}
            className={`p-0.5 rounded hover:bg-[var(--bg-hover)] transition-colors ${
              pinned ? 'text-[var(--accent-primary)]' : 'text-[var(--text-secondary)]'
            }`}
            title={pinned ? 'Unpin tab' : 'Pin tab'}
          >
            <Pin className="h-3 w-3" />
          </button>
        )}
        {onClose && !pinned && (
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation()
              onClose()
            }}
            className="p-0.5 rounded text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-hover)] transition-colors"
            title="Close tab"
          >
            <X className="h-3 w-3" />
          </button>
        )}
      </div>

      {/* Active indicator */}
      {active && (
        <div className="absolute bottom-0 left-0 right-0 h-[2px] bg-[var(--accent-primary)]" />
      )}
    </div>
  )
}

