import React, { createContext, useContext, useState, useCallback, useEffect, ReactNode } from 'react'

type AriaLive = 'polite' | 'assertive' | 'off'

interface Announcement {
  id: string
  message: string
  priority: AriaLive
}

interface AnnouncerContextType {
  announce: (message: string, priority?: AriaLive) => void
  announcePolite: (message: string) => void
  announceAssertive: (message: string) => void
}

const AnnouncerContext = createContext<AnnouncerContextType | null>(null)

export function useAnnouncer() {
  const context = useContext(AnnouncerContext)
  if (!context) {
    throw new Error('useAnnouncer must be used within an AnnouncerProvider')
  }
  return context
}

interface AnnouncerProviderProps {
  children: ReactNode
}

export function AnnouncerProvider({ children }: AnnouncerProviderProps) {
  const [politeMessage, setPoliteMessage] = useState('')
  const [assertiveMessage, setAssertiveMessage] = useState('')

  const announce = useCallback((message: string, priority: AriaLive = 'polite') => {
    if (priority === 'assertive') {
      setAssertiveMessage(message)
    } else {
      setPoliteMessage(message)
    }
  }, [])

  const announcePolite = useCallback((message: string) => {
    announce(message, 'polite')
  }, [announce])

  const announceAssertive = useCallback((message: string) => {
    announce(message, 'assertive')
  }, [announce])

  // Clear messages after they're announced
  useEffect(() => {
    if (politeMessage) {
      const timeout = setTimeout(() => setPoliteMessage(''), 1000)
      return () => clearTimeout(timeout)
    }
  }, [politeMessage])

  useEffect(() => {
    if (assertiveMessage) {
      const timeout = setTimeout(() => setAssertiveMessage(''), 1000)
      return () => clearTimeout(timeout)
    }
  }, [assertiveMessage])

  return (
    <AnnouncerContext.Provider value={{ announce, announcePolite, announceAssertive }}>
      {children}
      {/* Screen reader only live regions */}
      <div
        role="status"
        aria-live="polite"
        aria-atomic="true"
        className="sr-only"
        style={{
          position: 'absolute',
          width: '1px',
          height: '1px',
          padding: 0,
          margin: '-1px',
          overflow: 'hidden',
          clip: 'rect(0, 0, 0, 0)',
          whiteSpace: 'nowrap',
          border: 0,
        }}
      >
        {politeMessage}
      </div>
      <div
        role="alert"
        aria-live="assertive"
        aria-atomic="true"
        className="sr-only"
        style={{
          position: 'absolute',
          width: '1px',
          height: '1px',
          padding: 0,
          margin: '-1px',
          overflow: 'hidden',
          clip: 'rect(0, 0, 0, 0)',
          whiteSpace: 'nowrap',
          border: 0,
        }}
      >
        {assertiveMessage}
      </div>
    </AnnouncerContext.Provider>
  )
}

// Higher-order component for components that need announcer
export function withAnnouncer<P extends object>(
  WrappedComponent: React.ComponentType<P & { announcer: AnnouncerContextType }>
) {
  return function WithAnnouncer(props: P) {
    const announcer = useAnnouncer()
    return <WrappedComponent {...props} announcer={announcer} />
  }
}

// Utility hook for common announcements
export function useStatusAnnouncer() {
  const { announcePolite, announceAssertive } = useAnnouncer()

  return {
    announceLoading: (item: string) => announcePolite(`Loading ${item}...`),
    announceLoaded: (item: string) => announcePolite(`${item} loaded`),
    announceSaved: (item: string) => announcePolite(`${item} saved`),
    announceError: (message: string) => announceAssertive(`Error: ${message}`),
    announceSuccess: (message: string) => announcePolite(message),
    announceAction: (action: string) => announcePolite(action),
  }
}

import React, { useState, useEffect, useRef } from 'react'
import { Button } from '@persona-framework/ui'
import { Sparkles, CheckCircle, XCircle, Loader2 } from 'lucide-react'
import type * as Monaco from 'monaco-editor'

interface AICodeAssistantProps {
  editor: Monaco.editor.IStandaloneCodeEditor | null
  enabled?: boolean
}

interface Suggestion {
  text: string
  position: Monaco.IPosition
  range: Monaco.IRange
}

export function AICodeAssistant({ editor, enabled = true }: AICodeAssistantProps) {
  const [currentSuggestion, setCurrentSuggestion] = useState<Suggestion | null>(null)
  const [isGenerating, setIsGenerating] = useState(false)
  const [showFeaturePanel, setShowFeaturePanel] = useState(false)
  const suggestionTimeoutRef = useRef<NodeJS.Timeout | null>(null)
  const inlineWidgetRef = useRef<Monaco.editor.IContentWidget | null>(null)

  useEffect(() => {
    if (!editor || !enabled) return

    const onDidChangeContent = editor.onDidChangeModelContent((e) => {
      if (suggestionTimeoutRef.current) {
        clearTimeout(suggestionTimeoutRef.current)
      }

      suggestionTimeoutRef.current = setTimeout(() => {
        generateInlineSuggestion()
      }, 800)
    })

    return () => {
      onDidChangeContent.dispose()
      if (suggestionTimeoutRef.current) {
        clearTimeout(suggestionTimeoutRef.current)
      }
    }
  }, [editor, enabled])

  useEffect(() => {
    if (!editor) return

    const onKeyDown = editor.onKeyDown((e) => {
      if (e.keyCode === 2 && currentSuggestion) {
        e.preventDefault()
        acceptSuggestion()
      }
      else if (e.keyCode === 9 && currentSuggestion) {
        e.preventDefault()
        dismissSuggestion()
      }
    })

    return () => {
      onKeyDown.dispose()
    }
  }, [editor, currentSuggestion])

  const generateInlineSuggestion = async () => {
    if (!editor) return

    const model = editor.getModel()
    if (!model) return

    const position = editor.getPosition()
    if (!position) return

    const lineNumber = position.lineNumber
    const currentLine = model.getLineContent(lineNumber)

    if (!currentLine.trim()) return

    const startLine = Math.max(1, lineNumber - 10)
    const context = []
    for (let i = startLine; i < lineNumber; i++) {
      context.push(model.getLineContent(i))
    }
    context.push(currentLine)

    const contextText = context.join('\n')

    if (currentLine.trim().startsWith('//') || currentLine.trim().startsWith('/*')) {
      return
    }

    setIsGenerating(true)

    try {
      const response = await fetch('/api/ai/code-completion', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          context: contextText,
          language: model.getLanguageId(),
          position: { line: position.lineNumber, column: position.column },
        }),
      })

      if (response.ok) {
        const data = await response.json()
        if (data.suggestion && data.suggestion.trim()) {
          const suggestionText = data.suggestion
          const range: Monaco.IRange = {
            startLineNumber: position.lineNumber,
            startColumn: position.column,
            endLineNumber: position.lineNumber,
            endColumn: position.column,
          }

          setCurrentSuggestion({
            text: suggestionText,
            position,
            range,
          })

          showInlineWidget(suggestionText, position)
        }
      }
    } catch (error) {
      console.error('Failed to generate code suggestion:', error)
    } finally {
      setIsGenerating(false)
    }
  }

  const showInlineWidget = (text: string, position: Monaco.IPosition) => {
    if (!editor) return

    if (inlineWidgetRef.current) {
      editor.removeContentWidget(inlineWidgetRef.current)
    }

    const widget: Monaco.editor.IContentWidget = {
      getId: () => 'ai-suggestion-widget',
      getDomNode: () => {
        const node = document.createElement('div')
        node.style.color = '#858585'
        node.style.fontStyle = 'italic'
        node.style.opacity = '0.6'
        node.style.pointerEvents = 'none'
        node.textContent = text
        return node
      },
      getPosition: () => ({
        position,
        preference: [1],
      }),
    }

    editor.addContentWidget(widget)
    inlineWidgetRef.current = widget
  }

  const acceptSuggestion = () => {
    if (!editor || !currentSuggestion) return

    const model = editor.getModel()
    if (!model) return

    editor.executeEdits('ai-assistant', [
      {
        range: currentSuggestion.range,
        text: currentSuggestion.text,
        forceMoveMarkers: true,
      },
    ])

    dismissSuggestion()
  }

  const dismissSuggestion = () => {
    if (!editor) return

    if (inlineWidgetRef.current) {
      editor.removeContentWidget(inlineWidgetRef.current)
      inlineWidgetRef.current = null
    }

    setCurrentSuggestion(null)
  }

  const explainCode = async () => {
    if (!editor) return

    const selection = editor.getSelection()
    const model = editor.getModel()
    if (!selection || !model) return

    const selectedText = model.getValueInRange(selection)
    if (!selectedText.trim()) {
      alert('Please select code to explain')
      return
    }

    setShowFeaturePanel(false)

    try {
      const response = await fetch('/api/ai/explain-code', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          code: selectedText,
          language: model.getLanguageId(),
        }),
      })

      if (response.ok) {
        const data = await response.json()
        alert(`Code Explanation:\n\n${data.explanation}`)
      }
    } catch (error) {
      console.error('Failed to explain code:', error)
      alert('Failed to explain code. Please try again.')
    }
  }

  const generateCodeFromComment = async () => {
    if (!editor) return

    const position = editor.getPosition()
    const model = editor.getModel()
    if (!position || !model) return

    const currentLine = model.getLineContent(position.lineNumber)

    if (!currentLine.trim().startsWith('//') && !currentLine.trim().startsWith('/*')) {
      alert('Place cursor on a comment line to generate code from it')
      return
    }

    const comment = currentLine.replace(/^[\s/*]*/, '').replace(/[*\/]*$/, '').trim()

    setShowFeaturePanel(false)
    setIsGenerating(true)

    try {
      const response = await fetch('/api/ai/generate-code', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          prompt: comment,
          language: model.getLanguageId(),
          context: model.getValue(),
        }),
      })

      if (response.ok) {
        const data = await response.json()
        if (data.code) {
          const insertPosition = {
            lineNumber: position.lineNumber + 1,
            column: 1,
          }

          editor.executeEdits('ai-assistant', [
            {
              range: {
                startLineNumber: insertPosition.lineNumber,
                startColumn: insertPosition.column,
                endLineNumber: insertPosition.lineNumber,
                endColumn: insertPosition.column,
              },
              text: data.code + '\n',
              forceMoveMarkers: true,
            },
          ])
        }
      }
    } catch (error) {
      console.error('Failed to generate code:', error)
      alert('Failed to generate code. Please try again.')
    } finally {
      setIsGenerating(false)
    }
  }

  const refactorCode = async () => {
    if (!editor) return

    const selection = editor.getSelection()
    const model = editor.getModel()
    if (!selection || !model) return

    const selectedText = model.getValueInRange(selection)
    if (!selectedText.trim()) {
      alert('Please select code to refactor')
      return
    }

    setShowFeaturePanel(false)
    setIsGenerating(true)

    try {
      const response = await fetch('/api/ai/refactor-code', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          code: selectedText,
          language: model.getLanguageId(),
        }),
      })

      if (response.ok) {
        const data = await response.json()
        if (data.refactored) {
          editor.executeEdits('ai-assistant', [
            {
              range: selection,
              text: data.refactored,
              forceMoveMarkers: true,
            },
          ])
        }
      }
    } catch (error) {
      console.error('Failed to refactor code:', error)
      alert('Failed to refactor code. Please try again.')
    } finally {
      setIsGenerating(false)
    }
  }

  if (!enabled) return null

  return (
    <div className="relative w-full h-full">
      {currentSuggestion && (
        <div className="absolute top-2 right-2 flex items-center gap-2 px-3 py-2 bg-[#2b2b2b] border border-[#4fc3f7] rounded z-[1000] text-xs text-[#cccccc] shadow-lg">
          <Sparkles className="w-4 h-4 text-[#4fc3f7]" />
          <span className="text-[#4fc3f7] font-medium">AI Suggestion</span>
          <span className="text-[10px] text-[#858585]">Tab to accept, Esc to dismiss</span>
          <Button
            size="sm"
            onClick={acceptSuggestion}
            className="bg-[#0e639c] hover:bg-[#1177bb]"
          >
            <CheckCircle className="w-3 h-3" />
          </Button>
          <Button
            variant="ghost"
            size="sm"
            onClick={dismissSuggestion}
          >
            <XCircle className="w-3 h-3" />
          </Button>
        </div>
      )}

      {isGenerating && (
        <div className="absolute bottom-3 right-3 flex items-center gap-2 px-3 py-1.5 bg-[#2b2b2b] border border-[#4fc3f7] rounded text-[11px] text-[#4fc3f7] z-[1000]">
          <Loader2 className="w-3 h-3 animate-spin" />
          <span>AI generating...</span>
        </div>
      )}

      {showFeaturePanel && (
        <div className="absolute top-12 right-3 w-[300px] bg-[#1e1e1e] border border-[#3c3c3c] rounded p-3 z-[1000] shadow-lg">
          <div className="text-sm font-semibold text-white mb-3 flex items-center">
            <Sparkles className="w-4 h-4 mr-2" />
            AI Code Assistant
          </div>

          <Button
            variant="ghost"
            className="w-full justify-start mb-2"
            onClick={explainCode}
          >
            <Sparkles className="w-4 h-4 mr-2 text-[#4fc3f7]" />
            Explain Selected Code
          </Button>

          <Button
            variant="ghost"
            className="w-full justify-start mb-2"
            onClick={generateCodeFromComment}
          >
            <Sparkles className="w-4 h-4 mr-2 text-[#4fc3f7]" />
            Generate Code from Comment
          </Button>

          <Button
            variant="ghost"
            className="w-full justify-start mb-2"
            onClick={refactorCode}
          >
            <Sparkles className="w-4 h-4 mr-2 text-[#4fc3f7]" />
            Refactor Selected Code
          </Button>

          <Button
            variant="outline"
            size="sm"
            className="w-full mt-2"
            onClick={() => setShowFeaturePanel(false)}
          >
            Close
          </Button>
        </div>
      )}

      <Button
        size="sm"
        onClick={() => setShowFeaturePanel(!showFeaturePanel)}
        className="absolute top-3 right-3 z-[999] bg-[#0e639c] rounded-full w-9 h-9 p-0 min-w-0"
        title="AI Code Assistant (Ctrl+Shift+A)"
      >
        <Sparkles className="w-4 h-4" />
      </Button>
    </div>
  )
}

import React, { useState, useEffect } from 'react'
import { Button } from '@persona-framework/ui'
import { DiffEditor } from '@monaco-editor/react'
import { RefreshCw, X, Loader2 } from 'lucide-react'

interface GitDiffViewerProps {
  filePath: string | null
  onClose?: () => void
}

interface DiffStats {
  additions: number
  deletions: number
  status: 'modified' | 'added' | 'deleted' | 'renamed'
}

export function GitDiffViewer({ filePath, onClose }: GitDiffViewerProps) {
  const [originalContent, setOriginalContent] = useState<string>('')
  const [modifiedContent, setModifiedContent] = useState<string>('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [diffStats, setDiffStats] = useState<DiffStats>({ additions: 0, deletions: 0, status: 'modified' })

  const fetchGitDiff = async (path: string) => {
    setLoading(true)
    setError(null)

    try {
      const absolutePath = path.startsWith('/') ? path : `/workspace/persona-framework/${path}`

      const currentResponse = await fetch(`/api/project/read?path=${encodeURIComponent(absolutePath)}`)
      if (!currentResponse.ok) {
        throw new Error(`Failed to read current file: ${currentResponse.statusText}`)
      }
      const currentData = await currentResponse.json()
      setModifiedContent(currentData.content || '')

      const gitResponse = await fetch(`/api/git/show?path=${encodeURIComponent(path)}&ref=HEAD`)
      if (gitResponse.ok) {
        const gitData = await gitResponse.json()
        setOriginalContent(gitData.content || '')

        const stats = calculateDiffStats(gitData.content || '', currentData.content || '')
        setDiffStats(stats)
      } else {
        setOriginalContent('')
        setDiffStats({ additions: currentData.content.split('\n').length, deletions: 0, status: 'added' })
      }

      setLoading(false)
    } catch (err: any) {
      setError(err.message || 'Failed to load git diff')
      setLoading(false)
    }
  }

  const calculateDiffStats = (original: string, modified: string): DiffStats => {
    const originalLines = original.split('\n')
    const modifiedLines = modified.split('\n')

    let additions = 0
    let deletions = 0

    const maxLines = Math.max(originalLines.length, modifiedLines.length)

    for (let i = 0; i < maxLines; i++) {
      const origLine = originalLines[i]
      const modLine = modifiedLines[i]

      if (origLine === undefined && modLine !== undefined) {
        additions++
      } else if (origLine !== undefined && modLine === undefined) {
        deletions++
      } else if (origLine !== modLine) {
        additions++
        deletions++
      }
    }

    let status: 'modified' | 'added' | 'deleted' = 'modified'
    if (original === '' && modified !== '') status = 'added'
    if (original !== '' && modified === '') status = 'deleted'

    return { additions, deletions, status }
  }

  useEffect(() => {
    if (filePath) {
      fetchGitDiff(filePath)
    }
  }, [filePath])

  const handleRefresh = () => {
    if (filePath) {
      fetchGitDiff(filePath)
    }
  }

  const getLanguage = (path: string | null): string => {
    if (!path) return 'plaintext'

    const ext = path.split('.').pop()?.toLowerCase()
    const languageMap: Record<string, string> = {
      ts: 'typescript',
      tsx: 'typescript',
      js: 'javascript',
      jsx: 'javascript',
      json: 'json',
      md: 'markdown',
      java: 'java',
      kt: 'kotlin',
      py: 'python',
      css: 'css',
      html: 'html',
      xml: 'xml',
      yaml: 'yaml',
      yml: 'yaml',
      sh: 'shell',
      sql: 'sql',
    }
    return languageMap[ext || ''] || 'plaintext'
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'modified':
        return 'bg-[#f59e0b33] text-[#f59e0b]'
      case 'added':
        return 'bg-[#10b98133] text-[#10b981]'
      case 'deleted':
        return 'bg-[#ef444433] text-[#ef4444]'
      default:
        return 'bg-[#3c3c3c] text-[#cccccc]'
    }
  }

  if (!filePath) {
    return (
      <div className="w-full h-full flex flex-col bg-[#1e1e1e]">
        <div className="p-10 text-center text-[#858585]">
          Select a file to view git diff
        </div>
      </div>
    )
  }

  if (loading) {
    return (
      <div className="w-full h-full flex flex-col bg-[#1e1e1e]">
        <div className="flex items-center gap-2 px-3 py-2 bg-[#2b2b2b] border-b border-[#3c3c3c] text-[#cccccc] text-xs">
          <span>{filePath}</span>
        </div>
        <div className="flex flex-col items-center justify-center gap-3 p-10">
          <Loader2 className="w-6 h-6 animate-spin" />
          <span className="text-sm">Loading git diff...</span>
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className="w-full h-full flex flex-col bg-[#1e1e1e]">
        <div className="flex items-center gap-2 px-3 py-2 bg-[#2b2b2b] border-b border-[#3c3c3c] text-[#cccccc] text-xs">
          <span>{filePath}</span>
          {onClose && (
            <Button
              variant="ghost"
              size="sm"
              onClick={onClose}
              className="ml-auto"
            >
              <X className="w-4 h-4" />
            </Button>
          )}
        </div>
        <div className="p-5 text-[#f48771]">{error}</div>
      </div>
    )
  }

  return (
    <div className="w-full h-full flex flex-col bg-[#1e1e1e]">
      <div className="flex items-center justify-between px-3 py-2 bg-[#2b2b2b] border-b border-[#3c3c3c] text-[#cccccc] text-xs">
        <div className="flex items-center gap-3">
          <span>{filePath}</span>
          <div className={`px-2 py-0.5 rounded-xl text-[11px] font-semibold uppercase ${getStatusColor(diffStats.status)}`}>
            {diffStats.status}
          </div>
          <div className="flex gap-4 text-[11px]">
            <div className="flex items-center gap-1">
              <span className="font-semibold text-[#10b981]">
                +{diffStats.additions}
              </span>
              <span>additions</span>
            </div>
            <div className="flex items-center gap-1">
              <span className="font-semibold text-[#ef4444]">
                -{diffStats.deletions}
              </span>
              <span>deletions</span>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="ghost"
            size="sm"
            onClick={handleRefresh}
            title="Refresh diff"
          >
            <RefreshCw className="w-4 h-4" />
          </Button>
          {onClose && (
            <Button
              variant="ghost"
              size="sm"
              onClick={onClose}
              title="Close diff view"
            >
              <X className="w-4 h-4" />
            </Button>
          )}
        </div>
      </div>

      <div className="flex-1 min-h-0">
        <DiffEditor
          height="100%"
          language={getLanguage(filePath)}
          original={originalContent}
          modified={modifiedContent}
          theme="vs-dark"
          options={{
            readOnly: true,
            renderSideBySide: true,
            minimap: { enabled: false },
            fontSize: 13,
            lineNumbers: 'on',
            scrollBeyondLastLine: false,
            automaticLayout: true,
            renderOverviewRuler: true,
            diffWordWrap: 'on',
          }}
        />
      </div>
    </div>
  )
}

