import React, { useState, useEffect } from 'react'
import { Button, Toggle } from '@persona-framework/ui'
import { FileText, Code, SplitSquareVertical } from 'lucide-react'
import ReactMarkdown from 'react-markdown'
import remarkGfm from 'remark-gfm'
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter'
import { vscDarkPlus } from 'react-syntax-highlighter/dist/esm/styles/prism'

interface MarkdownPreviewProps {
  filePath: string | null
  content?: string
}

type ViewMode = 'preview' | 'source' | 'split'

export function MarkdownPreview({ filePath, content: propContent }: MarkdownPreviewProps) {
  const [content, setContent] = useState<string>(propContent || '')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [viewMode, setViewMode] = useState<ViewMode>('preview')

  useEffect(() => {
    if (propContent !== undefined) {
      setContent(propContent)
      return
    }

    if (!filePath) {
      setContent('')
      setError(null)
      return
    }

    setLoading(true)
    setError(null)

    const absolutePath = filePath.startsWith('/') ? filePath : `/workspace/persona-framework/${filePath}`

    fetch(`/api/project/read?path=${encodeURIComponent(absolutePath)}`)
      .then(response => {
        if (!response.ok) {
          if (response.status === 404) {
            throw new Error('API endpoint /api/project/read not found. Backend support needed.')
          }
          throw new Error(`Failed to read file: ${response.statusText}`)
        }
        return response.json()
      })
      .then(data => {
        setContent(data.content || '')
        setLoading(false)
      })
      .catch(err => {
        setError(err.message)
        setLoading(false)
      })
  }, [filePath, propContent])

  if (!filePath && !propContent) {
    return (
      <div className="w-full h-full flex flex-col bg-[#1e1e1e]">
        <div className="p-10 text-center text-[#858585]">
          Select a markdown file to preview
        </div>
      </div>
    )
  }

  if (loading) {
    return (
      <div className="w-full h-full flex flex-col bg-[#1e1e1e]">
        <div className="flex items-center gap-2 px-3 py-2 bg-[#2b2b2b] border-b border-[#3c3c3c] text-[#cccccc] text-xs">{filePath}</div>
        <div className="p-10 text-center text-[#858585]">Loading markdown...</div>
      </div>
    )
  }

  if (error) {
    return (
      <div className="w-full h-full flex flex-col bg-[#1e1e1e]">
        <div className="flex items-center gap-2 px-3 py-2 bg-[#2b2b2b] border-b border-[#3c3c3c] text-[#cccccc] text-xs">{filePath}</div>
        <div className="p-5 text-[#f48771]">{error}</div>
      </div>
    )
  }

  const renderPreview = () => (
    <div className="flex-1 overflow-auto bg-[#1e1e1e] px-10 py-5 text-[#d4d4d4] text-sm leading-relaxed border-l border-[#3c3c3c]">
      <ReactMarkdown
        remarkPlugins={[remarkGfm]}
        components={{
          h1: ({ children }) => <h1 className="text-[32px] font-bold text-white mt-6 mb-4 pb-2 border-b border-[#3c3c3c]">{children}</h1>,
          h2: ({ children }) => <h2 className="text-2xl font-semibold text-white mt-5 mb-3 pb-1.5 border-b border-[#3c3c3c]">{children}</h2>,
          h3: ({ children }) => <h3 className="text-xl font-semibold text-white mt-4 mb-2.5">{children}</h3>,
          h4: ({ children }) => <h4 className="text-base font-semibold text-[#cccccc] mt-3 mb-2">{children}</h4>,
          h5: ({ children }) => <h5 className="text-sm font-semibold text-[#cccccc] mt-2.5 mb-1.5">{children}</h5>,
          h6: ({ children }) => <h6 className="text-sm font-semibold text-[#cccccc] mt-2.5 mb-1.5">{children}</h6>,
          p: ({ children }) => <p className="mb-4 text-[#d4d4d4]">{children}</p>,
          ul: ({ children }) => <ul className="ml-6 mb-4 text-[#d4d4d4]">{children}</ul>,
          ol: ({ children }) => <ol className="ml-6 mb-4 text-[#d4d4d4]">{children}</ol>,
          li: ({ children }) => <li className="mb-2">{children}</li>,
          a: ({ href, children }) => (
            <a href={href} className="text-[#4fc3f7] no-underline hover:underline" target="_blank" rel="noopener noreferrer">
              {children}
            </a>
          ),
          code({ node, inline, className, children, ...props }) {
            const match = /language-(\w+)/.exec(className || '')
            const language = match ? match[1] : ''

            return !inline && language ? (
              <SyntaxHighlighter
                style={vscDarkPlus}
                language={language}
                PreTag="div"
                customStyle={{
                  margin: 0,
                  borderRadius: '6px',
                  fontSize: '13px',
                }}
                {...props}
              >
                {String(children).replace(/\n$/, '')}
              </SyntaxHighlighter>
            ) : (
              <code className="bg-[#3c3c3c] px-1.5 py-0.5 rounded font-mono text-[13px] text-[#f59e0b]" {...props}>
                {children}
              </code>
            )
          },
          pre: ({ children }) => <pre className="mb-4 rounded-md overflow-auto">{children}</pre>,
          blockquote: ({ children }) => (
            <blockquote className="ml-0 mb-4 pl-4 border-l-4 border-[#4fc3f7] text-[#b0b0b0] italic">
              {children}
            </blockquote>
          ),
          table: ({ children }) => (
            <table className="w-full mb-4 border-collapse border border-[#3c3c3c]">
              {children}
            </table>
          ),
          th: ({ children }) => (
            <th className="bg-[#2b2b2b] text-white font-semibold p-3 text-left border border-[#3c3c3c]">
              {children}
            </th>
          ),
          td: ({ children }) => (
            <td className="p-3 border border-[#3c3c3c] text-[#d4d4d4]">
              {children}
            </td>
          ),
          tr: ({ children }) => <tr className="even:bg-[#252526]">{children}</tr>,
          hr: () => <hr className="border-none border-t border-[#3c3c3c] my-6" />,
          img: ({ src, alt }) => (
            <img src={src} alt={alt} className="max-w-full h-auto rounded-md mt-2 mb-4" />
          ),
        }}
      >
        {content}
      </ReactMarkdown>
    </div>
  )

  const renderSource = () => (
    <div className="flex-1 overflow-auto bg-[#1e1e1e] p-5 font-mono text-sm text-[#d4d4d4] leading-relaxed whitespace-pre-wrap break-words">
      {content}
    </div>
  )

  return (
    <div className="w-full h-full flex flex-col bg-[#1e1e1e]">
      <div className="flex items-center justify-between px-3 py-2 bg-[#2b2b2b] border-b border-[#3c3c3c] text-[#cccccc] text-xs">
        <span>{filePath || 'Markdown Preview'}</span>
        <div className="flex gap-1">
          <Button
            variant={viewMode === 'preview' ? 'default' : 'ghost'}
            size="sm"
            onClick={() => setViewMode('preview')}
            title="Preview"
          >
            <FileText className="w-4 h-4" />
          </Button>
          <Button
            variant={viewMode === 'split' ? 'default' : 'ghost'}
            size="sm"
            onClick={() => setViewMode('split')}
            title="Split View"
          >
            <SplitSquareVertical className="w-4 h-4" />
          </Button>
          <Button
            variant={viewMode === 'source' ? 'default' : 'ghost'}
            size="sm"
            onClick={() => setViewMode('source')}
            title="Source"
          >
            <Code className="w-4 h-4" />
          </Button>
        </div>
      </div>

      {viewMode === 'preview' && renderPreview()}
      {viewMode === 'source' && renderSource()}
      {viewMode === 'split' && (
        <div className="flex flex-1 overflow-hidden">
          {renderSource()}
          {renderPreview()}
        </div>
      )}
    </div>
  )
}

import React, { useState, useEffect } from 'react'
import { Button, Input, Switch, Badge, Spinner, Tabs, TabsList, TabsTrigger, TabsContent } from '@persona-framework/ui'
import {
  Search,
  Plug,
  Settings,
  Trash2,
  Download,
  CheckCircle,
  XCircle,
  Star,
} from 'lucide-react'

interface Extension {
  id: string
  name: string
  author: string
  version: string
  description: string
  icon?: string
  rating: number
  downloads: number
  category: string
  tags: string[]
  installed: boolean
  enabled: boolean
  featured?: boolean
}

type TabValue = 'installed' | 'marketplace' | 'featured'

export function ExtensionManagerPanel() {
  const [searchQuery, setSearchQuery] = useState('')
  const [activeTab, setActiveTab] = useState<TabValue>('installed')
  const [extensions, setExtensions] = useState<Extension[]>([])
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    loadExtensions()
  }, [activeTab])

  const loadExtensions = async () => {
    setLoading(true)

    try {
      const endpoint =
        activeTab === 'installed'
          ? '/api/extensions/installed'
          : activeTab === 'featured'
            ? '/api/extensions/featured'
            : '/api/extensions/marketplace'

      const response = await fetch(endpoint)
      if (response.ok) {
        const data = await response.json()
        setExtensions(data.extensions || getMockExtensions())
      } else {
        setExtensions(getMockExtensions())
      }
    } catch (error) {
      console.error('Failed to load extensions:', error)
      setExtensions(getMockExtensions())
    } finally {
      setLoading(false)
    }
  }

  const getMockExtensions = (): Extension[] => {
    const mockExtensions: Extension[] = [
      {
        id: 'theme-dracula',
        name: 'Dracula Theme',
        author: 'Dracula Theme',
        version: '2.24.2',
        description: 'Official Dracula Theme. A dark theme for many editors, shells, and more.',
        rating: 4.8,
        downloads: 5420000,
        category: 'Themes',
        tags: ['theme', 'dark', 'dracula'],
        installed: true,
        enabled: true,
        featured: true,
      },
      {
        id: 'prettier',
        name: 'Prettier - Code formatter',
        author: 'Prettier',
        version: '10.1.0',
        description: 'Code formatter using prettier. Supports many languages.',
        rating: 4.7,
        downloads: 28500000,
        category: 'Formatters',
        tags: ['formatter', 'prettier', 'javascript'],
        installed: true,
        enabled: true,
        featured: true,
      },
      {
        id: 'eslint',
        name: 'ESLint',
        author: 'Microsoft',
        version: '2.4.2',
        description: 'Integrates ESLint JavaScript into VS Code.',
        rating: 4.6,
        downloads: 24800000,
        category: 'Linters',
        tags: ['linter', 'eslint', 'javascript'],
        installed: true,
        enabled: false,
      },
      {
        id: 'git-graph',
        name: 'Git Graph',
        author: 'mhutchie',
        version: '1.30.0',
        description: 'View a Git Graph of your repository, and perform Git actions from the graph.',
        rating: 4.9,
        downloads: 4100000,
        category: 'Source Control',
        tags: ['git', 'graph', 'visualization'],
        installed: false,
        enabled: false,
        featured: true,
      },
      {
        id: 'docker',
        name: 'Docker',
        author: 'Microsoft',
        version: '1.26.0',
        description: 'Makes it easy to create, manage, and debug containerized applications.',
        rating: 4.5,
        downloads: 15300000,
        category: 'Containers',
        tags: ['docker', 'containers', 'devops'],
        installed: false,
        enabled: false,
      },
      {
        id: 'copilot',
        name: 'GitHub Copilot',
        author: 'GitHub',
        version: '1.120.0',
        description: 'Your AI pair programmer. Get suggestions for whole lines or entire functions.',
        rating: 4.4,
        downloads: 12000000,
        category: 'AI',
        tags: ['ai', 'copilot', 'autocomplete'],
        installed: false,
        enabled: false,
        featured: true,
      },
    ]

    if (activeTab === 'installed') {
      return mockExtensions.filter((ext) => ext.installed)
    } else if (activeTab === 'featured') {
      return mockExtensions.filter((ext) => ext.featured)
    }

    return mockExtensions
  }

  const installExtension = async (extensionId: string) => {
    try {
      await fetch('/api/extensions/install', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ extensionId }),
      })

      setExtensions((prev) =>
        prev.map((ext) =>
          ext.id === extensionId
            ? { ...ext, installed: true, enabled: true }
            : ext
        )
      )
    } catch (error) {
      console.error('Failed to install extension:', error)
      alert('Failed to install extension')
    }
  }

  const uninstallExtension = async (extensionId: string) => {
    try {
      await fetch('/api/extensions/uninstall', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ extensionId }),
      })

      setExtensions((prev) =>
        prev.map((ext) =>
          ext.id === extensionId
            ? { ...ext, installed: false, enabled: false }
            : ext
        )
      )
    } catch (error) {
      console.error('Failed to uninstall extension:', error)
      alert('Failed to uninstall extension')
    }
  }

  const toggleExtension = async (extensionId: string) => {
    const extension = extensions.find((ext) => ext.id === extensionId)
    if (!extension) return

    try {
      await fetch('/api/extensions/toggle', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ extensionId, enabled: !extension.enabled }),
      })

      setExtensions((prev) =>
        prev.map((ext) =>
          ext.id === extensionId ? { ...ext, enabled: !ext.enabled } : ext
        )
      )
    } catch (error) {
      console.error('Failed to toggle extension:', error)
    }
  }

  const filteredExtensions = extensions.filter((ext) => {
    if (!searchQuery.trim()) return true

    const query = searchQuery.toLowerCase()
    return (
      ext.name.toLowerCase().includes(query) ||
      ext.description.toLowerCase().includes(query) ||
      ext.tags.some((tag) => tag.toLowerCase().includes(query))
    )
  })

  const renderRating = (rating: number) => {
    return (
      <div className="flex items-center gap-1">
        {[...Array(5)].map((_, i) => (
          <Star
            key={i}
            className={`w-3 h-3 ${i < Math.floor(rating) ? 'fill-[#f59e0b] text-[#f59e0b]' : 'text-[#858585]'}`}
          />
        ))}
        <span className="ml-1">{rating.toFixed(1)}</span>
      </div>
    )
  }

  const formatDownloads = (count: number): string => {
    if (count >= 1000000) {
      return `${(count / 1000000).toFixed(1)}M`
    } else if (count >= 1000) {
      return `${(count / 1000).toFixed(1)}K`
    }
    return count.toString()
  }

  return (
    <div className="flex flex-col h-full bg-[#1e1e1e] text-[#cccccc]">
      <div className="flex items-center gap-2 px-3 py-3 border-b border-[#3c3c3c]">
        <Plug className="w-[18px] h-[18px]" />
        <span className="text-sm font-semibold text-white">Extension Manager</span>
      </div>

      <div className="px-3 py-3 border-b border-[#3c3c3c]">
        <div className="relative">
          <Search className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-[#858585]" />
          <Input
            placeholder="Search extensions..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-8"
          />
        </div>
      </div>

      <Tabs value={activeTab} onValueChange={(value) => setActiveTab(value as TabValue)} className="flex flex-col flex-1">
        <div className="px-3 py-2 border-b border-[#3c3c3c]">
          <TabsList>
            <TabsTrigger value="installed">Installed</TabsTrigger>
            <TabsTrigger value="marketplace">Marketplace</TabsTrigger>
            <TabsTrigger value="featured">Featured</TabsTrigger>
          </TabsList>
        </div>

        <TabsContent value={activeTab} className="flex-1 overflow-auto px-3 py-3">
          {loading && (
            <div className="flex flex-col items-center gap-3 px-5 py-10">
              <Spinner size="md" />
              <span>Loading extensions...</span>
            </div>
          )}

          {!loading && filteredExtensions.length === 0 && (
            <div className="px-5 py-10 text-center text-[#858585] text-[13px]">
              {searchQuery
                ? `No extensions found for "${searchQuery}"`
                : activeTab === 'installed'
                  ? 'No extensions installed. Browse the marketplace to discover extensions.'
                  : 'No extensions available.'}
            </div>
          )}

          {!loading &&
            filteredExtensions.map((extension) => (
              <div
                key={extension.id}
                className="bg-[#252526] border border-[#3c3c3c] rounded p-4 mb-3 hover:border-[#4fc3f7] hover:bg-[#2b2b2b] transition-colors"
              >
                <div className="flex items-start gap-3 mb-3">
                  <div className="w-12 h-12 min-w-[48px] rounded bg-[#4fc3f7] flex items-center justify-center text-2xl text-white">
                    <Plug />
                  </div>

                  <div className="flex-1 min-w-0">
                    <div className="text-sm font-semibold text-white mb-1">{extension.name}</div>
                    <div className="text-[11px] text-[#858585] mb-1">
                      {extension.author} • v{extension.version}
                    </div>
                  </div>

                  {extension.installed && (
                    <Switch
                      checked={extension.enabled}
                      onCheckedChange={() => toggleExtension(extension.id)}
                    />
                  )}
                </div>

                <div className="text-xs text-[#cccccc] leading-relaxed mt-2">
                  {extension.description}
                </div>

                <div className="flex items-center gap-3 text-[11px] text-[#858585] mt-2">
                  {renderRating(extension.rating)}
                  <span>•</span>
                  <span>{formatDownloads(extension.downloads)} downloads</span>
                  <span>•</span>
                  <Badge variant="secondary" className="text-[10px]">
                    {extension.category}
                  </Badge>
                </div>

                <div className="flex gap-2 mt-3">
                  {!extension.installed ? (
                    <Button
                      size="sm"
                      onClick={() => installExtension(extension.id)}
                    >
                      <Download className="w-3 h-3 mr-1" />
                      Install
                    </Button>
                  ) : (
                    <>
                      <Button
                        size="sm"
                        variant="ghost"
                      >
                        <Settings className="w-3 h-3 mr-1" />
                        Settings
                      </Button>
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => uninstallExtension(extension.id)}
                      >
                        <Trash2 className="w-3 h-3 mr-1" />
                        Uninstall
                      </Button>
                    </>
                  )}
                </div>
              </div>
            ))}
        </TabsContent>
      </Tabs>
    </div>
  )
}

import React, { useState, useEffect } from 'react'
import { Button, Spinner } from '@persona-framework/ui'
import { AlertTriangle, RefreshCw, Flag } from 'lucide-react'
import { makeHttpClient } from '../../../data/https'

const http = makeHttpClient('/api')

const STORAGE_KEY = 'wraith_sprint_project_id'

function getStoredProjectId(): number {
  try {
    const stored = localStorage.getItem(STORAGE_KEY)
    if (stored) {
      const parsed = parseInt(stored, 10)
      if (!isNaN(parsed) && parsed > 0) return parsed
    }
  } catch {
    // Ignore storage errors
  }
  return 1 // Default project ID
}

interface SprintPanelProps {
  projectId?: number
}

interface Sprint {
  id: number
  projectId: number
  name: string
  goal?: string
  startDate: string
  endDate: string
  status: 'PLANNED' | 'ACTIVE' | 'COMPLETED'
}

interface SprintStats {
  sprintId: number
  sprintName: string
  status: 'PLANNED' | 'ACTIVE' | 'COMPLETED'
  totalTasks: number
  completedTasks: number
  remainingTasks: number
  completionPercentage: number
  totalStoryPoints: number
  completedStoryPoints: number
  remainingStoryPoints: number
  daysRemaining: number
  averageVelocity: number
  warnings: string[]
  isOverCommitted: boolean
  isUnderCommitted: boolean
}

interface Task {
  id: number
  title: string
  status: string
  storyPoints?: number
  assignee?: string
}

interface VelocityDataPoint {
  sprintId: number
  sprintName: string
  completedPoints: number
  plannedPoints: number
  completionRate: number
}

export function SprintPanel({ projectId: propProjectId }: SprintPanelProps = {}) {
  const [activeSprint, setActiveSprint] = useState<Sprint | null>(null)
  const [stats, setStats] = useState<SprintStats | null>(null)
  const [tasks, setTasks] = useState<Task[]>([])
  const [velocity, setVelocity] = useState<VelocityDataPoint[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // Use prop if provided, otherwise use stored/default
  const projectId = propProjectId ?? getStoredProjectId()

  const fetchActiveSprint = async () => {
    try {
      setLoading(true)
      setError(null)

      const sprintResponse = await http.get(`/nexus/sprints/project/${projectId}/active`)
      if (sprintResponse.ok) {
        const sprint = await sprintResponse.json()
        setActiveSprint(sprint)

        const statsResponse = await http.get(`/nexus/sprints/${sprint.id}/stats`)
        if (statsResponse.ok) {
          const sprintStats = await statsResponse.json()
          setStats(sprintStats)
        }

        const tasksResponse = await http.get(`/nexus/sprints/${sprint.id}/tasks`)
        if (tasksResponse.ok) {
          const sprintTasks = await tasksResponse.json()
          setTasks(sprintTasks)
        }

        const velocityResponse = await http.get(`/nexus/sprints/project/${projectId}/velocity?limit=5`)
        if (velocityResponse.ok) {
          const velocityData = await velocityResponse.json()
          setVelocity(velocityData)
        }
      } else if (sprintResponse.status === 404) {
        setActiveSprint(null)
        setStats(null)
        setTasks([])
      } else {
        setError('Failed to fetch sprint data')
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchActiveSprint()
    const interval = setInterval(fetchActiveSprint, 30000)
    return () => clearInterval(interval)
  }, [projectId])

  if (loading && !activeSprint) {
    return (
      <div className="flex flex-col h-full bg-[#1e1e1e] text-[#cccccc] overflow-hidden">
        <div className="flex flex-col items-center justify-center h-full gap-3">
          <Spinner size="lg" />
          <div className="text-sm text-[#b0b0b0]">Loading sprint...</div>
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className="flex flex-col h-full bg-[#1e1e1e] text-[#cccccc] overflow-hidden">
        <div className="flex flex-col items-center justify-center h-full p-6">
          <div className="p-3 bg-[#5a1d1d] rounded-full mb-4">
            <AlertTriangle className="w-8 h-8 text-[#f48771]" />
          </div>
          <div className="text-sm text-[#f48771] font-medium mb-2">Failed to load sprint</div>
          <div className="text-xs text-[#858585] text-center mb-4 max-w-[200px]">{error}</div>
          <Button size="sm" variant="outline" onClick={() => fetchActiveSprint()}>
            <RefreshCw className="w-3.5 h-3.5 mr-1.5" />
            Retry
          </Button>
        </div>
      </div>
    )
  }

  if (!activeSprint) {
    return (
      <div className="flex flex-col h-full bg-[#1e1e1e] text-[#cccccc] overflow-hidden">
        <div className="flex flex-col items-center justify-center h-full p-6">
          <div className="p-3 bg-[#252526] rounded-full mb-4">
            <Flag className="w-8 h-8 text-[#858585]" />
          </div>
          <div className="text-sm text-[#cccccc] font-medium mb-1">No active sprint</div>
          <div className="text-xs text-[#858585] text-center">Start a sprint to see progress here</div>
        </div>
      </div>
    )
  }

  const getStatusClass = (status: string) => {
    switch (status) {
      case 'ACTIVE':
        return 'bg-[rgba(0,255,127,0.2)] text-[#00ff7f] border border-[#00ff7f]'
      case 'PLANNED':
        return 'bg-[rgba(91,206,250,0.2)] text-[#5bcefa] border border-[#5bcefa]'
      case 'COMPLETED':
        return 'bg-[rgba(157,0,255,0.2)] text-[#9d00ff] border border-[#9d00ff]'
      default:
        return ''
    }
  }

  const maxVelocity = Math.max(...velocity.map(v => v.completedPoints), 1)

  return (
    <div className="flex flex-col h-full bg-[#1e1e1e] text-[#cccccc] overflow-hidden">
      <div className="p-4 border-b border-[#3c3c3c] bg-[#252526]">
        <div className="text-lg font-semibold text-white mb-2">
          🏃 {activeSprint.name}
        </div>
        {activeSprint.goal && (
          <div className="text-[13px] text-[#b0b0b0] mb-3 italic">
            "{activeSprint.goal}"
          </div>
        )}
        <span className={`inline-block px-3 py-1 rounded-xl text-[11px] font-semibold uppercase ${getStatusClass(activeSprint.status)}`}>
          {activeSprint.status}
        </span>
        <div className="text-[11px] text-[#808080] mt-2">
          {new Date(activeSprint.startDate).toLocaleDateString()} - {new Date(activeSprint.endDate).toLocaleDateString()}
          {stats && ` • ${stats.daysRemaining} days remaining`}
        </div>
      </div>

      {stats && stats.warnings.length > 0 && (
        <div className="p-4 pb-0">
          {stats.warnings.map((warning, idx) => (
            <div key={idx} className="p-3 bg-[rgba(255,215,0,0.1)] border border-[#ffd700] rounded-md mb-4">
              <div className="text-xs text-[#ffd700]">⚠️ {warning}</div>
            </div>
          ))}
        </div>
      )}

      {stats && (
        <div className="grid grid-cols-2 gap-3 p-4 border-b border-[#3c3c3c]">
          <div className="p-3 bg-[#252526] rounded-md border border-[#3c3c3c]">
            <div className="text-[11px] text-[#808080] uppercase mb-1.5">Progress</div>
            <div className="text-2xl font-bold text-white">{stats.completionPercentage}%</div>
            <div className="text-[11px] text-[#b0b0b0] mt-1">
              {stats.completedTasks} of {stats.totalTasks} tasks
            </div>
            <div className="h-1.5 bg-[#3c3c3c] rounded-sm overflow-hidden mt-2">
              <div
                className="h-full bg-[#00ff7f] transition-all duration-300"
                style={{ width: `${stats.completionPercentage}%` }}
              />
            </div>
          </div>

          <div className="p-3 bg-[#252526] rounded-md border border-[#3c3c3c]">
            <div className="text-[11px] text-[#808080] uppercase mb-1.5">Story Points</div>
            <div className="text-2xl font-bold text-white">{stats.completedStoryPoints.toFixed(0)}</div>
            <div className="text-[11px] text-[#b0b0b0] mt-1">
              of {stats.totalStoryPoints.toFixed(0)} points
            </div>
            <div className="h-1.5 bg-[#3c3c3c] rounded-sm overflow-hidden mt-2">
              <div
                className="h-full bg-[#9d00ff] transition-all duration-300"
                style={{
                  width: `${(stats.completedStoryPoints / stats.totalStoryPoints) * 100}%`
                }}
              />
            </div>
          </div>
        </div>
      )}

      <div className="flex-1 overflow-auto p-4">
        <div className="mb-6">
          <div className="text-sm font-semibold text-white mb-3 flex items-center gap-2">
            📋 Sprint Tasks ({tasks.length})
          </div>
          {tasks.length > 0 ? (
            <div className="flex flex-col gap-2">
              {tasks.map(task => (
                <div key={task.id} className="p-3 bg-[#252526] rounded-md border border-[#3c3c3c] cursor-pointer transition-all hover:bg-[#2d2d30] hover:border-[#5bcefa]">
                  <div className="text-[13px] text-white mb-1">{task.title}</div>
                  <div className="text-[11px] text-[#808080]">
                    {task.status}
                    {task.storyPoints && ` • ${task.storyPoints} pts`}
                    {task.assignee && ` • ${task.assignee}`}
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="text-center py-5 text-[#808080] text-xs">
              No tasks in this sprint
            </div>
          )}
        </div>

        {velocity.length > 0 && (
          <div className="mb-6">
            <div className="text-sm font-semibold text-white mb-3 flex items-center gap-2">
              📈 Team Velocity (Last 5 Sprints)
            </div>
            <div className="mt-4 p-4 bg-[#252526] rounded-md border border-[#3c3c3c]">
              <div className="flex items-end gap-3 h-[120px] mt-4">
                {velocity.map(point => (
                  <div key={point.sprintId} className="flex-1 flex flex-col items-center gap-2">
                    <div
                      className="w-full bg-[#5bcefa] rounded-t transition-all duration-300"
                      style={{
                        height: `${(point.completedPoints / maxVelocity) * 100}%`,
                        minHeight: '4px'
                      }}
                      title={`${point.completedPoints} pts completed`}
                    />
                    <div className="text-[10px] text-[#808080] text-center">
                      {point.sprintName.substring(0, 10)}...
                      <br />
                      {point.completedPoints.toFixed(0)} pts
                    </div>
                  </div>
                ))}
              </div>
              {stats && (
                <div className="mt-4 text-xs text-[#b0b0b0] text-center">
                  Average Velocity: {stats.averageVelocity.toFixed(1)} points/sprint
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

