import React from 'react'
import { Spinner, Button, Input, Badge, Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from '@persona-framework/ui'
import { getDefaultApiClient } from '@shared/api/client'
import { Filter, Search, RefreshCw, Maximize, Circle } from 'lucide-react'

interface LogEntry {
  timestamp: string
  level: 'DEBUG' | 'INFO' | 'WARN' | 'ERROR'
  logger: string
  thread: string
  message: string
  stackTrace?: string
}

interface LogsPanelProps {
  onOpenFullScreen?: () => void
}

type ConnectionStatus = 'connected' | 'connecting' | 'disconnected'

export function LogsPanel({ onOpenFullScreen }: LogsPanelProps = {}) {
  const [logs, setLogs] = React.useState<LogEntry[]>([])
  const [levelFilter, setLevelFilter] = React.useState('ALL')
  const [searchQuery, setSearchQuery] = React.useState('')
  const [loggerFilter, setLoggerFilter] = React.useState('')
  const [connectionStatus, setConnectionStatus] = React.useState<ConnectionStatus>('connecting')
  const [isLoading, setIsLoading] = React.useState(true)
  const scrollRef = React.useRef<HTMLDivElement>(null)
  const eventSourceRef = React.useRef<EventSource | null>(null)
  const autoScrollRef = React.useRef(true)

  React.useEffect(() => {
    const loadInitialLogs = async () => {
      try {
        const client = getDefaultApiClient()
        const params: Record<string, any> = { limit: 500 }
        if (levelFilter !== 'ALL') params.level = levelFilter
        if (searchQuery) params.message = searchQuery
        if (loggerFilter) params.logger = loggerFilter

        const res = await client.get('/api/logs/recent', { params })
        const recentLogs = res?.data?.logs || []
        setLogs(recentLogs)
        setIsLoading(false)
      } catch (error) {
        console.error('Failed to load initial logs:', error)
        setLogs([])
        setIsLoading(false)
      }
    }

    loadInitialLogs()
  }, [levelFilter, searchQuery, loggerFilter])

  React.useEffect(() => {
    const baseUrl = getDefaultApiClient().defaults.baseURL || 'http://localhost:8989'
    const sseUrl = `${baseUrl}/api/logs/stream`

    setConnectionStatus('connecting')

    const eventSource = new EventSource(sseUrl)
    eventSourceRef.current = eventSource

    eventSource.addEventListener('connected', (event) => {
      console.log('SSE connected:', event.data)
      setConnectionStatus('connected')
    })

    eventSource.addEventListener('log', (event) => {
      try {
        const logEntry: LogEntry = JSON.parse(event.data)

        const passesLevelFilter = levelFilter === 'ALL' || logEntry.level === levelFilter
        const passesLoggerFilter = !loggerFilter || logEntry.logger.toLowerCase().includes(loggerFilter.toLowerCase())
        const passesSearchFilter = !searchQuery || logEntry.message.toLowerCase().includes(searchQuery.toLowerCase())

        if (passesLevelFilter && passesLoggerFilter && passesSearchFilter) {
          setLogs(prev => {
            const newLogs = [...prev, logEntry].slice(-500)
            return newLogs
          })
        }
      } catch (error) {
        console.error('Failed to parse log event:', error)
      }
    })

    eventSource.addEventListener('heartbeat', () => {
    })

    eventSource.onerror = (error) => {
      console.error('SSE error:', error)
      setConnectionStatus('disconnected')

      setTimeout(() => {
        if (eventSource.readyState === EventSource.CONNECTING) {
          setConnectionStatus('connecting')
        }
      }, 1000)
    }

    eventSource.onopen = () => {
      setConnectionStatus('connected')
    }

    return () => {
      eventSource.close()
      eventSourceRef.current = null
    }
  }, [levelFilter, searchQuery, loggerFilter])

  React.useEffect(() => {
    if (scrollRef.current && autoScrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight
    }
  }, [logs])

  const handleScroll = React.useCallback(() => {
    if (scrollRef.current) {
      const { scrollTop, scrollHeight, clientHeight } = scrollRef.current
      const isAtBottom = scrollHeight - scrollTop - clientHeight < 50
      autoScrollRef.current = isAtBottom
    }
  }, [])

  const handleRefresh = async () => {
    setIsLoading(true)
    try {
      const client = getDefaultApiClient()
      const params: Record<string, any> = { limit: 500 }
      if (levelFilter !== 'ALL') params.level = levelFilter
      if (searchQuery) params.message = searchQuery
      if (loggerFilter) params.logger = loggerFilter

      const res = await client.get('/api/logs/recent', { params })
      const recentLogs = res?.data?.logs || []
      setLogs(recentLogs)
    } catch (error) {
      console.error('Failed to refresh logs:', error)
    } finally {
      setIsLoading(false)
    }
  }

  const handleClearLogs = async () => {
    try {
      const client = getDefaultApiClient()
      await client.post('/api/logs/clear')
      setLogs([])
    } catch (error) {
      console.error('Failed to clear logs:', error)
    }
  }

  const getLevelColor = (level: string) => {
    switch (level.toUpperCase()) {
      case 'ERROR': return '#f48771'
      case 'WARN': return '#fbbf24'
      case 'INFO': return '#60a5fa'
      case 'DEBUG': return '#a78bfa'
      default: return '#cccccc'
    }
  }

  const getLevelBadgeVariant = (level: string): "default" | "secondary" | "destructive" | "outline" => {
    switch (level.toUpperCase()) {
      case 'ERROR': return 'destructive'
      case 'WARN': return 'default'
      case 'INFO': return 'secondary'
      default: return 'outline'
    }
  }

  const getStatusColor = () => {
    switch (connectionStatus) {
      case 'connected': return 'text-green-500'
      case 'connecting': return 'text-amber-500'
      case 'disconnected': return 'text-red-500'
    }
  }

  const getStatusText = () => {
    switch (connectionStatus) {
      case 'connected': return 'Connected'
      case 'connecting': return 'Connecting...'
      case 'disconnected': return 'Disconnected'
    }
  }

  if (isLoading) {
    return (
      <div className="flex flex-col h-full bg-[#1e1e1e] text-[#cccccc]">
        <div className="px-3 py-2 border-b border-[#3c3c3c] text-[13px] font-semibold">
          Server Logs
        </div>
        <div className="p-4 flex justify-center">
          <Spinner size="sm" />
          <span className="ml-2 text-sm">Loading logs...</span>
        </div>
      </div>
    )
  }

  return (
    <div className="flex flex-col h-full bg-[#1e1e1e] text-[#cccccc]">
      <div className="px-3 py-2 border-b border-[#3c3c3c] text-[13px] font-semibold flex justify-between items-center">
        <div className="flex items-center">
          <span>Server Logs</span>
          <div className="ml-3 text-[11px] flex items-center">
            <Circle className={`w-2 h-2 mr-1.5 fill-current ${getStatusColor()}`} />
            <span className="text-[#858585]">{getStatusText()}</span>
          </div>
        </div>
        {onOpenFullScreen && (
          <Button
            variant="ghost"
            size="sm"
            onClick={onOpenFullScreen}
            title="Open full-screen logs viewer"
          >
            <Maximize className="w-4 h-4" />
          </Button>
        )}
      </div>
      <div className="p-2 border-b border-[#3c3c3c] flex flex-col gap-1.5">
        <div className="flex gap-1 flex-wrap">
          <Select value={levelFilter} onValueChange={setLevelFilter}>
            <SelectTrigger className="w-20 h-7 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="ALL">All</SelectItem>
              <SelectItem value="ERROR">ERROR</SelectItem>
              <SelectItem value="WARN">WARN</SelectItem>
              <SelectItem value="INFO">INFO</SelectItem>
              <SelectItem value="DEBUG">DEBUG</SelectItem>
            </SelectContent>
          </Select>
          <div className="relative w-[100px]">
            <Search className="absolute left-2 top-1/2 -translate-y-1/2 w-3 h-3 text-gray-400" />
            <Input
              className="h-7 text-xs pl-7"
              placeholder="Search..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <div className="relative w-[90px]">
            <Filter className="absolute left-2 top-1/2 -translate-y-1/2 w-3 h-3 text-gray-400" />
            <Input
              className="h-7 text-xs pl-7"
              placeholder="Logger..."
              value={loggerFilter}
              onChange={(e) => setLoggerFilter(e.target.value)}
            />
          </div>
          <Button
            size="sm"
            variant="ghost"
            onClick={handleRefresh}
            title="Refresh logs"
            className="h-7 px-2"
          >
            <RefreshCw className="w-3 h-3" />
          </Button>
          <Button
            size="sm"
            variant="ghost"
            onClick={handleClearLogs}
            title="Clear log buffer"
            className="h-7 text-xs"
          >
            Clear
          </Button>
        </div>
        <div className="text-[10px] text-[#858585]">
          {logs.length} entries • Live streaming
        </div>
      </div>
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-2 font-mono text-[11px]" onScroll={handleScroll}>
        {logs.length === 0 ? (
          <div className="text-[#858585] text-center p-4">
            No logs found
          </div>
        ) : (
          logs.map((log, idx) => {
            const timestamp = log.timestamp?.includes('T') ? log.timestamp : null
            const loggerShortName = log.logger && log.logger !== 'unknown'
              ? log.logger.split('.').slice(-2).join('.')
              : 'system'

            return (
              <div
                key={`${log.timestamp}-${idx}`}
                className={`px-2 py-1 rounded-sm mb-0.5 whitespace-pre-wrap break-words ${
                  log.level === 'ERROR' ? 'bg-[#2d1e1e]' : log.level === 'WARN' ? 'bg-[#2d2a1e]' : ''
                }`}
              >
                <div className="flex gap-1.5 items-center mb-0.5 flex-wrap">
                  {timestamp && (
                    <span className="text-[#858585] text-[10px]">
                      {new Date(timestamp).toLocaleTimeString()}
                    </span>
                  )}
                  <Badge variant={getLevelBadgeVariant(log.level)} className="text-[10px] px-1.5 py-0">
                    {log.level}
                  </Badge>
                  <span className="text-[#858585] text-[10px]">
                    {loggerShortName}
                  </span>
                  {log.thread && (
                    <span className="text-[#858585] text-[9px]">
                      [{log.thread}]
                    </span>
                  )}
                </div>
                <div style={{ color: getLevelColor(log.level) }}>
                  {log.message}
                </div>
                {log.stackTrace && (
                  <div className="text-[#f48771] text-[10px] mt-1 pl-2 border-l-2 border-[#f48771]">
                    {log.stackTrace}
                  </div>
                )}
              </div>
            )
          })
        )}
      </div>
    </div>
  )
}

