import React, { useState, useEffect } from 'react'
import { Button, Checkbox, Input, Label, Spinner, Accordion, AccordionItem, AccordionTrigger, AccordionContent } from '@persona-framework/ui'
import {
  Play,
  FileText,
  Settings,
  Plus,
  Trash2,
} from 'lucide-react'

interface ServiceConfig {
  name: string
  enabled: boolean
  image?: string
  build?: string
  ports: string[]
  volumes: string[]
  environment: { key: string; value: string }[]
  dependsOn: string[]
}

export function DockerComposePanel() {
  const [services, setServices] = useState<ServiceConfig[]>([])
  const [loading, setLoading] = useState(true)
  const [generatedCompose, setGeneratedCompose] = useState<string>('')
  const [showPreview, setShowPreview] = useState(false)

  useEffect(() => {
    fetchServices()
  }, [])

  const fetchServices = async () => {
    setLoading(true)
    try {
      const response = await fetch('/api/docker/detect-services')
      if (response.ok) {
        const data = await response.json()
        setServices(data.services || [])
      } else {
        setServices([
          {
            name: 'persona-framework',
            enabled: true,
            build: '.',
            ports: ['8080:8080'],
            volumes: ['./:/workspace'],
            environment: [{ key: 'SPRING_PROFILES_ACTIVE', value: 'dev' }],
            dependsOn: ['postgres'],
          },
          {
            name: 'postgres',
            enabled: true,
            image: 'postgres:15-alpine',
            ports: ['5432:5432'],
            volumes: ['postgres-data:/var/lib/postgresql/data'],
            environment: [
              { key: 'POSTGRES_DB', value: 'hydra' },
              { key: 'POSTGRES_USER', value: 'hydra' },
              { key: 'POSTGRES_PASSWORD', value: 'hydra' },
            ],
            dependsOn: [],
          },
        ])
      }
    } catch (error) {
      console.error('Failed to fetch services:', error)
      setServices([])
    } finally {
      setLoading(false)
    }
  }

  const toggleService = (index: number) => {
    setServices(prev => prev.map((s, i) => i === index ? { ...s, enabled: !s.enabled } : s))
  }

  const updateService = (index: number, field: keyof ServiceConfig, value: any) => {
    setServices(prev => prev.map((s, i) => i === index ? { ...s, [field]: value } : s))
  }

  const addPort = (index: number) => {
    setServices(prev => prev.map((s, i) =>
      i === index ? { ...s, ports: [...s.ports, ''] } : s
    ))
  }

  const updatePort = (serviceIndex: number, portIndex: number, value: string) => {
    setServices(prev => prev.map((s, i) =>
      i === serviceIndex ? {
        ...s,
        ports: s.ports.map((p, pi) => pi === portIndex ? value : p)
      } : s
    ))
  }

  const removePort = (serviceIndex: number, portIndex: number) => {
    setServices(prev => prev.map((s, i) =>
      i === serviceIndex ? {
        ...s,
        ports: s.ports.filter((_, pi) => pi !== portIndex)
      } : s
    ))
  }

  const addVolume = (index: number) => {
    setServices(prev => prev.map((s, i) =>
      i === index ? { ...s, volumes: [...s.volumes, ''] } : s
    ))
  }

  const updateVolume = (serviceIndex: number, volumeIndex: number, value: string) => {
    setServices(prev => prev.map((s, i) =>
      i === serviceIndex ? {
        ...s,
        volumes: s.volumes.map((v, vi) => vi === volumeIndex ? value : v)
      } : s
    ))
  }

  const removeVolume = (serviceIndex: number, volumeIndex: number) => {
    setServices(prev => prev.map((s, i) =>
      i === serviceIndex ? {
        ...s,
        volumes: s.volumes.filter((_, vi) => vi !== volumeIndex)
      } : s
    ))
  }

  const addEnvVar = (index: number) => {
    setServices(prev => prev.map((s, i) =>
      i === index ? { ...s, environment: [...s.environment, { key: '', value: '' }] } : s
    ))
  }

  const updateEnvVar = (serviceIndex: number, envIndex: number, field: 'key' | 'value', value: string) => {
    setServices(prev => prev.map((s, i) =>
      i === serviceIndex ? {
        ...s,
        environment: s.environment.map((e, ei) =>
          ei === envIndex ? { ...e, [field]: value } : e
        )
      } : s
    ))
  }

  const removeEnvVar = (serviceIndex: number, envIndex: number) => {
    setServices(prev => prev.map((s, i) =>
      i === serviceIndex ? {
        ...s,
        environment: s.environment.filter((_, ei) => ei !== envIndex)
      } : s
    ))
  }

  const generateCompose = () => {
    const enabledServices = services.filter(s => s.enabled)

    if (enabledServices.length === 0) {
      setGeneratedCompose('# No services selected\n')
      setShowPreview(true)
      return
    }

    let yaml = 'version: "3.8"\n\nservices:\n'

    enabledServices.forEach(service => {
      yaml += `  ${service.name}:\n`

      if (service.image) {
        yaml += `    image: ${service.image}\n`
      }

      if (service.build) {
        yaml += `    build: ${service.build}\n`
      }

      if (service.ports.length > 0) {
        yaml += `    ports:\n`
        service.ports.forEach(port => {
          if (port.trim()) yaml += `      - "${port}"\n`
        })
      }

      if (service.volumes.length > 0) {
        yaml += `    volumes:\n`
        service.volumes.forEach(volume => {
          if (volume.trim()) yaml += `      - ${volume}\n`
        })
      }

      if (service.environment.length > 0) {
        yaml += `    environment:\n`
        service.environment.forEach(env => {
          if (env.key.trim()) yaml += `      ${env.key}: ${env.value}\n`
        })
      }

      if (service.dependsOn.length > 0) {
        yaml += `    depends_on:\n`
        service.dependsOn.forEach(dep => {
          yaml += `      - ${dep}\n`
        })
      }

      yaml += '\n'
    })

    yaml += 'volumes:\n'
    yaml += '  postgres-data:\n'

    setGeneratedCompose(yaml)
    setShowPreview(true)
  }

  const saveCompose = async () => {
    try {
      const response = await fetch('/api/docker/save-compose', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ content: generatedCompose }),
      })

      if (response.ok) {
        alert('docker-compose.yml saved successfully!')
      } else {
        alert('Failed to save docker-compose.yml')
      }
    } catch (error) {
      console.error('Save error:', error)
      alert('Failed to save docker-compose.yml')
    }
  }

  if (loading) {
    return (
      <div className="flex flex-col h-full bg-[#1e1e1e] text-[#cccccc] overflow-auto">
        <div className="px-4 py-3 border-b border-[#3c3c3c] text-sm font-semibold">
          Docker Compose Generator
        </div>
        <div className="flex flex-col items-center gap-3 px-5 py-10">
          <Spinner size="md" />
          <span>Detecting services...</span>
        </div>
      </div>
    )
  }

  return (
    <div className="flex flex-col h-full bg-[#1e1e1e] text-[#cccccc] overflow-auto">
      <div className="px-4 py-3 border-b border-[#3c3c3c] text-sm font-semibold">
        Docker Compose Generator
      </div>

      <div className="flex flex-col gap-4 p-4">
        {services.map((service, serviceIndex) => (
          <Accordion key={serviceIndex} type="single" collapsible className="w-full">
            <AccordionItem value={serviceIndex.toString()}>
              <AccordionTrigger>
                <div className="flex items-center gap-3">
                  <Checkbox
                    checked={service.enabled}
                    onCheckedChange={() => toggleService(serviceIndex)}
                    onClick={(e) => e.stopPropagation()}
                  />
                  <span className="text-sm font-semibold text-[#4fc3f7]">{service.name}</span>
                </div>
              </AccordionTrigger>
              <AccordionContent>
                <div className="flex flex-col gap-2 ml-8">
                  <div className="flex gap-2 items-center">
                    <Label className="min-w-[80px] text-xs text-[#858585]">
                      {service.image ? 'Image' : 'Build'}
                    </Label>
                    <Input
                      className="flex-1 text-[11px]"
                      value={service.image || service.build || ''}
                      onChange={(e) =>
                        updateService(serviceIndex, service.image ? 'image' : 'build', e.target.value)
                      }
                      size="sm"
                    />
                  </div>

                  <div>
                    <Label className="min-w-[80px] text-xs text-[#858585]">Ports</Label>
                    {service.ports.map((port, portIndex) => (
                      <div key={portIndex} className="flex gap-1 items-center mt-1">
                        <Input
                          className="flex-1 text-[11px]"
                          value={port}
                          onChange={(e) => updatePort(serviceIndex, portIndex, e.target.value)}
                          placeholder="8080:8080"
                          size="sm"
                        />
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={() => removePort(serviceIndex, portIndex)}
                        >
                          <Trash2 className="w-3 h-3" />
                        </Button>
                      </div>
                    ))}
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => addPort(serviceIndex)}
                      className="mt-1"
                    >
                      <Plus className="w-3 h-3 mr-1" />
                      Add Port
                    </Button>
                  </div>

                  <div>
                    <Label className="min-w-[80px] text-xs text-[#858585]">Volumes</Label>
                    {service.volumes.map((volume, volumeIndex) => (
                      <div key={volumeIndex} className="flex gap-1 items-center mt-1">
                        <Input
                          className="flex-1 text-[11px]"
                          value={volume}
                          onChange={(e) => updateVolume(serviceIndex, volumeIndex, e.target.value)}
                          placeholder="./:/workspace"
                          size="sm"
                        />
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={() => removeVolume(serviceIndex, volumeIndex)}
                        >
                          <Trash2 className="w-3 h-3" />
                        </Button>
                      </div>
                    ))}
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => addVolume(serviceIndex)}
                      className="mt-1"
                    >
                      <Plus className="w-3 h-3 mr-1" />
                      Add Volume
                    </Button>
                  </div>

                  <div>
                    <Label className="min-w-[80px] text-xs text-[#858585]">Environment</Label>
                    {service.environment.map((env, envIndex) => (
                      <div key={envIndex} className="flex gap-1 items-center mt-1">
                        <Input
                          className="flex-1 text-[11px]"
                          value={env.key}
                          onChange={(e) => updateEnvVar(serviceIndex, envIndex, 'key', e.target.value)}
                          placeholder="KEY"
                          size="sm"
                        />
                        <Input
                          className="flex-1 text-[11px]"
                          value={env.value}
                          onChange={(e) => updateEnvVar(serviceIndex, envIndex, 'value', e.target.value)}
                          placeholder="value"
                          size="sm"
                        />
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={() => removeEnvVar(serviceIndex, envIndex)}
                        >
                          <Trash2 className="w-3 h-3" />
                        </Button>
                      </div>
                    ))}
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => addEnvVar(serviceIndex)}
                      className="mt-1"
                    >
                      <Plus className="w-3 h-3 mr-1" />
                      Add Variable
                    </Button>
                  </div>
                </div>
              </AccordionContent>
            </AccordionItem>
          </Accordion>
        ))}

        <div className="flex flex-col gap-3 border-t border-[#3c3c3c] pt-4">
          <Button
            onClick={generateCompose}
            disabled={services.filter(s => s.enabled).length === 0}
          >
            <Play className="w-4 h-4 mr-2" />
            Generate docker-compose.yml
          </Button>

          {showPreview && (
            <>
              <Label>Preview:</Label>
              <div className="bg-[#1e1e1e] border border-[#3c3c3c] rounded-md p-3 font-mono text-[11px] max-h-[300px] overflow-auto whitespace-pre-wrap break-words">
                {generatedCompose}
              </div>
              <Button
                variant="outline"
                onClick={saveCompose}
              >
                <FileText className="w-4 h-4 mr-2" />
                Save to Workspace
              </Button>
            </>
          )}
        </div>
      </div>
    </div>
  )
}

import React, { useState, useEffect, useRef } from 'react'
import { Button, Badge, Spinner, Progress } from '@persona-framework/ui'
import {
  Play,
  Square,
  Download,
} from 'lucide-react'

interface PerformanceMetrics {
  cpu: number
  memory: number
  fps: number
  networkRequests: number
}

interface HotSpot {
  name: string
  time: number
  percentage: number
  file: string
  line: number
}

export function PerformanceMonitorPanel() {
  const [profiling, setProfiling] = useState(false)
  const [metrics, setMetrics] = useState<PerformanceMetrics>({
    cpu: 0,
    memory: 0,
    fps: 0,
    networkRequests: 0,
  })
  const [cpuHistory, setCpuHistory] = useState<number[]>([])
  const [memoryHistory, setMemoryHistory] = useState<number[]>([])
  const [hotspots, setHotspots] = useState<HotSpot[]>([])
  const canvasRef = useRef<HTMLCanvasElement>(null)

  useEffect(() => {
    if (!profiling) return

    const interval = setInterval(() => {
      const newCpu = Math.random() * 100
      const newMemory = 40 + Math.random() * 40
      const newFps = 55 + Math.random() * 10

      setMetrics({
        cpu: Math.round(newCpu),
        memory: Math.round(newMemory),
        fps: Math.round(newFps),
        networkRequests: Math.floor(Math.random() * 20),
      })

      setCpuHistory(prev => [...prev.slice(-50), newCpu])
      setMemoryHistory(prev => [...prev.slice(-50), newMemory])
    }, 1000)

    return () => clearInterval(interval)
  }, [profiling])

  useEffect(() => {
    if (!canvasRef.current || cpuHistory.length === 0) return

    const canvas = canvasRef.current
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    canvas.width = canvas.offsetWidth
    canvas.height = canvas.offsetHeight

    ctx.clearRect(0, 0, canvas.width, canvas.height)

    ctx.strokeStyle = '#3c3c3c'
    ctx.lineWidth = 1
    for (let i = 0; i <= 4; i++) {
      const y = (canvas.height / 4) * i
      ctx.beginPath()
      ctx.moveTo(0, y)
      ctx.lineTo(canvas.width, y)
      ctx.stroke()
    }

    ctx.strokeStyle = '#4fc3f7'
    ctx.lineWidth = 2
    ctx.beginPath()

    const pointWidth = canvas.width / (cpuHistory.length - 1 || 1)
    cpuHistory.forEach((value, index) => {
      const x = index * pointWidth
      const y = canvas.height - (value / 100) * canvas.height

      if (index === 0) {
        ctx.moveTo(x, y)
      } else {
        ctx.lineTo(x, y)
      }
    })

    ctx.stroke()

    ctx.lineTo(canvas.width, canvas.height)
    ctx.lineTo(0, canvas.height)
    ctx.closePath()
    ctx.fillStyle = 'rgba(79, 195, 247, 0.1)'
    ctx.fill()
  }, [cpuHistory])

  const startProfiling = async () => {
    setProfiling(true)

    try {
      const response = await fetch('/api/performance/start', {
        method: 'POST',
      })

      if (response.ok) {
        setHotspots([
          { name: 'renderComponent', time: 245.3, percentage: 42.1, file: 'App.tsx', line: 156 },
          { name: 'fetchData', time: 123.8, percentage: 21.3, file: 'api.ts', line: 45 },
          { name: 'processResults', time: 89.2, percentage: 15.3, file: 'utils.ts', line: 78 },
          { name: 'updateDOM', time: 67.5, percentage: 11.6, file: 'render.ts', line: 234 },
          { name: 'validateInput', time: 45.1, percentage: 7.7, file: 'validator.ts', line: 12 },
        ])
      }
    } catch (error) {
      console.error('Failed to start profiling:', error)
    }
  }

  const stopProfiling = async () => {
    setProfiling(false)

    try {
      await fetch('/api/performance/stop', {
        method: 'POST',
      })
    } catch (error) {
      console.error('Failed to stop profiling:', error)
    }
  }

  const exportProfile = () => {
    const data = {
      metrics,
      cpuHistory,
      memoryHistory,
      hotspots,
      timestamp: new Date().toISOString(),
    }

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `profile-${Date.now()}.json`
    a.click()
    URL.revokeObjectURL(url)
  }

  const getCpuColor = (cpu: number) => {
    if (cpu < 50) return 'default'
    if (cpu < 80) return 'default'
    return 'destructive'
  }

  const getMemoryColor = (memory: number) => {
    if (memory < 60) return 'default'
    if (memory < 85) return 'default'
    return 'destructive'
  }

  return (
    <div className="flex flex-col h-full bg-[#1e1e1e] text-[#cccccc]">
      <div className="flex items-center justify-between px-3 py-2 border-b border-[#3c3c3c] bg-[#2b2b2b]">
        <div className="text-[13px] font-semibold text-white">Performance Monitor</div>

        <div className="flex gap-1">
          {!profiling ? (
            <Button
              size="sm"
              onClick={startProfiling}
            >
              <Play className="w-3.5 h-3.5 mr-1" />
              Start Profiling
            </Button>
          ) : (
            <Button
              size="sm"
              onClick={stopProfiling}
            >
              <Square className="w-3.5 h-3.5 mr-1" />
              Stop Profiling
            </Button>
          )}
          <Button
            variant="ghost"
            size="sm"
            onClick={exportProfile}
            disabled={!profiling && cpuHistory.length === 0}
            title="Export Profile"
          >
            <Download className="w-3.5 h-3.5" />
          </Button>
        </div>
      </div>

      {profiling && (
        <div className="grid grid-cols-2 gap-3 p-3 border-b border-[#3c3c3c]">
          <div className="p-3 bg-[#252526] border border-[#3c3c3c] rounded">
            <div className="text-[10px] text-[#858585] uppercase mb-1.5">CPU Usage</div>
            <div className="text-2xl font-bold text-white mb-1">{metrics.cpu}%</div>
            <div className="mb-2">
              <Badge variant={getCpuColor(metrics.cpu)} className="text-[10px]">
                {metrics.cpu < 50 ? 'Normal' : metrics.cpu < 80 ? 'High' : 'Critical'}
              </Badge>
            </div>
            <Progress value={metrics.cpu} className="h-1.5" />
          </div>

          <div className="p-3 bg-[#252526] border border-[#3c3c3c] rounded">
            <div className="text-[10px] text-[#858585] uppercase mb-1.5">Memory</div>
            <div className="text-2xl font-bold text-white mb-1">{metrics.memory}%</div>
            <div className="mb-2">
              <Badge variant={getMemoryColor(metrics.memory)} className="text-[10px]">
                {metrics.memory < 60 ? 'Normal' : metrics.memory < 85 ? 'High' : 'Critical'}
              </Badge>
            </div>
            <Progress value={metrics.memory} className="h-1.5" />
          </div>

          <div className="p-3 bg-[#252526] border border-[#3c3c3c] rounded">
            <div className="text-[10px] text-[#858585] uppercase mb-1.5">Frame Rate</div>
            <div className="text-2xl font-bold text-white">{metrics.fps} FPS</div>
            <div className="text-[10px] text-[#b0b0b0] mt-1">
              {metrics.fps >= 55 ? '✓ Smooth' : '⚠ Lagging'}
            </div>
          </div>

          <div className="p-3 bg-[#252526] border border-[#3c3c3c] rounded">
            <div className="text-[10px] text-[#858585] uppercase mb-1.5">Network</div>
            <div className="text-2xl font-bold text-white">{metrics.networkRequests}</div>
            <div className="text-[10px] text-[#b0b0b0] mt-1">Active requests</div>
          </div>
        </div>
      )}

      <div className="flex-1 overflow-auto p-3">
        {!profiling && cpuHistory.length === 0 && (
          <div className="flex flex-col items-center justify-center h-full text-center text-[#858585] text-xs">
            <div className="text-5xl mb-3">📊</div>
            <div>Click "Start Profiling" to begin monitoring performance</div>
          </div>
        )}

        {profiling && (
          <>
            <div className="mb-5">
              <div className="text-[11px] font-semibold text-[#858585] uppercase mb-2">CPU Usage Over Time</div>
              <div className="h-[120px] bg-[#252526] border border-[#3c3c3c] rounded p-2 relative">
                <canvas ref={canvasRef} className="w-full h-full" />
              </div>
            </div>

            <div className="mb-5">
              <div className="text-[11px] font-semibold text-[#858585] uppercase mb-2">Performance Hotspots</div>
              <div className="flex flex-col gap-1">
                {hotspots.map((hotspot, index) => (
                  <div key={index} className="flex items-center justify-between px-3 py-2 bg-[#252526] border border-[#3c3c3c] rounded text-[11px]">
                    <div className="flex-1">
                      <div className="text-[#dcdcaa] font-medium">{hotspot.name}</div>
                      <div className="text-[#858585] text-[10px]">
                        {hotspot.file}:{hotspot.line}
                      </div>
                    </div>
                    <div className="text-[#f48771] font-semibold ml-3">{hotspot.time.toFixed(1)}ms</div>
                    <div className="text-[#858585] text-[10px] ml-2">{hotspot.percentage.toFixed(1)}%</div>
                  </div>
                ))}
              </div>
            </div>

            <div className="mb-5">
              <div className="text-[11px] font-semibold text-[#858585] uppercase mb-2">Call Stack Flame Graph</div>
              <div className="bg-[#252526] border border-[#3c3c3c] rounded p-3 min-h-[200px]">
                {hotspots.map((hotspot, index) => (
                  <div
                    key={index}
                    className="h-5 mb-0.5 flex items-center pl-2 text-[10px] text-white cursor-pointer rounded hover:opacity-80"
                    style={{
                      width: `${hotspot.percentage}%`,
                      backgroundColor: `hsl(${200 - index * 30}, 70%, 50%)`,
                      marginLeft: `${index * 20}px`,
                    }}
                  >
                    {hotspot.name} ({hotspot.time.toFixed(1)}ms)
                  </div>
                ))}
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  )
}

import React, { useState, useEffect } from 'react'
import { Button } from '@persona-framework/ui'
import {
  Settings, Plus, Trash2, Eye, EyeOff, Copy, Check, ChevronDown, ChevronRight,
  Shield, AlertTriangle, Download, Upload
} from 'lucide-react'

const STORAGE_KEY = 'wraith_environments'

type EnvironmentType = 'development' | 'staging' | 'production' | 'custom'

interface EnvVariable {
  key: string
  value: string
  isSecret: boolean
}

interface Environment {
  id: string
  name: string
  type: EnvironmentType
  variables: EnvVariable[]
  isActive: boolean
}

const ENV_TYPE_STYLES: Record<EnvironmentType, { bg: string; border: string; text: string }> = {
  development: {
    bg: 'bg-[rgba(0,255,127,0.2)]',
    border: 'border-[#00ff7f]',
    text: 'text-[#00ff7f]',
  },
  staging: {
    bg: 'bg-[rgba(255,215,0,0.2)]',
    border: 'border-[#ffd700]',
    text: 'text-[#ffd700]',
  },
  production: {
    bg: 'bg-[rgba(244,135,113,0.2)]',
    border: 'border-[#f48771]',
    text: 'text-[#f48771]',
  },
  custom: {
    bg: 'bg-[rgba(157,0,255,0.2)]',
    border: 'border-[#9d00ff]',
    text: 'text-[#9d00ff]',
  },
}

function loadEnvironments(): Environment[] {
  try {
    const stored = localStorage.getItem(STORAGE_KEY)
    if (stored) {
      const parsed = JSON.parse(stored)
      if (Array.isArray(parsed)) return parsed
    }
  } catch {
    // Invalid storage
  }
  return getDefaultEnvironments()
}

function saveEnvironments(envs: Environment[]) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(envs))
  } catch {
    // Storage unavailable
  }
}

function getDefaultEnvironments(): Environment[] {
  return [
    {
      id: 'dev',
      name: 'Development',
      type: 'development',
      isActive: true,
      variables: [
        { key: 'API_URL', value: 'http://localhost:3000', isSecret: false },
        { key: 'DEBUG', value: 'true', isSecret: false },
      ],
    },
    {
      id: 'staging',
      name: 'Staging',
      type: 'staging',
      isActive: false,
      variables: [
        { key: 'API_URL', value: 'https://staging.example.com', isSecret: false },
        { key: 'DEBUG', value: 'false', isSecret: false },
      ],
    },
    {
      id: 'prod',
      name: 'Production',
      type: 'production',
      isActive: false,
      variables: [
        { key: 'API_URL', value: 'https://api.example.com', isSecret: false },
        { key: 'API_KEY', value: 'sk-prod-xxxxx', isSecret: true },
      ],
    },
  ]
}

export function EnvironmentManagerPanel() {
  const [environments, setEnvironments] = useState<Environment[]>(() => loadEnvironments())
  const [expandedEnvs, setExpandedEnvs] = useState<Set<string>>(new Set(['dev']))
  const [revealedSecrets, setRevealedSecrets] = useState<Set<string>>(new Set())
  const [copiedKey, setCopiedKey] = useState<string | null>(null)
  const [showAddEnv, setShowAddEnv] = useState(false)
  const [newEnv, setNewEnv] = useState({ name: '', type: 'custom' as EnvironmentType })

  useEffect(() => {
    saveEnvironments(environments)
  }, [environments])

  const toggleExpanded = (envId: string) => {
    setExpandedEnvs(prev => {
      const next = new Set(prev)
      if (next.has(envId)) {
        next.delete(envId)
      } else {
        next.add(envId)
      }
      return next
    })
  }

  const toggleSecret = (key: string) => {
    setRevealedSecrets(prev => {
      const next = new Set(prev)
      if (next.has(key)) {
        next.delete(key)
      } else {
        next.add(key)
      }
      return next
    })
  }

  const copyValue = (key: string, value: string) => {
    navigator.clipboard.writeText(value)
    setCopiedKey(key)
    setTimeout(() => setCopiedKey(null), 2000)
  }

  const setActiveEnv = (envId: string) => {
    setEnvironments(environments.map(env => ({
      ...env,
      isActive: env.id === envId,
    })))
  }

  const addEnvironment = () => {
    if (!newEnv.name.trim()) return

    const env: Environment = {
      id: crypto.randomUUID(),
      name: newEnv.name.trim(),
      type: newEnv.type,
      isActive: false,
      variables: [],
    }

    setEnvironments([...environments, env])
    setNewEnv({ name: '', type: 'custom' })
    setShowAddEnv(false)
    setExpandedEnvs(prev => new Set([...prev, env.id]))
  }

  const deleteEnvironment = (envId: string) => {
    setEnvironments(environments.filter(e => e.id !== envId))
  }

  const addVariable = (envId: string) => {
    setEnvironments(environments.map(env => {
      if (env.id !== envId) return env
      return {
        ...env,
        variables: [...env.variables, { key: '', value: '', isSecret: false }],
      }
    }))
  }

  const updateVariable = (envId: string, index: number, updates: Partial<EnvVariable>) => {
    setEnvironments(environments.map(env => {
      if (env.id !== envId) return env
      const newVars = [...env.variables]
      newVars[index] = { ...newVars[index], ...updates }
      return { ...env, variables: newVars }
    }))
  }

  const deleteVariable = (envId: string, index: number) => {
    setEnvironments(environments.map(env => {
      if (env.id !== envId) return env
      return {
        ...env,
        variables: env.variables.filter((_, i) => i !== index),
      }
    }))
  }

  const exportEnv = (env: Environment) => {
    const content = env.variables
      .map(v => `${v.key}=${v.value}`)
      .join('\n')
    const blob = new Blob([content], { type: 'text/plain' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `.env.${env.name.toLowerCase().replace(/\s+/g, '-')}`
    a.click()
    URL.revokeObjectURL(url)
  }

  const activeEnv = environments.find(e => e.isActive)

  return (
    <div className="flex flex-col h-full bg-[#1e1e1e] text-[#cccccc] overflow-hidden">
      <div className="p-3 border-b border-[#3c3c3c] bg-[#252526]">
        <div className="flex items-center justify-between mb-2">
          <div className="flex items-center gap-2">
            <Settings className="w-4 h-4 text-[#5bcefa]" />
            <span className="text-sm font-medium text-white">Environments</span>
          </div>
          <Button
            size="sm"
            variant="ghost"
            onClick={() => setShowAddEnv(!showAddEnv)}
            className="h-7 w-7 p-0"
            aria-label="Add environment"
          >
            <Plus className="w-4 h-4" />
          </Button>
        </div>

        {activeEnv && (
          <div className={`flex items-center gap-2 px-2 py-1 rounded text-xs ${ENV_TYPE_STYLES[activeEnv.type].bg}`}>
            <div className={`w-2 h-2 rounded-full ${ENV_TYPE_STYLES[activeEnv.type].bg} ${ENV_TYPE_STYLES[activeEnv.type].border} border-2`} />
            <span className={ENV_TYPE_STYLES[activeEnv.type].text}>Active: {activeEnv.name}</span>
          </div>
        )}
      </div>

      {showAddEnv && (
        <div className="p-3 border-b border-[#3c3c3c] bg-[#2d2d30]">
          <div className="flex flex-col gap-2">
            <input
              type="text"
              placeholder="Environment name"
              value={newEnv.name}
              onChange={(e) => setNewEnv({ ...newEnv, name: e.target.value })}
              className="w-full px-3 py-1.5 text-sm bg-[#3c3c3c] border border-[#3c3c3c] rounded text-white placeholder-[#808080] focus:outline-none focus:border-[#5bcefa]"
            />
            <select
              value={newEnv.type}
              onChange={(e) => setNewEnv({ ...newEnv, type: e.target.value as EnvironmentType })}
              className="w-full px-3 py-1.5 text-sm bg-[#3c3c3c] border border-[#3c3c3c] rounded text-white focus:outline-none focus:border-[#5bcefa]"
            >
              <option value="development">Development</option>
              <option value="staging">Staging</option>
              <option value="production">Production</option>
              <option value="custom">Custom</option>
            </select>
            <Button size="sm" onClick={addEnvironment} disabled={!newEnv.name.trim()}>
              <Plus className="w-3.5 h-3.5 mr-1.5" />
              Add Environment
            </Button>
          </div>
        </div>
      )}

      <div className="flex-1 overflow-auto p-2">
        {environments.map(env => {
          const style = ENV_TYPE_STYLES[env.type]
          const isExpanded = expandedEnvs.has(env.id)

          return (
            <div key={env.id} className="mb-2">
              <div
                className={`flex items-center gap-2 p-2 rounded-md cursor-pointer transition-all hover:bg-[#2d2d30] ${
                  env.isActive ? `${style.bg} border ${style.border}` : ''
                }`}
                onClick={() => toggleExpanded(env.id)}
              >
                {isExpanded ? (
                  <ChevronDown className="w-4 h-4 text-[#808080]" />
                ) : (
                  <ChevronRight className="w-4 h-4 text-[#808080]" />
                )}
                <span className={`text-sm font-medium ${env.isActive ? style.text : 'text-white'}`}>
                  {env.name}
                </span>
                <span className={`text-[10px] uppercase px-1.5 py-0.5 rounded ${style.bg} ${style.text}`}>
                  {env.type}
                </span>
                <span className="text-xs text-[#808080]">({env.variables.length})</span>
                <div className="flex-1" />
                {!env.isActive && (
                  <button
                    onClick={(e) => {
                      e.stopPropagation()
                      setActiveEnv(env.id)
                    }}
                    className="px-2 py-0.5 text-[10px] bg-[#3c3c3c] text-[#b0b0b0] rounded hover:bg-[#4c4c4c] transition-colors"
                  >
                    Activate
                  </button>
                )}
                <button
                  onClick={(e) => {
                    e.stopPropagation()
                    exportEnv(env)
                  }}
                  className="p-1 rounded hover:bg-[#3c3c3c] transition-colors"
                  aria-label="Export environment"
                >
                  <Download className="w-3.5 h-3.5 text-[#808080]" />
                </button>
                <button
                  onClick={(e) => {
                    e.stopPropagation()
                    deleteEnvironment(env.id)
                  }}
                  className="p-1 rounded hover:bg-[#5a1d1d] transition-colors"
                  aria-label="Delete environment"
                >
                  <Trash2 className="w-3.5 h-3.5 text-[#f48771]" />
                </button>
              </div>

              {isExpanded && (
                <div className="ml-6 mt-1 border-l-2 border-[#3c3c3c] pl-3">
                  {env.variables.map((variable, idx) => (
                    <div key={idx} className="flex items-center gap-2 py-1.5">
                      <input
                        type="text"
                        placeholder="KEY"
                        value={variable.key}
                        onChange={(e) => updateVariable(env.id, idx, { key: e.target.value })}
                        className="w-32 px-2 py-1 text-xs bg-[#3c3c3c] border border-[#3c3c3c] rounded text-white font-mono placeholder-[#808080] focus:outline-none focus:border-[#5bcefa]"
                      />
                      <span className="text-[#606060]">=</span>
                      <div className="flex-1 flex items-center gap-1">
                        <input
                          type={variable.isSecret && !revealedSecrets.has(`${env.id}-${idx}`) ? 'password' : 'text'}
                          placeholder="value"
                          value={variable.value}
                          onChange={(e) => updateVariable(env.id, idx, { value: e.target.value })}
                          className="flex-1 px-2 py-1 text-xs bg-[#3c3c3c] border border-[#3c3c3c] rounded text-white font-mono placeholder-[#808080] focus:outline-none focus:border-[#5bcefa]"
                        />
                      </div>
                      <button
                        onClick={() => updateVariable(env.id, idx, { isSecret: !variable.isSecret })}
                        className={`p-1 rounded transition-colors ${
                          variable.isSecret ? 'bg-[rgba(244,135,113,0.2)] text-[#f48771]' : 'hover:bg-[#3c3c3c] text-[#808080]'
                        }`}
                        aria-label={variable.isSecret ? 'Mark as non-secret' : 'Mark as secret'}
                        title={variable.isSecret ? 'Secret' : 'Not secret'}
                      >
                        <Shield className="w-3.5 h-3.5" />
                      </button>
                      {variable.isSecret && (
                        <button
                          onClick={() => toggleSecret(`${env.id}-${idx}`)}
                          className="p-1 rounded hover:bg-[#3c3c3c] transition-colors"
                          aria-label={revealedSecrets.has(`${env.id}-${idx}`) ? 'Hide value' : 'Show value'}
                        >
                          {revealedSecrets.has(`${env.id}-${idx}`) ? (
                            <EyeOff className="w-3.5 h-3.5 text-[#808080]" />
                          ) : (
                            <Eye className="w-3.5 h-3.5 text-[#808080]" />
                          )}
                        </button>
                      )}
                      <button
                        onClick={() => copyValue(`${env.id}-${idx}`, variable.value)}
                        className="p-1 rounded hover:bg-[#3c3c3c] transition-colors"
                        aria-label="Copy value"
                      >
                        {copiedKey === `${env.id}-${idx}` ? (
                          <Check className="w-3.5 h-3.5 text-[#00ff7f]" />
                        ) : (
                          <Copy className="w-3.5 h-3.5 text-[#808080]" />
                        )}
                      </button>
                      <button
                        onClick={() => deleteVariable(env.id, idx)}
                        className="p-1 rounded hover:bg-[#5a1d1d] transition-colors"
                        aria-label="Delete variable"
                      >
                        <Trash2 className="w-3.5 h-3.5 text-[#f48771]" />
                      </button>
                    </div>
                  ))}
                  <button
                    onClick={() => addVariable(env.id)}
                    className="flex items-center gap-1.5 text-xs text-[#5bcefa] hover:text-[#7dd3fc] py-1.5 transition-colors"
                  >
                    <Plus className="w-3.5 h-3.5" />
                    Add Variable
                  </button>
                </div>
              )}
            </div>
          )
        })}
      </div>
    </div>
  )
}

