import React, { useState, useEffect } from 'react'
import { Button, Input, Spinner, Progress, Badge, DropdownMenu, DropdownMenuTrigger, DropdownMenuContent, DropdownMenuItem } from '@persona-framework/ui'
import {
  Play,
  RotateCcw,
  X,
  Search,
  ChevronRight,
  ChevronDown,
  CheckCircle,
  XCircle,
  AlertCircle,
  Clock,
  Filter,
  Eye,
  Bug,
  Shield,
} from 'lucide-react'

interface TestCase {
  id: string
  name: string
  status: 'pass' | 'fail' | 'skip' | 'running' | 'pending'
  duration?: number
  error?: string
  filePath: string
  line: number
}

interface TestSuite {
  id: string
  name: string
  language: 'kotlin' | 'rust' | 'typescript' | 'java'
  filePath: string
  tests: TestCase[]
  expanded: boolean
}

export function TestExplorerPanel() {
  const [searchQuery, setSearchQuery] = useState('')
  const [testSuites, setTestSuites] = useState<TestSuite[]>([])
  const [loading, setLoading] = useState(false)
  const [running, setRunning] = useState(false)
  const [progress, setProgress] = useState(0)
  const [filterStatus, setFilterStatus] = useState<'all' | 'pass' | 'fail' | 'skip'>('all')
  const [watchMode, setWatchMode] = useState(false)
  const [coverage, setCoverage] = useState<{ line: number; branch: number; statement: number } | null>(null)
  const [showCoverage, setShowCoverage] = useState(false)

  useEffect(() => {
    loadTests()
  }, [])

  useEffect(() => {
    if (!watchMode) return

    const interval = setInterval(() => {
      runAllTests()
    }, 5000)

    return () => clearInterval(interval)
  }, [watchMode])

  const loadTests = async () => {
    setLoading(true)
    try {
      const response = await fetch('/api/tests/discover')
      if (response.ok) {
        const data = await response.json()
        setTestSuites(data.suites || getMockTestSuites())
      } else {
        setTestSuites(getMockTestSuites())
      }
    } catch {
      // Fallback to mock data when API unavailable
      setTestSuites(getMockTestSuites())
    } finally {
      setLoading(false)
    }
  }

  const getMockTestSuites = (): TestSuite[] => {
    return [
      {
        id: 'suite-1',
        name: 'LeviathanServiceTest (Kotlin)',
        language: 'kotlin',
        filePath: '/leviathan/src/test/kotlin/LeviathanServiceTest.kt',
        expanded: true,
        tests: [
          {
            id: 'test-1-1',
            name: 'should create persona successfully',
            status: 'pass',
            duration: 124,
            filePath: '/leviathan/src/test/kotlin/LeviathanServiceTest.kt',
            line: 15,
          },
          {
            id: 'test-1-2',
            name: 'should update persona attributes',
            status: 'pass',
            duration: 89,
            filePath: '/leviathan/src/test/kotlin/LeviathanServiceTest.kt',
            line: 32,
          },
          {
            id: 'test-1-3',
            name: 'should handle invalid persona ID',
            status: 'fail',
            duration: 45,
            error: 'Expected exception not thrown',
            filePath: '/leviathan/src/test/kotlin/LeviathanServiceTest.kt',
            line: 48,
          },
        ],
      },
      {
        id: 'suite-2',
        name: 'bael.spec.tsx (TypeScript)',
        language: 'typescript',
        filePath: '/bael/src/__tests__/App.spec.tsx',
        expanded: false,
        tests: [
          {
            id: 'test-4-1',
            name: 'renders main component',
            status: 'pass',
            duration: 234,
            filePath: '/bael/src/__tests__/App.spec.tsx',
            line: 10,
          },
          {
            id: 'test-4-2',
            name: 'handles user interaction',
            status: 'pass',
            duration: 156,
            filePath: '/bael/src/__tests__/App.spec.tsx',
            line: 25,
          },
        ],
      },
    ]
  }

  const runAllTests = async () => {
    setRunning(true)
    setProgress(0)

    try {
      const response = await fetch('/api/tests/run', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ all: true, coverage: showCoverage }),
      })

      if (response.ok) {
        const data = await response.json()

        if (data.coverage) {
          setCoverage(data.coverage)
        }

        // Update progress based on actual response or simulate
        for (let i = 0; i <= 100; i += 10) {
          setProgress(i)
          await new Promise((resolve) => setTimeout(resolve, 200))
        }

        loadTests()
      }
    } catch {
      // Test run failed - will show in test results
    } finally {
      setRunning(false)
      setProgress(0)
    }
  }

  const debugTest = async (testId: string) => {
    try {
      await fetch('/api/tests/debug', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ testId }),
      })
      // Debug session will open in debugger panel
    } catch {
      // Debug start failed - non-blocking
    }
  }

  const runTest = async (testId: string) => {
    try {
      await fetch('/api/tests/run', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ testId }),
      })
      loadTests()
    } catch {
      // Test run failed - will be visible in test results
    }
  }

  const runTestSuite = async (suiteId: string) => {
    try {
      await fetch('/api/tests/run', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ suiteId }),
      })
      loadTests()
    } catch {
      // Suite run failed - will be visible in test results
    }
  }

  const toggleSuite = (suiteId: string) => {
    setTestSuites((prev) =>
      prev.map((suite) =>
        suite.id === suiteId ? { ...suite, expanded: !suite.expanded } : suite
      )
    )
  }

  const getStatusIcon = (status: TestCase['status']) => {
    switch (status) {
      case 'pass':
        return <CheckCircle className="text-[#4ec9b0] w-3.5 h-3.5" />
      case 'fail':
        return <XCircle className="text-[#f48771] w-3.5 h-3.5" />
      case 'skip':
        return <AlertCircle className="text-[#858585] w-3.5 h-3.5" />
      case 'running':
        return <Spinner size="sm" />
      case 'pending':
        return <Clock className="text-[#858585] w-3.5 h-3.5" />
    }
  }

  const getSuiteStatus = (suite: TestSuite) => {
    const passed = suite.tests.filter((t) => t.status === 'pass').length
    const failed = suite.tests.filter((t) => t.status === 'fail').length
    const skipped = suite.tests.filter((t) => t.status === 'skip').length

    if (failed > 0) return 'fail'
    if (skipped === suite.tests.length) return 'skip'
    if (passed === suite.tests.length) return 'pass'
    return 'pending'
  }

  const filteredSuites = testSuites
    .map((suite) => ({
      ...suite,
      tests: suite.tests.filter((test) => {
        const matchesSearch =
          test.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
          suite.name.toLowerCase().includes(searchQuery.toLowerCase())
        const matchesFilter = filterStatus === 'all' || test.status === filterStatus
        return matchesSearch && matchesFilter
      }),
    }))
    .filter((suite) => suite.tests.length > 0)

  const totalTests = testSuites.reduce((acc, suite) => acc + suite.tests.length, 0)
  const passedTests = testSuites.reduce(
    (acc, suite) => acc + suite.tests.filter((t) => t.status === 'pass').length,
    0
  )
  const failedTests = testSuites.reduce(
    (acc, suite) => acc + suite.tests.filter((t) => t.status === 'fail').length,
    0
  )
  const skippedTests = testSuites.reduce(
    (acc, suite) => acc + suite.tests.filter((t) => t.status === 'skip').length,
    0
  )

  return (
    <div className="flex flex-col h-full bg-[#1e1e1e] text-[#cccccc]">
      <div className="flex items-center justify-between px-3 py-2 border-b border-[#3c3c3c] bg-[#2b2b2b]">
        <div className="text-[13px] font-semibold text-white">Test Explorer</div>

        <div className="flex gap-1">
          <Button
            variant={watchMode ? 'default' : 'ghost'}
            size="sm"
            onClick={() => setWatchMode(!watchMode)}
            title={watchMode ? 'Disable Watch Mode' : 'Enable Watch Mode'}
          >
            <Eye className="w-3.5 h-3.5" />
          </Button>
          <Button
            variant={showCoverage ? 'default' : 'ghost'}
            size="sm"
            onClick={() => setShowCoverage(!showCoverage)}
            title={showCoverage ? 'Disable Coverage' : 'Enable Coverage'}
          >
            <Shield className="w-3.5 h-3.5" />
          </Button>
          <Button
            size="sm"
            onClick={runAllTests}
            disabled={running || loading}
          >
            <Play className="w-3.5 h-3.5 mr-1" />
            Run All
          </Button>
          <Button
            variant="ghost"
            size="sm"
            onClick={loadTests}
            disabled={loading}
            title="Refresh"
          >
            <RotateCcw className="w-3.5 h-3.5" />
          </Button>
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="sm" title="Filter">
                <Filter className="w-3.5 h-3.5" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent>
              <DropdownMenuItem onClick={() => setFilterStatus('all')}>Show All</DropdownMenuItem>
              <DropdownMenuItem onClick={() => setFilterStatus('pass')}>Show Passed</DropdownMenuItem>
              <DropdownMenuItem onClick={() => setFilterStatus('fail')}>Show Failed</DropdownMenuItem>
              <DropdownMenuItem onClick={() => setFilterStatus('skip')}>Show Skipped</DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>

      <div className="px-3 py-2 border-b border-[#3c3c3c]">
        <div className="relative">
          <Search className="absolute left-2 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-[#858585]" />
          <Input
            placeholder="Search tests..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            size="sm"
            className="w-full pl-8"
          />
        </div>
      </div>

      {running && (
        <div className="px-3 pb-2">
          <Progress value={progress} className="w-full" />
          {watchMode && <div className="text-[10px] text-[#4fc3f7] mt-1">⚡ Watch mode active</div>}
        </div>
      )}

      {showCoverage && coverage && (
        <div className="px-3 py-2 bg-[#252526] border-b border-[#3c3c3c] text-[11px]">
          <div className="mb-1 font-semibold">Code Coverage:</div>
          <div className="flex gap-3">
            <div>
              <span className="text-[#858585]">Lines:</span>{' '}
              <Badge variant={coverage.line >= 80 ? 'default' : coverage.line >= 60 ? 'default' : 'destructive'} className="text-[10px]">
                {coverage.line}%
              </Badge>
            </div>
            <div>
              <span className="text-[#858585]">Branches:</span>{' '}
              <Badge variant={coverage.branch >= 80 ? 'default' : coverage.branch >= 60 ? 'default' : 'destructive'} className="text-[10px]">
                {coverage.branch}%
              </Badge>
            </div>
            <div>
              <span className="text-[#858585]">Statements:</span>{' '}
              <Badge variant={coverage.statement >= 80 ? 'default' : coverage.statement >= 60 ? 'default' : 'destructive'} className="text-[10px]">
                {coverage.statement}%
              </Badge>
            </div>
          </div>
        </div>
      )}

      <div className="flex-1 overflow-auto px-3 py-3">
        {loading && (
          <div className="flex flex-col items-center gap-3 px-5 py-10">
            <Spinner size="md" />
            <span>Discovering tests...</span>
          </div>
        )}

        {!loading && filteredSuites.length === 0 && (
          <div className="px-5 py-10 text-center text-[#858585] text-[13px]">
            {searchQuery ? `No tests found for "${searchQuery}"` : 'No tests discovered'}
          </div>
        )}

        {!loading &&
          filteredSuites.map((suite) => (
            <div key={suite.id} className="mb-1">
              <div
                className="flex items-center gap-1.5 px-2 py-1.5 bg-[#252526] border border-[#3c3c3c] rounded cursor-pointer hover:bg-[#2b2b2b] hover:border-[#4fc3f7]"
                onClick={() => toggleSuite(suite.id)}
              >
                {suite.expanded ? <ChevronDown className="w-3 h-3 min-w-[12px]" /> : <ChevronRight className="w-3 h-3 min-w-[12px]" />}
                <div className="mr-1">{getStatusIcon(getSuiteStatus(suite))}</div>
                <div className="flex-1 text-xs font-semibold text-white truncate">{suite.name}</div>
                <div className="text-[10px] text-[#858585]">
                  {suite.tests.length} test{suite.tests.length !== 1 ? 's' : ''}
                </div>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={(e) => {
                    e.stopPropagation()
                    runTestSuite(suite.id)
                  }}
                  title="Run Suite"
                  className="h-6 w-6 p-0"
                >
                  <Play className="w-3 h-3" />
                </Button>
              </div>

              {suite.expanded && (
                <div className="ml-5 mt-1 space-y-0.5">
                  {suite.tests.map((test) => (
                    <div key={test.id} className="flex items-center gap-1.5 px-2 py-1.5 bg-[#1e1e1e] border border-transparent rounded hover:bg-[#252526] hover:border-[#4fc3f7] cursor-pointer">
                      <div className="mr-0.5">{getStatusIcon(test.status)}</div>
                      <div className="flex-1 text-[11px] text-[#cccccc] truncate">{test.name}</div>
                      {test.duration && (
                        <div className="text-[10px] text-[#858585] font-mono">{test.duration}ms</div>
                      )}
                      <div className="flex gap-0.5">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => runTest(test.id)}
                          title="Run Test"
                          className="h-6 w-6 p-0"
                        >
                          <Play className="w-3 h-3" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => debugTest(test.id)}
                          title="Debug Test"
                          className="h-6 w-6 p-0"
                        >
                          <Bug className="w-3 h-3" />
                        </Button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          ))}
      </div>

      <div className="flex items-center gap-4 px-3 py-2 border-t border-[#3c3c3c] bg-[#252526] text-[11px]">
        <div className="flex items-center gap-1">
          <span>Total:</span>
          <strong>{totalTests}</strong>
        </div>
        <div className="flex items-center gap-1">
          <CheckCircle className="text-[#4ec9b0] w-3 h-3" />
          <strong>{passedTests}</strong>
        </div>
        <div className="flex items-center gap-1">
          <XCircle className="text-[#f48771] w-3 h-3" />
          <strong>{failedTests}</strong>
        </div>
        <div className="flex items-center gap-1">
          <AlertCircle className="text-[#858585] w-3 h-3" />
          <strong>{skippedTests}</strong>
        </div>
      </div>
    </div>
  )
}

import React, { useState, useEffect } from 'react'
import { Button, Input, Badge, Tabs, TabsList, TabsTrigger, TabsContent } from '@persona-framework/ui'
import {
  AlertCircle,
  AlertTriangle,
  Info,
  X,
  RotateCcw,
  Search,
  Filter,
  ChevronRight,
} from 'lucide-react'

interface Problem {
  id: string
  severity: 'error' | 'warning' | 'info'
  message: string
  source: string
  filePath: string
  line: number
  column: number
  code?: string
  category?: string
}

interface ProblemGroup {
  filePath: string
  problems: Problem[]
  expanded: boolean
}

type TabValue = 'all' | 'errors' | 'warnings' | 'info'

export function ProblemsPanel() {
  const [activeTab, setActiveTab] = useState<TabValue>('all')
  const [searchQuery, setSearchQuery] = useState('')
  const [problemGroups, setProblemGroups] = useState<ProblemGroup[]>([])

  useEffect(() => {
    loadProblems()

    const interval = setInterval(loadProblems, 5000)
    return () => clearInterval(interval)
  }, [])

  const loadProblems = async () => {
    try {
      const response = await fetch('/api/diagnostics/all')
      if (response.ok) {
        const data = await response.json()
        const grouped = groupProblemsByFile(data.problems || getMockProblems())
        setProblemGroups(grouped)
      } else {
        const grouped = groupProblemsByFile(getMockProblems())
        setProblemGroups(grouped)
      }
    } catch (error) {
      console.error('Failed to load problems:', error)
      const grouped = groupProblemsByFile(getMockProblems())
      setProblemGroups(grouped)
    }
  }

  const getMockProblems = (): Problem[] => {
    return [
      {
        id: 'prob-1',
        severity: 'error',
        message: 'Unresolved reference: PersonaService',
        source: 'Kotlin Compiler',
        filePath: '/leviathan/src/main/kotlin/Controller.kt',
        line: 45,
        column: 23,
        code: 'UNRESOLVED_REFERENCE',
        category: 'compilation',
      },
      {
        id: 'prob-2',
        severity: 'error',
        message: 'Type mismatch: inferred type is String but Int was expected',
        source: 'Kotlin Compiler',
        filePath: '/leviathan/src/main/kotlin/Controller.kt',
        line: 67,
        column: 15,
        code: 'TYPE_MISMATCH',
        category: 'compilation',
      },
      {
        id: 'prob-3',
        severity: 'warning',
        message: 'Unused import statement',
        source: 'Kotlin Compiler',
        filePath: '/leviathan/src/main/kotlin/Controller.kt',
        line: 5,
        column: 1,
        code: 'UNUSED_IMPORT',
        category: 'style',
      },
      {
        id: 'prob-4',
        severity: 'error',
        message: 'cannot find symbol: method processData()',
        source: 'Java Compiler',
        filePath: '/persona-core/src/main/java/DataProcessor.java',
        line: 123,
        column: 12,
        category: 'compilation',
      },
      {
        id: 'prob-8',
        severity: 'error',
        message: "Property 'userData' does not exist on type 'User'",
        source: 'TypeScript',
        filePath: '/bael/src/components/UserProfile.tsx',
        line: 78,
        column: 18,
        code: 'TS2339',
        category: 'type-check',
      },
      {
        id: 'prob-9',
        severity: 'warning',
        message: "'useState' is defined but never used",
        source: 'ESLint',
        filePath: '/bael/src/components/UserProfile.tsx',
        line: 3,
        column: 10,
        code: 'no-unused-vars',
        category: 'lint',
      },
      {
        id: 'prob-10',
        severity: 'info',
        message: 'Consider using optional chaining: user?.name',
        source: 'ESLint',
        filePath: '/bael/src/components/UserProfile.tsx',
        line: 92,
        column: 20,
        code: 'prefer-optional-chain',
        category: 'suggestion',
      },
    ]
  }

  const groupProblemsByFile = (problems: Problem[]): ProblemGroup[] => {
    const groups: { [key: string]: Problem[] } = {}

    problems.forEach((problem) => {
      if (!groups[problem.filePath]) {
        groups[problem.filePath] = []
      }
      groups[problem.filePath].push(problem)
    })

    return Object.entries(groups).map(([filePath, problems]) => ({
      filePath,
      problems: problems.sort((a, b) => a.line - b.line),
      expanded: true,
    }))
  }

  const toggleGroup = (filePath: string) => {
    setProblemGroups((prev) =>
      prev.map((group) =>
        group.filePath === filePath ? { ...group, expanded: !group.expanded } : group
      )
    )
  }

  const getSeverityIcon = (severity: Problem['severity']) => {
    switch (severity) {
      case 'error':
        return <AlertCircle className="text-[#f48771] w-3.5 h-3.5" />
      case 'warning':
        return <AlertTriangle className="text-[#f59e0b] w-3.5 h-3.5" />
      case 'info':
        return <Info className="text-[#4fc3f7] w-3.5 h-3.5" />
    }
  }

  const filterProblems = (problems: Problem[]): Problem[] => {
    return problems.filter((problem) => {
      if (activeTab !== 'all') {
        if (activeTab === 'errors' && problem.severity !== 'error') return false
        if (activeTab === 'warnings' && problem.severity !== 'warning') return false
        if (activeTab === 'info' && problem.severity !== 'info') return false
      }

      if (searchQuery) {
        const query = searchQuery.toLowerCase()
        return (
          problem.message.toLowerCase().includes(query) ||
          problem.filePath.toLowerCase().includes(query) ||
          problem.source.toLowerCase().includes(query)
        )
      }

      return true
    })
  }

  const filteredGroups = problemGroups
    .map((group) => ({
      ...group,
      problems: filterProblems(group.problems),
    }))
    .filter((group) => group.problems.length > 0)

  const allProblems = problemGroups.flatMap((g) => g.problems)
  const errorCount = allProblems.filter((p) => p.severity === 'error').length
  const warningCount = allProblems.filter((p) => p.severity === 'warning').length
  const infoCount = allProblems.filter((p) => p.severity === 'info').length

  const handleProblemClick = (problem: Problem) => {
    console.log('Jump to:', problem.filePath, problem.line, problem.column)
  }

  return (
    <div className="flex flex-col h-full bg-[#1e1e1e] text-[#cccccc]">
      <div className="flex items-center justify-between px-3 py-2 border-b border-[#3c3c3c] bg-[#2b2b2b]">
        <div className="text-[13px] font-semibold text-white">Problems</div>

        <div className="flex gap-1">
          <Button
            variant="ghost"
            size="sm"
            onClick={loadProblems}
            title="Refresh"
          >
            <RotateCcw className="w-3.5 h-3.5" />
          </Button>
          <Button
            variant="ghost"
            size="sm"
            title="Clear All"
          >
            <X className="w-3.5 h-3.5" />
          </Button>
        </div>
      </div>

      <Tabs value={activeTab} onValueChange={(value) => setActiveTab(value as TabValue)} className="flex flex-col flex-1">
        <div className="px-3 py-2 border-b border-[#3c3c3c]">
          <TabsList>
            <TabsTrigger value="all">
              All
              <Badge variant="secondary" className="ml-1.5 text-[10px]">{allProblems.length}</Badge>
            </TabsTrigger>
            <TabsTrigger value="errors">
              Errors
              <Badge variant="destructive" className="ml-1.5 text-[10px]">{errorCount}</Badge>
            </TabsTrigger>
            <TabsTrigger value="warnings">
              Warnings
              <Badge variant="default" className="ml-1.5 text-[10px]">{warningCount}</Badge>
            </TabsTrigger>
            <TabsTrigger value="info">
              Info
              <Badge variant="secondary" className="ml-1.5 text-[10px]">{infoCount}</Badge>
            </TabsTrigger>
          </TabsList>
        </div>

        <div className="px-3 py-2 border-b border-[#3c3c3c]">
          <div className="relative">
            <Search className="absolute left-2 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-[#858585]" />
            <Input
              placeholder="Filter problems..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              size="sm"
              className="w-full pl-8"
            />
          </div>
        </div>

        <TabsContent value={activeTab} className="flex-1 overflow-auto">
          {filteredGroups.length === 0 && (
            <div className="px-5 py-10 text-center text-[#858585] text-[13px]">
              {allProblems.length === 0
                ? 'No problems detected!'
                : `No problems match your filter`}
            </div>
          )}

          {filteredGroups.map((group) => (
            <div key={group.filePath} className="border-b border-[#3c3c3c]">
              <div
                className="flex items-center gap-2 px-3 py-2 bg-[#252526] cursor-pointer hover:bg-[#2b2b2b]"
                onClick={() => toggleGroup(group.filePath)}
              >
                <ChevronRight
                  className={`w-3 h-3 min-w-[12px] transition-transform ${group.expanded ? 'rotate-90' : ''}`}
                />
                <div className="flex-1 text-xs font-semibold text-[#cccccc]">
                  {group.filePath.split('/').pop()}
                </div>
                <div className="text-[11px] text-[#858585]">
                  {group.problems.length} problem{group.problems.length !== 1 ? 's' : ''}
                </div>
              </div>

              {group.expanded && (
                <div className="bg-[#1e1e1e]">
                  {group.problems.map((problem) => (
                    <div
                      key={problem.id}
                      className="flex items-start gap-2 px-3 py-2 border-b border-[#2b2b2b] cursor-pointer hover:bg-[#252526] transition-colors"
                      onClick={() => handleProblemClick(problem)}
                    >
                      <div className="mt-0.5">{getSeverityIcon(problem.severity)}</div>
                      <div className="flex-1 min-w-0">
                        <div className="text-xs text-[#cccccc] mb-1 leading-[1.4]">{problem.message}</div>
                        <div className="flex items-center gap-2 text-[10px] text-[#858585]">
                          <span>{problem.source}</span>
                          <span>•</span>
                          <span className="font-mono">
                            {group.filePath.split('/').pop()}:{problem.line}:{problem.column}
                          </span>
                          {problem.code && (
                            <>
                              <span>•</span>
                              <span className="text-[#4fc3f7]">{problem.code}</span>
                            </>
                          )}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          ))}
        </TabsContent>
      </Tabs>

      <div className="flex items-center gap-4 px-3 py-2 border-t border-[#3c3c3c] bg-[#252526] text-[11px]">
        <div className="flex items-center gap-1.5">
          <AlertCircle className="text-[#f48771] w-3 h-3" />
          <strong>{errorCount}</strong>
          <span>Errors</span>
        </div>
        <div className="flex items-center gap-1.5">
          <AlertTriangle className="text-[#f59e0b] w-3 h-3" />
          <strong>{warningCount}</strong>
          <span>Warnings</span>
        </div>
        <div className="flex items-center gap-1.5">
          <Info className="text-[#4fc3f7] w-3 h-3" />
          <strong>{infoCount}</strong>
          <span>Info</span>
        </div>
      </div>
    </div>
  )
}

