import React, { useState, useEffect } from 'react'
import { Button, Spinner } from '@persona-framework/ui'
import {
  Sparkles, Play, AlertCircle, CheckCircle, Info, AlertTriangle,
  ChevronDown, ChevronRight, FileCode, RefreshCw, Settings, Copy, Check
} from 'lucide-react'
import { makeHttpClient } from '../../../data/https'

const http = makeHttpClient('/api')
const HISTORY_KEY = 'wraith_code_review_history'

type Severity = 'error' | 'warning' | 'info' | 'suggestion'

interface ReviewIssue {
  id: string
  severity: Severity
  title: string
  description: string
  lineStart?: number
  lineEnd?: number
  suggestion?: string
}

interface CodeReview {
  id: string
  fileName: string
  language: string
  code: string
  issues: ReviewIssue[]
  summary: string
  score: number
  reviewedAt: number
}

interface ReviewConfig {
  checkSecurity: boolean
  checkPerformance: boolean
  checkBestPractices: boolean
  checkAccessibility: boolean
  checkMaintainability: boolean
}

const SEVERITY_CONFIG: Record<Severity, { icon: React.ReactNode; bg: string; border: string; text: string }> = {
  error: {
    icon: <AlertCircle className="w-4 h-4" />,
    bg: 'bg-[rgba(244,135,113,0.2)]',
    border: 'border-[#f48771]',
    text: 'text-[#f48771]',
  },
  warning: {
    icon: <AlertTriangle className="w-4 h-4" />,
    bg: 'bg-[rgba(255,215,0,0.2)]',
    border: 'border-[#ffd700]',
    text: 'text-[#ffd700]',
  },
  info: {
    icon: <Info className="w-4 h-4" />,
    bg: 'bg-[rgba(91,206,250,0.2)]',
    border: 'border-[#5bcefa]',
    text: 'text-[#5bcefa]',
  },
  suggestion: {
    icon: <Sparkles className="w-4 h-4" />,
    bg: 'bg-[rgba(157,0,255,0.2)]',
    border: 'border-[#9d00ff]',
    text: 'text-[#9d00ff]',
  },
}

function loadHistory(): CodeReview[] {
  try {
    const stored = localStorage.getItem(HISTORY_KEY)
    if (stored) {
      const parsed = JSON.parse(stored)
      if (Array.isArray(parsed)) return parsed.slice(0, 20)
    }
  } catch {
    // Invalid storage
  }
  return []
}

function saveHistory(history: CodeReview[]) {
  try {
    localStorage.setItem(HISTORY_KEY, JSON.stringify(history.slice(0, 20)))
  } catch {
    // Storage unavailable
  }
}

interface AICodeReviewPanelProps {
  onFileClick?: (filePath: string, line?: number) => void
}

export function AICodeReviewPanel({ onFileClick }: AICodeReviewPanelProps) {
  const [code, setCode] = useState('')
  const [fileName, setFileName] = useState('')
  const [language, setLanguage] = useState('typescript')
  const [reviewing, setReviewing] = useState(false)
  const [currentReview, setCurrentReview] = useState<CodeReview | null>(null)
  const [history, setHistory] = useState<CodeReview[]>(() => loadHistory())
  const [expandedIssues, setExpandedIssues] = useState<Set<string>>(new Set())
  const [showConfig, setShowConfig] = useState(false)
  const [copied, setCopied] = useState<string | null>(null)
  const [config, setConfig] = useState<ReviewConfig>({
    checkSecurity: true,
    checkPerformance: true,
    checkBestPractices: true,
    checkAccessibility: false,
    checkMaintainability: true,
  })

  useEffect(() => {
    saveHistory(history)
  }, [history])

  const reviewCode = async () => {
    if (!code.trim()) return

    setReviewing(true)

    try {
      const response = await http.post('/nexus/ai/review', {
        code,
        language,
        fileName,
        config,
      })

      if (response.ok) {
        const data = await response.json()
        const review: CodeReview = {
          ...data,
          id: crypto.randomUUID(),
          code,
          fileName: fileName || 'untitled',
          language,
          reviewedAt: Date.now(),
        }
        setCurrentReview(review)
        setHistory([review, ...history].slice(0, 20))
      } else {
        // Demo review
        const review = getDemoReview()
        setCurrentReview(review)
        setHistory([review, ...history].slice(0, 20))
      }
    } catch {
      // Demo review
      const review = getDemoReview()
      setCurrentReview(review)
      setHistory([review, ...history].slice(0, 20))
    } finally {
      setReviewing(false)
    }
  }

  const getDemoReview = (): CodeReview => ({
    id: crypto.randomUUID(),
    fileName: fileName || 'untitled.ts',
    language,
    code,
    summary: 'The code is generally well-structured but has a few areas for improvement. Security considerations and error handling could be enhanced.',
    score: 72,
    reviewedAt: Date.now(),
    issues: [
      {
        id: '1',
        severity: 'error',
        title: 'Potential XSS vulnerability',
        description: 'Using innerHTML with user input can lead to cross-site scripting attacks. Consider using textContent or sanitizing the input.',
        lineStart: 15,
        lineEnd: 15,
        suggestion: 'element.textContent = userInput;',
      },
      {
        id: '2',
        severity: 'warning',
        title: 'Missing error handling',
        description: 'The async function does not have a try-catch block, which could lead to unhandled promise rejections.',
        lineStart: 8,
        lineEnd: 12,
        suggestion: 'Wrap the async operation in a try-catch block and handle errors appropriately.',
      },
      {
        id: '3',
        severity: 'info',
        title: 'Consider using const instead of let',
        description: 'The variable is never reassigned, so using const would be more appropriate and clearer.',
        lineStart: 3,
        suggestion: 'const data = fetchData();',
      },
      {
        id: '4',
        severity: 'suggestion',
        title: 'Extract magic number to named constant',
        description: 'The value 1000 appears to be a timeout. Consider extracting it to a named constant for better readability.',
        lineStart: 20,
        suggestion: 'const TIMEOUT_MS = 1000;',
      },
    ],
  })

  const toggleIssue = (id: string) => {
    setExpandedIssues(prev => {
      const next = new Set(prev)
      if (next.has(id)) {
        next.delete(id)
      } else {
        next.add(id)
      }
      return next
    })
  }

  const copySuggestion = (id: string, text: string) => {
    navigator.clipboard.writeText(text)
    setCopied(id)
    setTimeout(() => setCopied(null), 2000)
  }

  const getScoreColor = (score: number) => {
    if (score >= 80) return 'text-[#00ff7f]'
    if (score >= 60) return 'text-[#ffd700]'
    return 'text-[#f48771]'
  }

  const getScoreBg = (score: number) => {
    if (score >= 80) return 'bg-[rgba(0,255,127,0.2)] border-[#00ff7f]'
    if (score >= 60) return 'bg-[rgba(255,215,0,0.2)] border-[#ffd700]'
    return 'bg-[rgba(244,135,113,0.2)] border-[#f48771]'
  }

  const issueCounts = currentReview?.issues.reduce<Record<Severity, number>>(
    (acc, issue) => {
      acc[issue.severity] = (acc[issue.severity] || 0) + 1
      return acc
    },
    { error: 0, warning: 0, info: 0, suggestion: 0 }
  ) || { error: 0, warning: 0, info: 0, suggestion: 0 }

  return (
    <div className="flex flex-col h-full bg-[#1e1e1e] text-[#cccccc] overflow-hidden">
      {/* Header */}
      <div className="p-3 border-b border-[#3c3c3c] bg-[#252526]">
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-2">
            <Sparkles className="w-4 h-4 text-[#9d00ff]" />
            <span className="text-sm font-medium text-white">AI Code Review</span>
          </div>
          <div className="flex items-center gap-2">
            <Button
              size="sm"
              variant="ghost"
              onClick={() => setShowConfig(!showConfig)}
              className="h-7 w-7 p-0"
              aria-label="Settings"
            >
              <Settings className={`w-3.5 h-3.5 ${showConfig ? 'text-[#5bcefa]' : ''}`} />
            </Button>
            <Button
              size="sm"
              onClick={reviewCode}
              disabled={reviewing || !code.trim()}
            >
              {reviewing ? (
                <Spinner size="sm" />
              ) : (
                <>
                  <Play className="w-3.5 h-3.5 mr-1.5" />
                  Review
                </>
              )}
            </Button>
          </div>
        </div>

        {showConfig && (
          <div className="flex flex-wrap gap-2 mb-3 p-2 bg-[#2d2d30] rounded">
            {(Object.keys(config) as (keyof ReviewConfig)[]).map(key => (
              <label key={key} className="flex items-center gap-1.5 text-xs cursor-pointer">
                <input
                  type="checkbox"
                  checked={config[key]}
                  onChange={(e) => setConfig({ ...config, [key]: e.target.checked })}
                  className="w-3.5 h-3.5 rounded"
                />
                <span className="text-[#b0b0b0]">
                  {key.replace('check', '').replace(/([A-Z])/g, ' $1').trim()}
                </span>
              </label>
            ))}
          </div>
        )}

        <div className="flex gap-2">
          <input
            type="text"
            placeholder="File name (optional)"
            value={fileName}
            onChange={(e) => setFileName(e.target.value)}
            className="w-40 px-2 py-1.5 text-sm bg-[#3c3c3c] border border-[#3c3c3c] rounded text-white placeholder-[#808080] focus:outline-none focus:border-[#5bcefa]"
          />
          <select
            value={language}
            onChange={(e) => setLanguage(e.target.value)}
            className="px-2 py-1.5 text-sm bg-[#3c3c3c] border border-[#3c3c3c] rounded text-white focus:outline-none focus:border-[#5bcefa]"
          >
            <option value="typescript">TypeScript</option>
            <option value="javascript">JavaScript</option>
            <option value="python">Python</option>
            <option value="java">Java</option>
            <option value="go">Go</option>
            <option value="rust">Rust</option>
            <option value="csharp">C#</option>
            <option value="cpp">C++</option>
          </select>
        </div>
      </div>

      {/* Code Input */}
      <div className="p-3 border-b border-[#3c3c3c]">
        <textarea
          value={code}
          onChange={(e) => setCode(e.target.value)}
          placeholder="Paste your code here for AI review..."
          className="w-full h-32 p-3 text-sm bg-[#2d2d30] border border-[#3c3c3c] rounded text-white font-mono placeholder-[#808080] focus:outline-none focus:border-[#5bcefa] resize-none"
        />
      </div>

      {/* Review Results */}
      <div className="flex-1 overflow-auto">
        {reviewing && (
          <div className="flex flex-col items-center justify-center h-full gap-3">
            <Spinner size="lg" />
            <div className="text-sm text-[#b0b0b0]">Analyzing code...</div>
          </div>
        )}

        {currentReview && !reviewing && (
          <div className="p-3">
            {/* Score */}
            <div className={`p-4 rounded-lg border mb-4 ${getScoreBg(currentReview.score)}`}>
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm font-medium text-white">Code Quality Score</span>
                <span className={`text-3xl font-bold ${getScoreColor(currentReview.score)}`}>
                  {currentReview.score}/100
                </span>
              </div>
              <p className="text-xs text-[#b0b0b0]">{currentReview.summary}</p>
            </div>

            {/* Issue Summary */}
            <div className="flex gap-3 mb-4">
              {(Object.entries(SEVERITY_CONFIG) as [Severity, typeof SEVERITY_CONFIG.error][]).map(([sev, cfg]) => (
                <div
                  key={sev}
                  className={`flex items-center gap-1.5 px-2 py-1 rounded ${cfg.bg} border ${cfg.border}`}
                >
                  <span className={cfg.text}>{cfg.icon}</span>
                  <span className={`text-xs font-medium ${cfg.text}`}>
                    {issueCounts[sev]} {sev}
                  </span>
                </div>
              ))}
            </div>

            {/* Issues */}
            <div className="space-y-2">
              {currentReview.issues.map(issue => {
                const cfg = SEVERITY_CONFIG[issue.severity]
                const isExpanded = expandedIssues.has(issue.id)

                return (
                  <div
                    key={issue.id}
                    className={`rounded border ${cfg.border} overflow-hidden`}
                  >
                    <div
                      className={`flex items-center gap-2 p-3 cursor-pointer ${cfg.bg}`}
                      onClick={() => toggleIssue(issue.id)}
                    >
                      {isExpanded ? (
                        <ChevronDown className={`w-4 h-4 ${cfg.text}`} />
                      ) : (
                        <ChevronRight className={`w-4 h-4 ${cfg.text}`} />
                      )}
                      <span className={cfg.text}>{cfg.icon}</span>
                      <span className="text-sm font-medium text-white flex-1">{issue.title}</span>
                      {issue.lineStart && (
                        <span className="text-xs text-[#808080]">
                          Line {issue.lineStart}
                          {issue.lineEnd && issue.lineEnd !== issue.lineStart && `-${issue.lineEnd}`}
                        </span>
                      )}
                    </div>

                    {isExpanded && (
                      <div className="p-3 bg-[#252526] border-t border-[#3c3c3c]">
                        <p className="text-sm text-[#b0b0b0] mb-3">{issue.description}</p>
                        {issue.suggestion && (
                          <div className="flex items-start gap-2 p-2 bg-[#2d2d30] rounded">
                            <div className="flex-1">
                              <div className="text-[10px] text-[#808080] uppercase mb-1">Suggestion</div>
                              <pre className="text-xs text-white font-mono whitespace-pre-wrap">
                                {issue.suggestion}
                              </pre>
                            </div>
                            <button
                              onClick={() => copySuggestion(issue.id, issue.suggestion!)}
                              className="p-1 rounded hover:bg-[#3c3c3c] transition-colors"
                              aria-label="Copy suggestion"
                            >
                              {copied === issue.id ? (
                                <Check className="w-3.5 h-3.5 text-[#00ff7f]" />
                              ) : (
                                <Copy className="w-3.5 h-3.5 text-[#808080]" />
                              )}
                            </button>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                )
              })}
            </div>

            {currentReview.issues.length === 0 && (
              <div className="flex flex-col items-center justify-center py-8 text-center">
                <CheckCircle className="w-8 h-8 text-[#00ff7f] mb-3" />
                <div className="text-sm text-white font-medium">No issues found!</div>
                <div className="text-xs text-[#858585]">Your code looks great.</div>
              </div>
            )}
          </div>
        )}

        {!reviewing && !currentReview && (
          <div className="flex flex-col items-center justify-center h-full text-center p-6">
            <Sparkles className="w-8 h-8 text-[#858585] mb-3" />
            <div className="text-sm text-[#cccccc] font-medium">Ready to review</div>
            <div className="text-xs text-[#858585]">Paste your code and click Review</div>
          </div>
        )}
      </div>
    </div>
  )
}

