import React, { useState, useEffect, useCallback } from 'react'
import { AlertCircle, Check, Wand2 } from 'lucide-react'

interface JsonEditorProps {
  value: string
  onChange: (value: string) => void
  placeholder?: string
  minHeight?: string
  maxHeight?: string
  label?: string
  required?: boolean
}

export function JsonEditor({
  value,
  onChange,
  placeholder = '{"key": "value"}',
  minHeight = '8rem',
  maxHeight,
  label,
  required = false,
}: JsonEditorProps) {
  const [error, setError] = useState<string | null>(null)
  const [isValid, setIsValid] = useState(false)

  // Validate JSON on value change
  useEffect(() => {
    if (!value.trim()) {
      setError(null)
      setIsValid(false)
      return
    }

    try {
      JSON.parse(value)
      setError(null)
      setIsValid(true)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Invalid JSON')
      setIsValid(false)
    }
  }, [value])

  // Format JSON
  const handleFormat = useCallback(() => {
    if (!value.trim()) return

    try {
      const parsed = JSON.parse(value)
      onChange(JSON.stringify(parsed, null, 2))
    } catch {
      // Can't format invalid JSON
    }
  }, [value, onChange])

  // Minify JSON
  const handleMinify = useCallback(() => {
    if (!value.trim()) return

    try {
      const parsed = JSON.parse(value)
      onChange(JSON.stringify(parsed))
    } catch {
      // Can't minify invalid JSON
    }
  }, [value, onChange])

  return (
    <div className="space-y-1">
      {label && (
        <div className="flex items-center justify-between">
          <label className="text-xs text-[#808080] flex items-center gap-1">
            {label}
            {required && <span className="text-[#f48771]">*</span>}
          </label>
          <div className="flex items-center gap-1">
            {isValid && (
              <span className="text-[10px] text-[#00ff7f] flex items-center gap-1">
                <Check className="w-3 h-3" />
                Valid
              </span>
            )}
            {value.trim() && isValid && (
              <>
                <button
                  onClick={handleFormat}
                  className="text-[10px] text-[#5bcefa] hover:text-[#7dd3fc] px-1.5 py-0.5 rounded hover:bg-[#3c3c3c]"
                  title="Format JSON"
                >
                  Format
                </button>
                <button
                  onClick={handleMinify}
                  className="text-[10px] text-[#5bcefa] hover:text-[#7dd3fc] px-1.5 py-0.5 rounded hover:bg-[#3c3c3c]"
                  title="Minify JSON"
                >
                  Minify
                </button>
              </>
            )}
          </div>
        </div>
      )}

      <div className="relative">
        <textarea
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          className={`w-full p-3 text-sm bg-[#2d2d30] border rounded text-white font-mono resize-y focus:outline-none ${
            error
              ? 'border-[#f48771] focus:border-[#f48771]'
              : 'border-[#3c3c3c] focus:border-[#5bcefa]'
          }`}
          style={{
            minHeight,
            maxHeight: maxHeight || undefined,
          }}
          spellCheck={false}
          aria-label={label || 'JSON input'}
          aria-invalid={!!error}
          aria-describedby={error ? 'json-error' : undefined}
        />

        {/* Line numbers gutter could be added here if needed */}
      </div>

      {error && (
        <div
          id="json-error"
          className="flex items-start gap-1.5 text-xs text-[#f48771] bg-[rgba(244,135,113,0.1)] px-2 py-1.5 rounded"
          role="alert"
        >
          <AlertCircle className="w-3.5 h-3.5 mt-0.5 flex-shrink-0" />
          <span>{error}</span>
        </div>
      )}
    </div>
  )
}

// Standalone validation function
export function validateJson(value: string): { valid: boolean; error?: string } {
  if (!value.trim()) {
    return { valid: true }
  }

  try {
    JSON.parse(value)
    return { valid: true }
  } catch (err) {
    return {
      valid: false,
      error: err instanceof Error ? err.message : 'Invalid JSON',
    }
  }
}

// Format JSON string
export function formatJson(value: string): string {
  try {
    return JSON.stringify(JSON.parse(value), null, 2)
  } catch {
    return value
  }
}

// Minify JSON string
export function minifyJson(value: string): string {
  try {
    return JSON.stringify(JSON.parse(value))
  } catch {
    return value
  }
}

