export function DependencyViewerPanel() {
  const [dependencies, setDependencies] = useState<Dependency[]>([])
  const [loading, setLoading] = useState(true)
  const [checking, setChecking] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [filter, setFilter] = useState('')
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set(['dependencies']))
  const [showOutdatedOnly, setShowOutdatedOnly] = useState(false)

  const fetchDependencies = async () => {
    try {
      setLoading(true)
      setError(null)
      const response = await http.get('/nexus/dependencies')
      if (response.ok) {
        const data = await response.json()
        setDependencies(data)
      } else if (response.status === 404) {
        setDependencies(getDemoDependencies())
      } else {
        setError('Failed to load dependencies')
      }
    } catch {
      setDependencies(getDemoDependencies())
    } finally {
      setLoading(false)
    }
  }

  const checkForUpdates = async () => {
    try {
      setChecking(true)
      const response = await http.post('/nexus/dependencies/check-updates', {})
      if (response.ok) {
        await fetchDependencies()
      }
    } catch {
      // Check failed silently
    } finally {
      setChecking(false)
    }
  }

  useEffect(() => {
    fetchDependencies()
  }, [])

  const getDemoDependencies = (): Dependency[] => [
    { name: 'react', currentVersion: '18.2.0', latestVersion: '18.2.0', type: 'dependencies', hasUpdate: false, isOutdated: false, hasVulnerability: false },
    { name: 'react-dom', currentVersion: '18.2.0', latestVersion: '18.2.0', type: 'dependencies', hasUpdate: false, isOutdated: false, hasVulnerability: false },
    { name: 'typescript', currentVersion: '5.3.2', latestVersion: '5.9.0', type: 'devDependencies', hasUpdate: true, isOutdated: false, hasVulnerability: false },
    { name: 'vite', currentVersion: '5.0.0', latestVersion: '7.1.0', type: 'devDependencies', hasUpdate: true, isOutdated: true, hasVulnerability: false },
    { name: 'tailwindcss', currentVersion: '3.4.0', latestVersion: '3.4.1', type: 'devDependencies', hasUpdate: true, isOutdated: false, hasVulnerability: false },
    { name: 'eslint', currentVersion: '8.56.0', latestVersion: '9.0.0', type: 'devDependencies', hasUpdate: true, isOutdated: true, hasVulnerability: false },
    { name: 'lodash', currentVersion: '4.17.20', latestVersion: '4.17.21', type: 'dependencies', hasUpdate: true, isOutdated: false, hasVulnerability: true, vulnerabilitySeverity: 'high' },
    { name: 'axios', currentVersion: '1.6.0', latestVersion: '1.6.5', type: 'dependencies', hasUpdate: true, isOutdated: false, hasVulnerability: false },
    { name: 'zustand', currentVersion: '4.4.7', latestVersion: '4.5.0', type: 'dependencies', hasUpdate: true, isOutdated: false, hasVulnerability: false },
    { name: 'lucide-react', currentVersion: '0.294.0', latestVersion: '0.300.0', type: 'dependencies', hasUpdate: true, isOutdated: false, hasVulnerability: false },
  ]

  const toggleGroup = (type: string) => {
    setExpandedGroups(prev => {
      const next = new Set(prev)
      if (next.has(type)) {
        next.delete(type)
      } else {
        next.add(type)
      }
      return next
    })
  }

  const filteredDeps = dependencies.filter(dep => {
    const matchesFilter = dep.name.toLowerCase().includes(filter.toLowerCase())
    const matchesOutdated = !showOutdatedOnly || dep.hasUpdate
    return matchesFilter && matchesOutdated
  })

  const groups: DependencyGroup[] = [
    { type: 'dependencies', label: 'Dependencies', deps: filteredDeps.filter(d => d.type === 'dependencies') },
    { type: 'devDependencies', label: 'Dev Dependencies', deps: filteredDeps.filter(d => d.type === 'devDependencies') },
    { type: 'peerDependencies', label: 'Peer Dependencies', deps: filteredDeps.filter(d => d.type === 'peerDependencies') },
  ].filter(g => g.deps.length > 0)

  const stats = {
    total: dependencies.length,
    outdated: dependencies.filter(d => d.hasUpdate).length,
    majorOutdated: dependencies.filter(d => d.isOutdated).length,
    vulnerable: dependencies.filter(d => d.hasVulnerability).length,
  }

  const getSeverityStyle = (severity?: string) => {
    switch (severity) {
      case 'critical':
        return 'bg-[rgba(220,38,38,0.2)] text-[#ef4444] border-[#ef4444]'
      case 'high':
        return 'bg-[rgba(244,135,113,0.2)] text-[#f48771] border-[#f48771]'
      case 'moderate':
        return 'bg-[rgba(255,215,0,0.2)] text-[#ffd700] border-[#ffd700]'
      default:
        return 'bg-[rgba(91,206,250,0.2)] text-[#5bcefa] border-[#5bcefa]'
    }
  }

  if (loading) {
    return (
      <div className="flex flex-col h-full bg-[#1e1e1e] text-[#cccccc] overflow-hidden">
        <div className="flex flex-col items-center justify-center h-full gap-3">
          <Spinner size="lg" />
          <div className="text-sm text-[#b0b0b0]">Loading dependencies...</div>
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className="flex flex-col h-full bg-[#1e1e1e] text-[#cccccc] overflow-hidden">
        <div className="flex flex-col items-center justify-center h-full p-6">
          <div className="p-3 bg-[#5a1d1d] rounded-full mb-4">
            <AlertTriangle className="w-8 h-8 text-[#f48771]" />
          </div>
          <div className="text-sm text-[#f48771] font-medium mb-2">Failed to load dependencies</div>
          <div className="text-xs text-[#858585] text-center mb-4">{error}</div>
          <Button size="sm" variant="outline" onClick={fetchDependencies}>
            <RefreshCw className="w-3.5 h-3.5 mr-1.5" />
            Retry
          </Button>
        </div>
      </div>
    )
  }

  return (
    <div className="flex flex-col h-full bg-[#1e1e1e] text-[#cccccc] overflow-hidden">
      <div className="p-3 border-b border-[#3c3c3c] bg-[#252526]">
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-2">
            <Package className="w-4 h-4 text-[#5bcefa]" />
            <span className="text-sm font-medium text-white">Dependencies</span>
            <span className="text-xs text-[#808080]">({stats.total})</span>
          </div>
          <Button
            size="sm"
            variant="ghost"
            onClick={checkForUpdates}
            disabled={checking}
            className="h-7 px-2"
            aria-label="Check for updates"
          >
            <RefreshCw className={`w-3.5 h-3.5 mr-1.5 ${checking ? 'animate-spin' : ''}`} />
            {checking ? 'Checking...' : 'Check Updates'}
          </Button>
        </div>

        <div className="grid grid-cols-4 gap-2 mb-3">
          <div className="p-2 bg-[#2d2d30] rounded text-center">
            <div className="text-lg font-bold text-white">{stats.total}</div>
            <div className="text-[10px] text-[#808080] uppercase">Total</div>
          </div>
          <div className="p-2 bg-[#2d2d30] rounded text-center">
            <div className="text-lg font-bold text-[#ffd700]">{stats.outdated}</div>
            <div className="text-[10px] text-[#808080] uppercase">Updates</div>
          </div>
          <div className="p-2 bg-[#2d2d30] rounded text-center">
            <div className="text-lg font-bold text-[#f48771]">{stats.majorOutdated}</div>
            <div className="text-[10px] text-[#808080] uppercase">Major</div>
          </div>
          <div className="p-2 bg-[#2d2d30] rounded text-center">
            <div className="text-lg font-bold text-[#ef4444]">{stats.vulnerable}</div>
            <div className="text-[10px] text-[#808080] uppercase">Vulns</div>
          </div>
        </div>

        <div className="flex gap-2">
          <div className="flex-1 relative">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-[#808080]" />
            <input
              type="text"
              placeholder="Filter packages..."
              value={filter}
              onChange={(e) => setFilter(e.target.value)}
              className="w-full pl-8 pr-3 py-1.5 text-sm bg-[#3c3c3c] border border-[#3c3c3c] rounded text-white placeholder-[#808080] focus:outline-none focus:border-[#5bcefa]"
            />
          </div>
          <button
            onClick={() => setShowOutdatedOnly(!showOutdatedOnly)}
            className={`px-2 py-1.5 text-xs rounded transition-colors ${
              showOutdatedOnly
                ? 'bg-[rgba(255,215,0,0.2)] text-[#ffd700] border border-[#ffd700]'
                : 'bg-[#3c3c3c] text-[#b0b0b0] hover:bg-[#4c4c4c]'
            }`}
          >
            <ArrowUp className="w-3.5 h-3.5" />
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-auto p-2">
        {groups.map(group => {
          const isExpanded = expandedGroups.has(group.type)
          return (
            <div key={group.type} className="mb-2">
              <div
                className="flex items-center gap-2 p-2 rounded-md cursor-pointer transition-all hover:bg-[#2d2d30]"
                onClick={() => toggleGroup(group.type)}
              >
                {isExpanded ? (
                  <ChevronDown className="w-4 h-4 text-[#808080]" />
                ) : (
                  <ChevronRight className="w-4 h-4 text-[#808080]" />
                )}
                <span className="text-sm font-medium text-white">{group.label}</span>
                <span className="text-xs text-[#808080]">({group.deps.length})</span>
              </div>

              {isExpanded && (
                <div className="ml-4">
                  {group.deps.map(dep => (
                    <div
                      key={dep.name}
                      className="flex items-center gap-2 p-2 rounded-md hover:bg-[#2d2d30] transition-colors"
                    >
                      <Package className="w-4 h-4 text-[#808080] flex-shrink-0" />
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <span className="text-sm text-white font-mono">{dep.name}</span>
                          {dep.hasVulnerability && (
                            <span className={`flex items-center gap-1 px-1.5 py-0.5 text-[10px] rounded border ${getSeverityStyle(dep.vulnerabilitySeverity)}`}>
                              <Shield className="w-3 h-3" />
                              {dep.vulnerabilitySeverity || 'vuln'}
                            </span>
                          )}
                        </div>
                        <div className="flex items-center gap-2 text-xs">
                          <span className="text-[#808080] font-mono">{dep.currentVersion}</span>
                          {dep.hasUpdate && dep.latestVersion && (
                            <>
                              <ArrowUp className={`w-3 h-3 ${dep.isOutdated ? 'text-[#f48771]' : 'text-[#ffd700]'}`} />
                              <span className={`font-mono ${dep.isOutdated ? 'text-[#f48771]' : 'text-[#ffd700]'}`}>
                                {dep.latestVersion}
                              </span>
                            </>
                          )}
                          {!dep.hasUpdate && (
                            <CheckCircle className="w-3 h-3 text-[#00ff7f]" />
                          )}
                        </div>
                      </div>
                      <a
                        href={`https://www.npmjs.com/package/${dep.name}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="p-1 rounded hover:bg-[#3c3c3c] transition-colors"
                        onClick={(e) => e.stopPropagation()}
                        aria-label={`View ${dep.name} on npm`}
                      >
                        <ExternalLink className="w-3.5 h-3.5 text-[#808080]" />
                      </a>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )
        })}

        {groups.length === 0 && (
          <div className="flex flex-col items-center justify-center h-full p-6 text-center">
            <div className="p-3 bg-[#252526] rounded-full mb-4">
              <Package className="w-8 h-8 text-[#858585]" />
            </div>
            <div className="text-sm text-[#cccccc] font-medium mb-1">No matching packages</div>
            <div className="text-xs text-[#858585]">Try a different search term</div>
          </div>
        )}
      </div>
    </div>
  )
}

