import React, { useState, useEffect, useRef } from 'react'
import { Input, Dialog, DialogContent } from '@persona-framework/ui'
import { Search } from 'lucide-react'

export interface Command {
  id: string
  title: string
  category: string
  shortcut?: string
  action: () => void
}

interface CommandPaletteProps {
  open: boolean
  onClose: () => void
  commands: Command[]
}

export function CommandPalette({ open, onClose, commands }: CommandPaletteProps) {
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedIndex, setSelectedIndex] = useState(0)
  const inputRef = useRef<HTMLInputElement>(null)
  const itemRefs = useRef<(HTMLDivElement | null)[]>([])

  useEffect(() => {
    if (open && inputRef.current) {
      setTimeout(() => inputRef.current?.focus(), 100)
      setSearchQuery('')
      setSelectedIndex(0)
    }
  }, [open])

  const fuzzyMatch = (text: string, query: string): boolean => {
    if (!query) return true
    const lowerText = text.toLowerCase()
    const lowerQuery = query.toLowerCase()
    let queryIndex = 0
    for (let i = 0; i < lowerText.length && queryIndex < lowerQuery.length; i++) {
      if (lowerText[i] === lowerQuery[queryIndex]) {
        queryIndex++
      }
    }
    return queryIndex === lowerQuery.length
  }

  const filteredCommands = commands.filter(cmd =>
    fuzzyMatch(cmd.title, searchQuery) || fuzzyMatch(cmd.category, searchQuery)
  )

  const groupedCommands = filteredCommands.reduce((acc, cmd) => {
    if (!acc[cmd.category]) {
      acc[cmd.category] = []
    }
    acc[cmd.category].push(cmd)
    return acc
  }, {} as Record<string, Command[]>)

  const flatCommands = filteredCommands

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!open) return

      switch (e.key) {
        case 'ArrowDown':
          e.preventDefault()
          setSelectedIndex(prev => (prev + 1) % flatCommands.length)
          break
        case 'ArrowUp':
          e.preventDefault()
          setSelectedIndex(prev => (prev - 1 + flatCommands.length) % flatCommands.length)
          break
        case 'Enter':
          e.preventDefault()
          if (flatCommands[selectedIndex]) {
            flatCommands[selectedIndex].action()
            onClose()
          }
          break
        case 'Escape':
          e.preventDefault()
          onClose()
          break
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [open, flatCommands, selectedIndex, onClose])

  useEffect(() => {
    if (itemRefs.current[selectedIndex]) {
      itemRefs.current[selectedIndex]?.scrollIntoView({
        block: 'nearest',
        behavior: 'smooth',
      })
    }
  }, [selectedIndex])

  if (!open) return null

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-[600px] w-[90vw] max-h-[500px] p-0 overflow-hidden bg-[#252526] border border-[#3c3c3c]">
        <div className="p-3 border-b border-[#3c3c3c] bg-[#1e1e1e]">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-[#858585]" />
            <Input
              ref={inputRef}
              value={searchQuery}
              onChange={(e) => {
                setSearchQuery(e.target.value)
                setSelectedIndex(0)
              }}
              placeholder="Type a command or search..."
              className="w-full bg-[#3c3c3c] border-none text-[#cccccc] text-sm pl-10 pr-16 placeholder:text-[#858585]"
            />
            {searchQuery && (
              <span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-[#858585]">
                {filteredCommands.length} result{filteredCommands.length !== 1 ? 's' : ''}
              </span>
            )}
          </div>
        </div>

        <div className="max-h-[400px] overflow-y-auto p-1">
          {flatCommands.length === 0 ? (
            <div className="py-10 px-5 text-center text-[#858585] text-sm">
              No commands found for "{searchQuery}"
            </div>
          ) : (
            Object.entries(groupedCommands).map(([category, cmds]) => (
              <div key={category}>
                <div className="text-xs font-semibold text-[#858585] px-3 pt-2 pb-1 uppercase tracking-wide">
                  {category}
                </div>
                {cmds.map((cmd) => {
                  const flatIndex = flatCommands.indexOf(cmd)
                  return (
                    <div
                      key={cmd.id}
                      ref={el => (itemRefs.current[flatIndex] = el)}
                      className={`flex items-center justify-between py-2.5 px-3 cursor-pointer rounded text-sm text-[#cccccc] transition-colors ${
                        flatIndex === selectedIndex
                          ? 'bg-[#094771] hover:bg-[#0e5a8a]'
                          : 'hover:bg-[#2a2d2e]'
                      }`}
                      onClick={() => {
                        cmd.action()
                        onClose()
                      }}
                      onMouseEnter={() => setSelectedIndex(flatIndex)}
                    >
                      <div className="flex flex-col gap-0.5">
                        <div className="font-medium text-[#cccccc]">{cmd.title}</div>
                      </div>
                      {cmd.shortcut && (
                        <div className="text-xs text-[#858585] bg-[#3c3c3c] px-1.5 py-0.5 rounded font-mono">
                          {cmd.shortcut}
                        </div>
                      )}
                    </div>
                  )
                })}
              </div>
            ))
          )}
        </div>
      </DialogContent>
    </Dialog>
  )
}

import { useState, useEffect, useRef } from 'react'
import Editor from '@monaco-editor/react'
import { Button } from '@persona-framework/ui'
import { Save, Loader2, Check } from 'lucide-react'
import { getDefaultApiClient } from '@shared/api/client'
import { AICodeAssistant } from './AICodeAssistant'
import { CollaborativeEditor } from './CollaborativeEditor'
import { getMonacoLanguage } from '../config/languages'
import type * as Monaco from 'monaco-editor'

interface EditorSettings {
  theme?: 'dark' | 'light' | 'high-contrast'
  fontSize?: number
  fontFamily?: string
  tabSize?: number
  insertSpaces?: boolean
  wordWrap?: boolean
  lineNumbers?: boolean
  minimap?: boolean
  renderWhitespace?: boolean
  cursorBlinking?: 'blink' | 'smooth' | 'phase' | 'expand' | 'solid'
  cursorStyle?: 'line' | 'block' | 'underline'
}

interface CodeEditorProps {
  filePath: string | null
  settings?: EditorSettings
}

export function CodeEditor({ filePath, settings }: CodeEditorProps) {
  const [content, setContent] = useState<string>('')
  const [loading, setLoading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saved' | 'error'>('idle')
  const [error, setError] = useState<string | null>(null)
  const [isDirty, setIsDirty] = useState(false)
  const editorRef = useRef<Monaco.editor.IStandaloneCodeEditor | null>(null)

  const handleSave = async () => {
    if (!filePath || !isDirty || saving) return

    setSaving(true)
    setSaveStatus('idle')

    try {
      const client = getDefaultApiClient()
      await client.post('/project/file', { path: filePath, content })
      setIsDirty(false)
      setError(null)
      setSaveStatus('saved')
      // Reset saved indicator after 2 seconds
      setTimeout(() => setSaveStatus('idle'), 2000)
    } catch (err: any) {
      setError(err.message || 'Failed to save file')
      setSaveStatus('error')
    } finally {
      setSaving(false)
    }
  }

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 's') {
        e.preventDefault()
        handleSave()
      }
    }
    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [filePath, isDirty, content])

  useEffect(() => {
    if (!filePath) {
      setContent('')
      setError(null)
      setIsDirty(false)
      return
    }

    setLoading(true)
    setError(null)
    setIsDirty(false)

    const absolutePath = filePath.startsWith('/') ? filePath : `/workspace/persona-framework/${filePath}`

    fetch(`/api/project/read?path=${encodeURIComponent(absolutePath)}`)
      .then(response => {
        if (!response.ok) {
          if (response.status === 404) {
            throw new Error('API endpoint /api/project/read not found. Backend support needed.')
          }
          throw new Error(`Failed to read file: ${response.statusText}`)
        }
        return response.json()
      })
      .then(data => {
        setContent(data.content || '')
        setLoading(false)
      })
      .catch(err => {
        setError(err.message)
        setLoading(false)
      })
  }, [filePath])

  const getLanguage = (path: string | null): string => {
    if (!path) return 'plaintext'
    return getMonacoLanguage(path)
  }

  if (!filePath) {
    return (
      <div className="w-full h-full flex flex-col bg-[#1e1e1e]">
        <div className="p-5 text-center text-[#858585]">
          Select a file from the workspace to view
        </div>
      </div>
    )
  }

  if (loading) {
    return (
      <div className="w-full h-full flex flex-col bg-[#1e1e1e]">
        <div className="flex items-center gap-2 px-3 py-2 bg-[#2b2b2b] border-b border-[#3c3c3c] text-[#cccccc] text-xs font-mono">
          {filePath}
        </div>
        <div className="p-5 text-center text-[#858585]">Loading...</div>
      </div>
    )
  }

  if (error) {
    return (
      <div className="w-full h-full flex flex-col bg-[#1e1e1e]">
        <div className="flex items-center gap-2 px-3 py-2 bg-[#2b2b2b] border-b border-[#3c3c3c] text-[#cccccc] text-xs font-mono">
          {filePath}
        </div>
        <div className="p-5 text-[#f48771]">{error}</div>
      </div>
    )
  }

  return (
    <div className="w-full h-full flex flex-col bg-[#1e1e1e]">
      <div className="flex items-center gap-2 px-3 py-2 bg-[#2b2b2b] border-b border-[#3c3c3c] text-[#cccccc] text-xs font-mono">
        <span>{filePath}</span>
        {isDirty && <span className="text-[#f59e0b] ml-2" title="Unsaved changes">●</span>}

        {/* Save status indicator */}
        <div className="ml-auto flex items-center gap-2">
          {saveStatus === 'saved' && (
            <span className="flex items-center gap-1 text-[#4ade80] text-xs animate-in fade-in duration-200">
              <Check className="w-3 h-3" />
              Saved
            </span>
          )}
          {saveStatus === 'error' && (
            <span className="text-[#f48771] text-xs">Save failed</span>
          )}

          <Button
            variant="ghost"
            size="sm"
            onClick={handleSave}
            disabled={!isDirty || saving}
            title="Save (Ctrl+S)"
          >
            {saving ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
              <Save className="w-4 h-4" />
            )}
          </Button>
        </div>
      </div>
      <div className="flex-1 min-h-0 relative">
        <Editor
          height="100%"
          language={getLanguage(filePath)}
          value={content}
          theme={settings?.theme === 'light' ? 'vs-light' : settings?.theme === 'high-contrast' ? 'hc-black' : 'vs-dark'}
