import React, { useRef, useEffect, useCallback, ReactNode } from 'react'

interface FocusTrapProps {
  children: ReactNode
  active?: boolean
  returnFocusOnDeactivate?: boolean
  autoFocus?: boolean
}

const FOCUSABLE_SELECTORS = [
  'a[href]:not([disabled])',
  'button:not([disabled])',
  'textarea:not([disabled])',
  'input:not([disabled])',
  'select:not([disabled])',
  '[tabindex]:not([tabindex="-1"])',
].join(', ')

export function FocusTrap({
  children,
  active = true,
  returnFocusOnDeactivate = true,
  autoFocus = true,
}: FocusTrapProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const previouslyFocusedRef = useRef<Element | null>(null)

  const getFocusableElements = useCallback(() => {
    if (!containerRef.current) return []
    return Array.from(containerRef.current.querySelectorAll(FOCUSABLE_SELECTORS))
  }, [])

  const focusFirst = useCallback(() => {
    const elements = getFocusableElements()
    if (elements.length > 0) {
      (elements[0] as HTMLElement).focus()
    }
  }, [getFocusableElements])

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (!active || e.key !== 'Tab') return

    const elements = getFocusableElements()
    if (elements.length === 0) return

    const firstElement = elements[0] as HTMLElement
    const lastElement = elements[elements.length - 1] as HTMLElement

    if (e.shiftKey) {
      // Shift+Tab: if on first element, move to last
      if (document.activeElement === firstElement) {
        e.preventDefault()
        lastElement.focus()
      }
    } else {
      // Tab: if on last element, move to first
      if (document.activeElement === lastElement) {
        e.preventDefault()
        firstElement.focus()
      }
    }
  }, [active, getFocusableElements])

  useEffect(() => {
    if (!active) return

    // Store the currently focused element
    previouslyFocusedRef.current = document.activeElement

    // Auto-focus the first focusable element
    if (autoFocus) {
      // Use a small delay to ensure the DOM is ready
      const timeoutId = setTimeout(() => {
        focusFirst()
      }, 50)
      return () => clearTimeout(timeoutId)
    }
  }, [active, autoFocus, focusFirst])

  useEffect(() => {
    if (!active) return

    document.addEventListener('keydown', handleKeyDown)
    return () => {
      document.removeEventListener('keydown', handleKeyDown)

      // Return focus to previously focused element
      if (returnFocusOnDeactivate && previouslyFocusedRef.current) {
        (previouslyFocusedRef.current as HTMLElement).focus?.()
      }
    }
  }, [active, handleKeyDown, returnFocusOnDeactivate])

  // Handle focus escaping the trap
  useEffect(() => {
    if (!active) return

    const handleFocusIn = (e: FocusEvent) => {
      if (!containerRef.current) return

      // If focus moved outside the trap, bring it back
      if (!containerRef.current.contains(e.target as Node)) {
        focusFirst()
      }
    }

    document.addEventListener('focusin', handleFocusIn)
    return () => document.removeEventListener('focusin', handleFocusIn)
  }, [active, focusFirst])

  return (
    <div ref={containerRef} className="contents">
      {children}
    </div>
  )
}

import React, { useState, useEffect, useRef } from 'react'
import { Avatar } from '@persona-framework/ui'
import { User } from 'lucide-react'
import type * as Monaco from 'monaco-editor'

interface CollaborativeEditorProps {
  editor: Monaco.editor.IStandaloneCodeEditor | null
  filePath: string | null
  userId: string
  userName: string
  enabled?: boolean
}

interface User {
  id: string
  name: string
  color: string
  cursor: Monaco.IPosition | null
  selection: Monaco.IRange | null
  active: boolean
}

interface CursorUpdate {
  userId: string
  userName: string
  position: Monaco.IPosition
  selection?: Monaco.IRange
}

interface EditUpdate {
  userId: string
  userName: string
  changes: Monaco.editor.IModelContentChange[]
  versionId: number
}

const USER_COLORS = [
  '#ff6b6b',
  '#4ecdc4',
  '#45b7d1',
  '#f9ca24',
  '#6c5ce7',
  '#fd79a8',
  '#fdcb6e',
  '#00b894',
  '#e17055',
  '#a29bfe',
]

export function CollaborativeEditor({
  editor,
  filePath,
  userId,
  userName,
  enabled = true,
}: CollaborativeEditorProps) {
  const [activeUsers, setActiveUsers] = useState<Map<string, User>>(new Map())
  const [showUsersPanel, setShowUsersPanel] = useState(false)
  const wsRef = useRef<WebSocket | null>(null)
  const cursorDecorationsRef = useRef<Map<string, string[]>>(new Map())
  const suppressLocalUpdatesRef = useRef(false)

  useEffect(() => {
    if (!editor || !enabled || !filePath) return

    const ws = new WebSocket(`ws://localhost:8989/ws/collab`)

    ws.onopen = () => {
      console.log('[Collab] Connected to collaboration server')

      ws.send(
        JSON.stringify({
          type: 'join',
          userId,
          userName,
          filePath,
          color: getUserColor(userId),
        })
      )
    }

    ws.onmessage = (event) => {
      const message = JSON.parse(event.data)
      handleCollabMessage(message)
    }

    ws.onerror = (error) => {
      console.error('[Collab] WebSocket error:', error)
    }

    ws.onclose = () => {
      console.log('[Collab] Disconnected from collaboration server')
    }

    wsRef.current = ws

    const onDidChangeCursorPosition = editor.onDidChangeCursorPosition((e) => {
      if (ws.readyState === WebSocket.OPEN) {
        const selection = editor.getSelection()
        ws.send(
          JSON.stringify({
            type: 'cursor',
            userId,
            userName,
            filePath,
            position: e.position,
            selection: selection || undefined,
          })
        )
      }
    })

    const onDidChangeModelContent = editor.onDidChangeModelContent((e) => {
      if (suppressLocalUpdatesRef.current) return

      if (ws.readyState === WebSocket.OPEN) {
        ws.send(
          JSON.stringify({
            type: 'edit',
            userId,
            userName,
            filePath,
            changes: e.changes,
            versionId: e.versionId,
          })
        )
      }
    })

    return () => {
      if (ws.readyState === WebSocket.OPEN) {
        ws.send(
          JSON.stringify({
            type: 'leave',
            userId,
            filePath,
          })
        )
        ws.close()
      }

      onDidChangeCursorPosition.dispose()
      onDidChangeModelContent.dispose()
      wsRef.current = null
    }
  }, [editor, enabled, filePath, userId, userName])

  const handleCollabMessage = (message: any) => {
    if (!editor) return

    switch (message.type) {
      case 'user-joined':
        handleUserJoined(message)
        break

      case 'user-left':
        handleUserLeft(message)
        break

      case 'cursor-update':
        handleCursorUpdate(message)
        break

      case 'edit-update':
        handleEditUpdate(message)
        break

      case 'users-list':
        handleUsersList(message)
        break
    }
  }

  const handleUserJoined = (message: any) => {
    const { userId: joinedUserId, userName: joinedUserName, color } = message

    if (joinedUserId === userId) return

    setActiveUsers((prev) => {
      const newMap = new Map(prev)
      newMap.set(joinedUserId, {
        id: joinedUserId,
        name: joinedUserName,
        color,
        cursor: null,
        selection: null,
        active: true,
      })
      return newMap
    })

    console.log(`[Collab] ${joinedUserName} joined`)
  }

  const handleUserLeft = (message: any) => {
    const { userId: leftUserId } = message

    setActiveUsers((prev) => {
      const newMap = new Map(prev)
      newMap.delete(leftUserId)
      return newMap
    })

    removeCursorDecoration(leftUserId)
  }

  const handleCursorUpdate = (message: CursorUpdate) => {
    if (!editor || message.userId === userId) return

    setActiveUsers((prev) => {
      const newMap = new Map(prev)
      const user = newMap.get(message.userId)

      if (user) {
        newMap.set(message.userId, {
          ...user,
          cursor: message.position,
          selection: message.selection || null,
          active: true,
        })
      }

      return newMap
    })

    updateCursorDecoration(message)
  }

  const handleEditUpdate = (message: EditUpdate) => {
    if (!editor || message.userId === userId) return

    const model = editor.getModel()
    if (!model) return

    suppressLocalUpdatesRef.current = true

    model.pushEditOperations(
      [],
      message.changes.map((change) => ({
        range: change.range,
        text: change.text,
        forceMoveMarkers: true,
      })),
      () => null
    )

    suppressLocalUpdatesRef.current = false
  }

  const handleUsersList = (message: any) => {
    const { users } = message

    const usersMap = new Map<string, User>()
    users.forEach((user: any) => {
      if (user.userId !== userId) {
        usersMap.set(user.userId, {
          id: user.userId,
          name: user.userName,
          color: user.color,
          cursor: null,
          selection: null,
          active: true,
        })
      }
    })

    setActiveUsers(usersMap)
  }

  const updateCursorDecoration = (cursorUpdate: CursorUpdate) => {
    if (!editor) return

    const user = activeUsers.get(cursorUpdate.userId)
    if (!user) return

    const oldDecorations = cursorDecorationsRef.current.get(cursorUpdate.userId) || []

    const decorations: Monaco.editor.IModelDeltaDecoration[] = []

    if (cursorUpdate.position) {
      decorations.push({
        range: new (window as any).monaco.Range(
          cursorUpdate.position.lineNumber,
          cursorUpdate.position.column,
          cursorUpdate.position.lineNumber,
          cursorUpdate.position.column
        ),
        options: {
          className: 'remote-cursor',
          beforeContentClassName: 'remote-cursor-line',
          stickiness: 1,
          hoverMessage: { value: `**${cursorUpdate.userName}** is here` },
        },
      })
    }

    if (cursorUpdate.selection) {
      decorations.push({
        range: cursorUpdate.selection,
        options: {
          className: 'remote-selection',
          stickiness: 1,
          inlineClassName: `remote-selection-inline`,
        },
      })
    }

    const newDecorationIds = editor.deltaDecorations(oldDecorations, decorations)
    cursorDecorationsRef.current.set(cursorUpdate.userId, newDecorationIds)

    injectCursorStyle(cursorUpdate.userId, user.color)
  }

  const removeCursorDecoration = (userId: string) => {
    if (!editor) return

    const decorations = cursorDecorationsRef.current.get(userId) || []
    editor.deltaDecorations(decorations, [])
    cursorDecorationsRef.current.delete(userId)
  }

  const injectCursorStyle = (userId: string, color: string) => {
    const styleId = `collab-cursor-${userId}`
    let style = document.getElementById(styleId)

    if (!style) {
      style = document.createElement('style')
      style.id = styleId
      document.head.appendChild(style)
    }

    style.textContent = `
      .remote-cursor-${userId} {
        border-left: 2px solid ${color};
      }
      .remote-selection-${userId} {
        background-color: ${color}33;
      }
    `
  }

  const getUserColor = (id: string): string => {
    const hash = id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0)
    return USER_COLORS[hash % USER_COLORS.length]
  }

  if (!enabled) return null

  const usersArray = Array.from(activeUsers.values())

  return (
    <div className="relative w-full h-full">
      {usersArray.length > 0 && (
        <div className="absolute top-2 left-2 flex items-center gap-2 px-3 py-2 bg-[#2b2b2b] border border-[#3c3c3c] rounded-2xl z-[1000] text-[11px] text-[#cccccc] shadow-md">
          <div className="flex items-center gap-1 text-[#4fc3f7] font-medium">
            <User className="w-3.5 h-3.5" />
            <span>{usersArray.length + 1}</span>
          </div>

          <div
            className="flex items-center gap-1 cursor-pointer"
            onClick={() => setShowUsersPanel(!showUsersPanel)}
          >
            <Avatar
              className="w-6 h-6"
              style={{
                border: `2px solid ${getUserColor(userId)}`,
              }}
            >
              {userName.substring(0, 2).toUpperCase()}
            </Avatar>

            {usersArray.slice(0, 5).map((user) => (
              <Avatar
                key={user.id}
                className="w-6 h-6"
                style={{
                  border: `2px solid ${user.color}`,
                }}
              >
                {user.name.substring(0, 2).toUpperCase()}
              </Avatar>
            ))}

            {usersArray.length > 5 && (
              <Avatar className="w-6 h-6 bg-[#3c3c3c]">
                +{usersArray.length - 5}
              </Avatar>
            )}
          </div>
        </div>
      )}

      {showUsersPanel && (
        <div className="absolute top-14 left-3 w-[280px] bg-[#1e1e1e] border border-[#3c3c3c] rounded p-3 z-[1000] shadow-lg">
          <div className="text-sm font-semibold text-white mb-3 flex items-center">
            <User className="w-4 h-4 mr-2" />
            Active Users ({usersArray.length + 1})
          </div>

          <div className="flex items-center gap-3 p-2 rounded mb-1">
            <Avatar className="w-8 h-8">
              {userName.substring(0, 2).toUpperCase()}
            </Avatar>
            <div className="flex-1">
              <div className="text-xs text-[#cccccc]">{userName} (You)</div>
              <div className="text-[10px] text-[#858585]">Editing</div>
            </div>
            <div className="w-2 h-2 rounded-full bg-[#4ec9b0]" />
          </div>

          {usersArray.map((user) => (
            <div key={user.id} className="flex items-center gap-3 p-2 rounded mb-1">
              <Avatar className="w-8 h-8">
                {user.name.substring(0, 2).toUpperCase()}
              </Avatar>
              <div className="flex-1">
                <div className="text-xs text-[#cccccc]">{user.name}</div>
                <div className="text-[10px] text-[#858585]">
                  {user.active ? 'Editing' : 'Viewing'}
                </div>
              </div>
              <div
                className="w-2 h-2 rounded-full"
                style={{ backgroundColor: user.color }}
              />
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

