import React from 'react'
import { Button, Input, Select, SelectTrigger, SelectContent, SelectItem, SelectValue, Badge } from '@persona-framework/ui'
import { useQuery } from '@tanstack/react-query'
import { getDefaultApiClient } from '@shared/api/client'
import { X, Search, Filter, RefreshCw } from 'lucide-react'

interface LogEntry {
  timestamp: string
  level: string
  logger: string
  thread?: string
  message: string
  throwable?: string
}

interface FullScreenLogsProps {
  onClose: () => void
}

const escapeHtml = (text: string) => {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;')
}

const renderMarkdown = (text: string) => {
  const escaped = escapeHtml(text)
  return escaped
    .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.*?)\*/g, '<em>$1</em>')
    .replace(/`(.*?)`/g, '<code style="background: #2d2d2d; padding: 2px 4px; border-radius: 3px; font-family: monospace;">$1</code>')
    .replace(/\[(.*?)\]\((.*?)\)/g, '<a href="$2" style="color: #60a5fa; text-decoration: underline;" target="_blank">$1</a>')
}

export function FullScreenLogs({ onClose }: FullScreenLogsProps) {
  const [logType, setLogType] = React.useState('agent')
  const [levelFilter, setLevelFilter] = React.useState('ALL')
  const [searchQuery, setSearchQuery] = React.useState('')
  const [loggerFilter, setLoggerFilter] = React.useState('')
  const [autoScroll, setAutoScroll] = React.useState(true)
  const [expandedTraces, setExpandedTraces] = React.useState<Set<number>>(new Set())
  const scrollRef = React.useRef<HTMLDivElement>(null)

  const { data: logs = [], refetch } = useQuery<LogEntry[]>({
    queryKey: ['fullscreen-logs', logType, levelFilter, searchQuery],
    queryFn: async () => {
      const client = getDefaultApiClient()
      const params: any = { limit: 1000, logType }
      if (levelFilter !== 'ALL') params.level = levelFilter
      if (searchQuery) params.search = searchQuery
      const res = await client.get('/logs', { params })
      return res?.data || []
    },
    refetchInterval: 2000,
    retry: false,
  })

  const filteredLogs = React.useMemo(() => {
    if (!loggerFilter) return logs
    return logs.filter(log =>
      log.logger && log.logger.toLowerCase().includes(loggerFilter.toLowerCase())
    )
  }, [logs, loggerFilter])

  React.useEffect(() => {
    if (autoScroll && scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight
    }
  }, [filteredLogs, autoScroll])

  const getLevelColor = (level: string) => {
    switch (level.toUpperCase()) {
      case 'ERROR': return '#f48771'
      case 'WARN': return '#fbbf24'
      case 'INFO': return '#60a5fa'
      case 'DEBUG': return '#a78bfa'
      default: return '#cccccc'
    }
  }

  const getLevelBadge = (level: string): "danger" | "warning" | "info" | "default" => {
    switch (level.toUpperCase()) {
      case 'ERROR': return 'danger'
      case 'WARN': return 'warning'
      case 'INFO': return 'info'
      default: return 'default'
    }
  }

  return (
    <div className="flex flex-col h-full bg-[#1e1e1e] text-[#cccccc]">
      <div className="flex items-center justify-between px-4 py-3 border-b border-[#3c3c3c] text-sm font-semibold">
        <span>Live Logs Viewer</span>
        <Button variant="ghost" size="sm" onClick={onClose}>
          <X className="w-4 h-4" />
        </Button>
      </div>
      <div className="flex flex-col gap-2 p-3 border-b border-[#3c3c3c]">
        <div className="flex gap-2 items-center flex-wrap">
          <Select value={logType} onValueChange={setLogType}>
            <SelectTrigger className="w-[140px]">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="application">System Logs</SelectItem>
              <SelectItem value="agent">Agent Logs</SelectItem>
            </SelectContent>
          </Select>
          <Select value={levelFilter} onValueChange={setLevelFilter}>
            <SelectTrigger className="w-[110px]">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="ALL">All Levels</SelectItem>
              <SelectItem value="ERROR">ERROR</SelectItem>
              <SelectItem value="WARN">WARN</SelectItem>
              <SelectItem value="INFO">INFO</SelectItem>
              <SelectItem value="DEBUG">DEBUG</SelectItem>
            </SelectContent>
          </Select>
          <Input
            size="sm"
            placeholder="Search message..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-[200px]"
          />
          <Input
            size="sm"
            placeholder="Filter logger..."
            value={loggerFilter}
            onChange={(e) => setLoggerFilter(e.target.value)}
            className="w-[150px]"
          />
          <Button
            variant={autoScroll ? 'default' : 'outline'}
            size="sm"
            onClick={() => setAutoScroll(!autoScroll)}
          >
            Auto-scroll
          </Button>
          <Button
            size="sm"
            variant="ghost"
            onClick={() => refetch()}
          >
            <RefreshCw className="w-4 h-4" />
          </Button>
        </div>
        <div className="text-[11px] text-[#858585]">
          {filteredLogs.length} entries • Refresh: 2s
        </div>
      </div>
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-3 font-mono text-xs">
        {filteredLogs.length === 0 ? (
          <div className="text-center text-[#858585] p-8">
            No logs found
          </div>
        ) : (
          filteredLogs.map((log, idx) => {
            const isExpanded = expandedTraces.has(idx)
            const toggleExpanded = () => {
              const newSet = new Set(expandedTraces)
              if (isExpanded) {
                newSet.delete(idx)
              } else {
                newSet.add(idx)
              }
              setExpandedTraces(newSet)
            }

            let timestamp = null
            try {
              if (log.timestamp) {
                const trimmed = log.timestamp.trim()
                timestamp = new Date(trimmed).toLocaleTimeString('en-US', {
                  hour12: false,
                  hour: '2-digit',
                  minute: '2-digit',
                  second: '2-digit'
                })
              }
            } catch (e) {
              timestamp = log.timestamp?.trim()
            }

            const loggerShortName = log.logger && log.logger !== 'unknown'
              ? log.logger.split('.').slice(-2).join('.')
              : 'system'

            return (
              <div
                key={idx}
                className="px-2.5 py-1.5 rounded mb-1 whitespace-pre-wrap break-words"
                style={{
                  backgroundColor: log.level === 'ERROR' ? '#2d1e1e' : log.level === 'WARN' ? '#2d2a1e' : 'transparent',
                  borderLeft: `3px solid ${getLevelColor(log.level)}`
                }}
              >
                <div className="flex gap-2.5 items-center mb-1">
                  {timestamp && (
                    <span className="text-[#858585] text-[11px] min-w-[80px] font-mono">
                      {timestamp}
                    </span>
                  )}
                  <Badge variant={getLevelBadge(log.level)} className="text-[10px]">
                    {log.level}
                  </Badge>
                  <span className="text-[#858585] text-[11px]">
                    {loggerShortName}
                  </span>
                  {log.thread && (
                    <span className="text-[#666] text-[10px]">
                      [{log.thread}]
                    </span>
                  )}
                </div>
                <div
                  className="ml-2.5"
                  style={{ color: getLevelColor(log.level) }}
                  dangerouslySetInnerHTML={{ __html: renderMarkdown(log.message) }}
                />
                {log.throwable && (
                  <div className="mt-1.5 ml-2.5">
                    <div
                      onClick={toggleExpanded}
                      className="text-[#f48771] text-[11px] cursor-pointer select-none inline-flex items-center gap-1"
                    >
                      <span>{isExpanded ? '▼' : '▶'}</span>
                      <span>Stack Trace ({log.throwable.split('\n').length} lines)</span>
                    </div>
                    {isExpanded && (
                      <div className="text-[#f48771] text-[10px] mt-1 pl-2.5 border-l-2 border-[#f48771] font-mono whitespace-pre-wrap">
                        {log.throwable}
                      </div>
                    )}
                  </div>
                )}
              </div>
            )
          })
        )}
      </div>
    </div>
  )
}

