import React from 'react'

export interface KbdProps {
  children: React.ReactNode
  className?: string
}

export const Kbd: React.FC<KbdProps> = ({ children, className = '' }) => {
  return (
    <kbd
      className={`inline-flex items-center justify-center min-w-[1.5rem] h-5 px-1.5 text-[10px] font-mono font-medium rounded bg-[var(--bg-tertiary)] text-[var(--text-secondary)] border border-[var(--border-primary)] ${className}`}
    >
      {children}
    </kbd>
  )
}

export interface KeyboardShortcutProps {
  keys: string[]
  className?: string
}

export const KeyboardShortcut: React.FC<KeyboardShortcutProps> = ({ keys, className = '' }) => {
  return (
    <span className={`inline-flex items-center gap-0.5 ${className}`}>
      {keys.map((key, index) => (
        <React.Fragment key={index}>
          <Kbd>{key}</Kbd>
          {index < keys.length - 1 && <span className="text-[var(--text-muted)] text-xs">+</span>}
        </React.Fragment>
      ))}
    </span>
  )
}

