import React, { useState, useEffect, useRef } from 'react'
import { Input, Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, Button } from '@persona-framework/ui'

interface GoToLineDialogProps {
  open: boolean
  onClose: () => void
  onGoToLine: (lineNumber: number) => void
  maxLine?: number
}

export function GoToLineDialog({ open, onClose, onGoToLine, maxLine }: GoToLineDialogProps) {
  const [lineNumber, setLineNumber] = useState('')
  const [error, setError] = useState('')
  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    if (open && inputRef.current) {
      setTimeout(() => {
        inputRef.current?.focus()
        inputRef.current?.select()
      }, 100)
      setLineNumber('')
      setError('')
    }
  }, [open])

  const handleSubmit = () => {
    const num = parseInt(lineNumber)

    if (isNaN(num) || num < 1) {
      setError('Please enter a valid line number (1 or greater)')
      return
    }

    if (maxLine && num > maxLine) {
      setError(`Line number must be between 1 and ${maxLine}`)
      return
    }

    onGoToLine(num)
    onClose()
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault()
      handleSubmit()
    } else if (e.key === 'Escape') {
      e.preventDefault()
      onClose()
    }
  }

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-[400px] w-[90vw] p-5 bg-[#252526] border border-[#3c3c3c]">
        <DialogHeader>
          <DialogTitle className="text-sm font-semibold text-[#cccccc]">Go to Line</DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          <Input
            ref={inputRef}
            value={lineNumber}
            onChange={(e) => {
              setLineNumber(e.target.value)
              setError('')
            }}
            onKeyDown={handleKeyDown}
            placeholder={maxLine ? `Enter line number (1-${maxLine})` : 'Enter line number'}
            type="number"
            className="w-full bg-[#3c3c3c] border-none text-[#cccccc] placeholder:text-[#858585]"
          />

          {error && <div className="text-[#f48771] text-xs -mt-3">{error}</div>}
        </div>

        <DialogFooter className="flex justify-end gap-2">
          <Button variant="outline" onClick={onClose}>
            Cancel
          </Button>
          <Button onClick={handleSubmit}>
            Go
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

