import { createContext, useCallback, useContext, useEffect, useMemo, useState, ReactNode } from 'react'
import { ThemeProvider as UIThemeProvider } from '@persona-framework/ui'

type ThemeMode = 'light' | 'dark' | 'system'

interface ThemeContextValue {
  mode: ThemeMode
  resolvedMode: 'dark' | 'light'
  toggleTheme: () => void
  setTheme: (mode: ThemeMode) => void
}

const ThemeContext = createContext<ThemeContextValue | undefined>(undefined)
const STORAGE_KEY = 'wraith-theme'
const getSystemPref = () => window.matchMedia?.('(prefers-color-scheme: light)').matches ? 'light' : 'dark'

export function ThemeProvider({ children }: { children: ReactNode }) {
  const [mode, setMode] = useState<ThemeMode>(() => {
    const s = localStorage.getItem(STORAGE_KEY)
    return (s === 'dark' || s === 'light' || s === 'system') ? s : 'dark'
  })

  const resolvedMode = useMemo(() => mode === 'system' ? getSystemPref() : mode, [mode])
  const setTheme = useCallback((m: ThemeMode) => { setMode(m); localStorage.setItem(STORAGE_KEY, m) }, [])
  const toggleTheme = useCallback(() => setTheme(resolvedMode === 'light' ? 'dark' : 'light'), [resolvedMode, setTheme])

  useEffect(() => { document.documentElement.setAttribute('data-persona-theme', resolvedMode) }, [resolvedMode])

  return (
    <ThemeContext.Provider value={{ mode, resolvedMode, toggleTheme, setTheme }}>
      <UIThemeProvider defaultTheme={resolvedMode} storageKey={STORAGE_KEY}>
        {children}
      </UIThemeProvider>
    </ThemeContext.Provider>
  )
}

export const useTheme = () => {
  const ctx = useContext(ThemeContext)
  if (!ctx) throw new Error('useTheme must be used within ThemeProvider')
  return ctx
}

import React, { useEffect, useRef, useState } from 'react'
import {
  Button,
  Tabs,
  TabsList,
  TabsTrigger,
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@persona-framework/ui'
import {
  Plus,
  X,
  ChevronDown,
  SplitSquareVertical,
  SplitSquareHorizontal,
} from 'lucide-react'
import { Terminal } from '@xterm/xterm'
import { FitAddon } from '@xterm/addon-fit'
import { Client, type StompSubscription } from '@stomp/stompjs'
import '@xterm/xterm/css/xterm.css'

interface TerminalOutput {
  sessionId: string
  type: 'STDOUT' | 'STDERR' | 'EXIT' | 'ERROR'
  content: string
  exitCode?: number | null
  timestamp: string
}

type TerminalProfile = 'bash' | 'zsh' | 'powershell' | 'sh' | 'fish'
type SplitMode = 'none' | 'vertical' | 'horizontal'

interface TerminalInstance {
  id: string
  profile: TerminalProfile
  sessionId: string
  workingDirectory: string
  terminal: Terminal | null
  fitAddon: FitAddon | null
  stompClient: Client | null
  subscription: StompSubscription | null
  connectionStatus: 'disconnected' | 'connecting' | 'connected'
}

export function TerminalPanel() {
  const [terminals, setTerminals] = useState<TerminalInstance[]>([])
  const [activeTerminalId, setActiveTerminalId] = useState<string | null>(null)
  const [splitMode, setSplitMode] = useState<SplitMode>('none')
  const terminalRefs = useRef<Map<string, HTMLDivElement>>(new Map())

  useEffect(() => {
    if (terminals.length === 0) {
      createTerminal('bash')
    }
  }, [])

  const createTerminal = (profile: TerminalProfile) => {
    const id = `terminal-${Date.now()}`
    const sessionId = `session-${id}`

    const newTerminal: TerminalInstance = {
      id,
      profile,
      sessionId,
      workingDirectory: '/home/user/persona-framework',
      terminal: null,
      fitAddon: null,
      stompClient: null,
      subscription: null,
      connectionStatus: 'disconnected',
    }

    setTerminals((prev) => [...prev, newTerminal])
    setActiveTerminalId(id)

    setTimeout(() => initializeTerminal(id), 100)
  }

  const initializeTerminal = (terminalId: string) => {
    const terminalDiv = terminalRefs.current.get(terminalId)
    if (!terminalDiv) {
      console.error(`Terminal div not found for ${terminalId}`)
      return
    }

    const terminalInstance = terminals.find((t) => t.id === terminalId)
    if (!terminalInstance) {
      console.error(`Terminal instance not found for ${terminalId}`)
      return
    }

    const terminal = new Terminal({
      cursorBlink: true,
      fontSize: 14,
      fontFamily: "Consolas, 'Courier New', monospace",
      theme: {
        background: '#1e1e1e',
        foreground: '#d4d4d4',
        cursor: '#d4d4d4',
        black: '#000000',
        red: '#cd3131',
        green: '#0dbc79',
        yellow: '#e5e510',
        blue: '#2472c8',
        magenta: '#bc3fbc',
        cyan: '#11a8cd',
        white: '#e5e5e5',
        brightBlack: '#666666',
        brightRed: '#f14c4c',
        brightGreen: '#23d18b',
        brightYellow: '#f5f543',
        brightBlue: '#3b8eea',
        brightMagenta: '#d670d6',
        brightCyan: '#29b8db',
        brightWhite: '#e5e5e5',
      },
      rows: 30,
      cols: 80,
    })

    const fitAddon = new FitAddon()
    terminal.loadAddon(fitAddon)

    terminal.open(terminalDiv)
    fitAddon.fit()

    terminal.writeln('╔═══════════════════════════════════════════════════════════╗')
    terminal.writeln('║          Persona Framework - Terminal Panel              ║')
    terminal.writeln('╚═══════════════════════════════════════════════════════════╝')
    terminal.writeln('')
    terminal.writeln(`Profile: ${terminalInstance.profile}`)
    terminal.writeln(`Working directory: ${terminalInstance.workingDirectory}`)
    terminal.writeln('')
    terminal.writeln('Connecting to server...')
    terminal.writeln('')

    let currentCommand = ''

    terminal.onData((data) => {
      const code = data.charCodeAt(0)

      if (code === 13) {
        terminal.writeln('')

        if (currentCommand.trim()) {
          executeCommand(terminalId, currentCommand.trim())
        }

        currentCommand = ''
        terminal.write('$ ')
      }
      else if (code === 127) {
        if (currentCommand.length > 0) {
          currentCommand = currentCommand.slice(0, -1)
          terminal.write('\b \b')
        }
      }
      else if (code === 3) {
        terminal.writeln('^C')
        currentCommand = ''
        terminal.write('$ ')
      }
      else {
        currentCommand += data
        terminal.write(data)
      }
    })

    setTerminals((prev) =>
      prev.map((t) =>
        t.id === terminalId
          ? { ...t, terminal, fitAddon, connectionStatus: 'connecting' }
          : t
      )
    )

    initializeWebSocket(terminalId, terminal, terminalInstance.sessionId)
  }

  const initializeWebSocket = (
    terminalId: string,
    terminal: Terminal,
    sessionId: string
  ) => {
    const wsUrl = `ws://localhost:8989/ws/terminal`

    const client = new Client({
      brokerURL: wsUrl,
      reconnectDelay: 5000,
      heartbeatIncoming: 4000,
      heartbeatOutgoing: 4000,

      onConnect: () => {
        console.log(`[Terminal ${terminalId}] Connected to WebSocket`)
        updateTerminalStatus(terminalId, 'connected')

        terminal.writeln('\x1B[32m✓ Connected to server\x1B[0m')
        terminal.writeln('')
        terminal.write('$ ')

        const subscription = client.subscribe(
          `/topic/terminal/${sessionId}`,
          (message) => {
            const output: TerminalOutput = JSON.parse(message.body)
            switch (output.type) {
              case 'STDOUT':
                terminal.writeln(output.content)
                break
              case 'STDERR':
                terminal.writeln(`\x1B[31m${output.content}\x1B[0m`)
                break
              case 'EXIT':
                if (output.exitCode === 0) {
                  terminal.writeln(`\x1B[32m${output.content}\x1B[0m`)
                } else {
                  terminal.writeln(`\x1B[31m${output.content}\x1B[0m`)
                }
                terminal.writeln('')
                terminal.write('$ ')
                break
              case 'ERROR':
                terminal.writeln(`\x1B[31m✗ Error: ${output.content}\x1B[0m`)
                terminal.writeln('')
                terminal.write('$ ')
                break
            }
          }
        )

        setTerminals((prev) =>
          prev.map((t) => (t.id === terminalId ? { ...t, subscription } : t))
        )
      },

      onStompError: (frame) => {
        console.error(`[Terminal ${terminalId}] STOMP Error:`, frame.headers.message)
        updateTerminalStatus(terminalId, 'disconnected')

        terminal.writeln(`\x1B[31m✗ STOMP Error: ${frame.headers.message}\x1B[0m`)
      },

      onWebSocketError: (event) => {
        console.error(`[Terminal ${terminalId}] WebSocket Error:`, event)
        updateTerminalStatus(terminalId, 'disconnected')
      },

      onWebSocketClose: () => {
        console.log(`[Terminal ${terminalId}] WebSocket closed`)
        updateTerminalStatus(terminalId, 'disconnected')

        terminal.writeln('')
        terminal.writeln('\x1B[33m✗ Disconnected from server\x1B[0m')
        terminal.writeln('Reconnecting...')
      },

      onDisconnect: () => {
        console.log(`[Terminal ${terminalId}] Disconnected from STOMP`)
        updateTerminalStatus(terminalId, 'disconnected')
      },
    })

    client.activate()

    setTerminals((prev) =>
      prev.map((t) => (t.id === terminalId ? { ...t, stompClient: client } : t))
    )
  }

  const updateTerminalStatus = (
    terminalId: string,
    status: 'disconnected' | 'connecting' | 'connected'
  ) => {
    setTerminals((prev) =>
      prev.map((t) => (t.id === terminalId ? { ...t, connectionStatus: status } : t))
    )
  }

  const executeCommand = (terminalId: string, command: string) => {
    const terminalInstance = terminals.find((t) => t.id === terminalId)
    if (!terminalInstance) return

    const client = terminalInstance.stompClient
    if (!client || !client.connected) {
      if (terminalInstance.terminal) {
        terminalInstance.terminal.writeln('\x1B[31m✗ Not connected to server\x1B[0m')
        terminalInstance.terminal.writeln('')
        terminalInstance.terminal.write('$ ')
      }
      return
    }

    const payload = {
      sessionId: terminalInstance.sessionId,
      command,
      workingDirectory: terminalInstance.workingDirectory,
      environment: {
        SHELL: getShellPath(terminalInstance.profile),
      },
    }

    client.publish({
      destination: '/app/terminal/execute',
      body: JSON.stringify(payload),
    })
  }

  const getShellPath = (profile: TerminalProfile): string => {
    switch (profile) {
      case 'bash':
        return '/bin/bash'
      case 'zsh':
        return '/bin/zsh'
      case 'sh':
        return '/bin/sh'
      case 'fish':
        return '/usr/bin/fish'
      case 'powershell':
        return '/usr/bin/pwsh'
      default:
        return '/bin/bash'
    }
  }

  const closeTerminal = (terminalId: string) => {
    const terminalInstance = terminals.find((t) => t.id === terminalId)
    if (!terminalInstance) return

    if (terminalInstance.subscription) {
      terminalInstance.subscription.unsubscribe()
    }
    if (terminalInstance.stompClient) {
      terminalInstance.stompClient.deactivate()
    }
    if (terminalInstance.terminal) {
      terminalInstance.terminal.dispose()
    }

    const newTerminals = terminals.filter((t) => t.id !== terminalId)
    setTerminals(newTerminals)

    if (activeTerminalId === terminalId) {
      setActiveTerminalId(newTerminals.length > 0 ? newTerminals[0].id : null)
    }

    if (newTerminals.length === 0) {
      createTerminal('bash')
    }
  }

  const getStatusText = (status: string) => {
    switch (status) {
      case 'connected':
        return 'Connected'
      case 'connecting':
        return 'Connecting...'
      case 'disconnected':
        return 'Disconnected'
    }
  }

  const getStatusDotClass = (status: string) => {
    switch (status) {
      case 'connected':
        return 'bg-[#4ec9b0]'
      case 'connecting':
        return 'bg-[#dcdcaa]'
      case 'disconnected':
        return 'bg-[#f48771]'
    }
  }

  const toggleSplitVertical = () => {
    setSplitMode(splitMode === 'vertical' ? 'none' : 'vertical')
  }

  const toggleSplitHorizontal = () => {
    setSplitMode(splitMode === 'horizontal' ? 'none' : 'horizontal')
  }

  const renderTerminal = (terminalId: string) => {
    const terminalInstance = terminals.find((t) => t.id === terminalId)
    if (!terminalInstance) return null

    return (
      <div key={terminalId} className="flex-1 flex flex-col min-w-0 min-h-0 relative">
        <div className="flex justify-between items-center px-3 py-1 bg-[#252526] border-b border-[#3c3c3c] text-[11px] text-[#858585]">
          <div className="flex items-center gap-2">
            <div className={`w-2 h-2 rounded-full ${getStatusDotClass(terminalInstance.connectionStatus)}`} />
            <span>{getStatusText(terminalInstance.connectionStatus)}</span>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-[10px] px-1.5 py-0.5 rounded bg-[#4fc3f722] text-[#4fc3f7] font-semibold uppercase">
              {terminalInstance.profile}
            </span>
            <span>{terminalInstance.sessionId}</span>
          </div>
        </div>

        <div
          className="flex-1 p-2 bg-[#1e1e1e] overflow-hidden"
          ref={(el) => {
            if (el) {
              terminalRefs.current.set(terminalId, el)
            }
          }}
        />
      </div>
    )
  }

  const renderTerminals = () => {
    const activeTerminal = terminals.find((t) => t.id === activeTerminalId)
    if (!activeTerminal) return null

    if (splitMode === 'none') {
      return renderTerminal(activeTerminal.id)
    }

    const splitTerminals = terminals.slice(0, 2)

    return (
      <div className={`flex flex-1 min-h-0 overflow-hidden ${splitMode === 'vertical' ? 'flex-row' : 'flex-col'}`}>
        {splitTerminals.map((term, index) => (
          <React.Fragment key={term.id}>
            {renderTerminal(term.id)}
            {index === 0 && splitTerminals.length > 1 && (
              <div
                className={`bg-[#3c3c3c] hover:bg-[#007acc] ${
                  splitMode === 'horizontal' ? 'w-full h-1 cursor-ns-resize' : 'w-1 h-full cursor-ew-resize'
                }`}
              />
            )}
          </React.Fragment>
        ))}
      </div>
    )
  }

  return (
    <div className="flex flex-col h-full w-full bg-neutral-50 overflow-hidden">
      <div className="flex items-center justify-between px-2 py-1 bg-[#2b2b2b] border-b border-[#3c3c3c] gap-2">
        <div className="flex items-center gap-2 flex-1 min-w-0">
          <Tabs value={activeTerminalId || undefined} onValueChange={setActiveTerminalId}>
            <TabsList className="h-8">
              {terminals.map((term) => (
                <TabsTrigger key={term.id} value={term.id} className="text-xs">
                  {term.profile}
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={(e) => {
                      e.stopPropagation()
                      closeTerminal(term.id)
                    }}
                    className="ml-1 h-4 w-4 p-0"
                  >
                    <X className="w-3 h-3" />
                  </Button>
                </TabsTrigger>
              ))}
            </TabsList>
          </Tabs>
        </div>

        <div className="flex items-center gap-1">
          <Button
            variant="ghost"
            size="sm"
            onClick={toggleSplitVertical}
            title="Split Vertically"
          >
            <SplitSquareVertical className="w-4 h-4" />
          </Button>
          <Button
            variant="ghost"
            size="sm"
            onClick={toggleSplitHorizontal}
            title="Split Horizontally"
          >
            <SplitSquareHorizontal className="w-4 h-4" />
          </Button>

          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button size="sm" className="gap-1">
                <Plus className="w-4 h-4" />
                New Terminal
                <ChevronDown className="w-3 h-3 ml-1" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent>
              <DropdownMenuItem onClick={() => createTerminal('bash')}>Bash</DropdownMenuItem>
              <DropdownMenuItem onClick={() => createTerminal('zsh')}>Zsh</DropdownMenuItem>
              <DropdownMenuItem onClick={() => createTerminal('sh')}>Sh</DropdownMenuItem>
              <DropdownMenuItem onClick={() => createTerminal('fish')}>Fish</DropdownMenuItem>
              <DropdownMenuItem onClick={() => createTerminal('powershell')}>PowerShell</DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>

      {renderTerminals()}
    </div>
  )
}

import { Button, Card, Label, Textarea } from "@persona-framework/ui"
import { Plus, Trash2 } from "lucide-react"
import type { FewShotExample } from "../../types"

interface FewShotExampleBuilderProps {
  examples: FewShotExample[]
  onChange: (examples: FewShotExample[]) => void
}

export function FewShotExampleBuilder({ examples, onChange }: FewShotExampleBuilderProps) {
  const addExample = () => {
    onChange([...examples, { id: crypto.randomUUID(), input: "", output: "" }])
  }

  const removeExample = (id: string) => {
    onChange(examples.filter(ex => ex.id !== id))
  }

  const updateExample = (id: string, field: "input" | "output", value: string) => {
    onChange(examples.map(ex => ex.id === id ? { ...ex, [field]: value } : ex))
  }

  return (
    <div className="flex flex-col gap-3">
      <div className="flex items-center justify-between gap-2">
        <Label className="font-semibold">Few-Shot Examples</Label>
        <Button onClick={addExample} size="sm">
          <Plus className="mr-2 h-4 w-4" />
          Add Example
        </Button>
      </div>

      <div className="flex flex-col gap-2 max-h-[400px] overflow-auto">
        {examples.map((example, index) => (
          <Card className="p-3" key={example.id}>
            <div className="flex items-center justify-between gap-2 mb-2">
              <Label className="font-semibold">
                Example
                {" "}
                {index + 1}
              </Label>
              <Button
                onClick={() => removeExample(example.id)}
                size="sm"
                variant="ghost"
              >
                <Trash2 className="h-4 w-4" />
              </Button>
            </div>
            <div className="mb-2">
              <Label className="text-sm">Input</Label>
              <Textarea
                onChange={(e) => updateExample(example.id, "input", e.target.value)}
                placeholder="Example input..."
                rows={2}
                value={example.input}
                className="resize-y"
              />
            </div>
            <div>
              <Label className="text-sm">Expected Output</Label>
              <Textarea
                onChange={(e) => updateExample(example.id, "output", e.target.value)}
                placeholder="Example output..."
                rows={2}
                value={example.output}
                className="resize-y"
              />
            </div>
          </Card>
        ))}
        {examples.length === 0 && (
          <div className="text-muted-foreground p-4 text-center">
            No examples defined. Click "Add Example" to create one.
          </div>
        )}
      </div>
    </div>
  )
}

import { useEffect, useState } from "react"
import { Card, Label } from "@persona-framework/ui"
import { AlertTriangle } from "lucide-react"

interface PromptMetricsProps {
  content: string
}

export function PromptMetrics({ content }: PromptMetricsProps) {
  const [metrics, setMetrics] = useState({
    length: 0,
    readabilityScore: 0,
    tokenCount: 0,
    warnings: [] as string[],
  })

  useEffect(() => {
    const warnings: string[] = []
    const length = content.length
    const tokenCount = Math.ceil(length / 4)

    if (length > 4000) {
      warnings.push("Prompt is very long and may exceed model context limits")
    }
    if (length < 50) {
      warnings.push("Prompt may be too vague or short")
    }
    if (!content.includes("?") && !content.includes(".")) {
      warnings.push("Consider adding clear instructions or questions")
    }
    if (content.toLowerCase().includes("do not") || content.toLowerCase().includes("don't")) {
      warnings.push("Consider using positive framing instead of negations")
    }

    const readabilityScore = Math.min(100, Math.max(0, 100 - (length / 50)))

    setMetrics({
      length,
      readabilityScore,
      tokenCount,
      warnings,
    })
  }, [content])

  return (
    <div className="flex flex-col gap-3">
      <Label className="font-semibold">Prompt Metrics</Label>

      <Card className="p-3">
        <div className="grid grid-cols-2 gap-3">
          <div className="flex flex-col gap-1">
            <span className="text-xs text-muted-foreground">Length</span>
            <div className="text-base font-semibold">
              {metrics.length}
              {" "}
              chars
            </div>
          </div>
          <div className="flex flex-col gap-1">
            <span className="text-xs text-muted-foreground">Est. Tokens</span>
            <div className="text-base font-semibold">{metrics.tokenCount}</div>
          </div>
          <div className="flex flex-col gap-1">
            <span className="text-xs text-muted-foreground">Readability</span>
            <div className="text-base font-semibold">
              {metrics.readabilityScore.toFixed(0)}
              %
            </div>
          </div>
        </div>
      </Card>

      {metrics.warnings.length > 0 && (
        <>
          <Label className="font-semibold">Optimization Suggestions</Label>
          <div className="flex flex-col gap-2">
            {metrics.warnings.map((warning, index) => (
              <div className="flex items-start gap-2" key={index}>
                <AlertTriangle className="h-4 w-4 text-yellow-500 mt-0.5 flex-shrink-0" />
                <span className="text-sm text-muted-foreground">{warning}</span>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  )
}

import { useState, useEffect } from "react"
import { Button, Tabs, TabsList, TabsTrigger, TabsContent } from "@persona-framework/ui"
import { Save, Check } from "lucide-react"
import type { FewShotExample, PromptConfig, PromptVariable, PromptVersion } from "../../types"
import { FewShotExampleBuilder } from "./FewShotExampleBuilder"
import { ModelConfigPanel } from "./ModelConfigPanel"
import { PromptEditor } from "./PromptEditor"
import { PromptMetrics } from "./PromptMetrics"
import { PromptTestPanel } from "./PromptTestPanel"
import { PromptVersionHistory } from "./PromptVersionHistory"
import { VariablesEditor } from "./VariablesEditor"

const STORAGE_KEY = 'wraith_prompt_designer_versions'

function loadVersionsFromStorage(): PromptVersion[] {
  try {
    const stored = localStorage.getItem(STORAGE_KEY)
    if (stored) {
      const parsed = JSON.parse(stored)
      // Validate structure
      if (Array.isArray(parsed)) {
        return parsed
      }
    }
  } catch {
    // Invalid storage data
  }
  return []
}

function saveVersionsToStorage(versions: PromptVersion[]) {
  try {
    // Only keep last 50 versions to prevent localStorage bloat
    const toSave = versions.slice(0, 50)
    localStorage.setItem(STORAGE_KEY, JSON.stringify(toSave))
  } catch {
    // Storage full or unavailable
  }
}

export function PromptDesigner() {
  const [promptContent, setPromptContent] = useState("")
  const [variables, setVariables] = useState<PromptVariable[]>([])
  const [examples, setExamples] = useState<FewShotExample[]>([])
  const [config, setConfig] = useState<PromptConfig>({
    maxTokens: 2000,
    stopSequences: [],
    temperature: 0.7,
    topP: 1.0,
  })
  const [versions, setVersions] = useState<PromptVersion[]>(() => loadVersionsFromStorage())
  const [rightPanelTab, setRightPanelTab] = useState<"variables" | "config" | "examples" | "history">("variables")
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saved'>('idle')

  // Persist versions to localStorage whenever they change
  useEffect(() => {
    saveVersionsToStorage(versions)
  }, [versions])

  const saveVersion = () => {
    const newVersion: PromptVersion = {
      config,
      content: promptContent,
      examples,
      id: crypto.randomUUID(),
      timestamp: Date.now(),
      variables,
    }
    setVersions([newVersion, ...versions])
    setSaveStatus('saved')
    setTimeout(() => setSaveStatus('idle'), 2000)
  }

  const restoreVersion = (version: PromptVersion) => {
    setPromptContent(version.content)
    setVariables(version.variables)
    setExamples(version.examples)
    setConfig(version.config)
  }

  const variablesMap = variables.reduce<Record<string, string>>((acc, v) => {
    acc[v.name] = v.value
    return acc
  }, {})

  return (
    <div className="flex flex-col gap-4 h-full">
      <div className="flex items-center justify-between gap-3">
        <h2 className="text-2xl font-semibold m-0">Prompt Designer</h2>
        <Button onClick={saveVersion}>
          {saveStatus === 'saved' ? (
            <>
              <Check className="mr-2 h-4 w-4 text-green-400" />
              Saved!
            </>
          ) : (
            <>
              <Save className="mr-2 h-4 w-4" />
              Save Version
            </>
          )}
        </Button>
      </div>

      <div className="grid grid-cols-3 gap-4 flex-1 min-h-0">
        <div className="bg-secondary rounded-lg h-full overflow-hidden">
          <div className="flex flex-col gap-3 min-h-0 overflow-auto p-4">
            <h3 className="text-lg font-semibold m-0">Prompt Editor</h3>
            <PromptEditor onChange={setPromptContent} value={promptContent} />
          </div>
        </div>

        <div className="bg-secondary rounded-lg h-full overflow-hidden">
          <div className="flex flex-col gap-3 min-h-0 overflow-auto p-4">
            <h3 className="text-lg font-semibold m-0">Live Test</h3>
            <PromptTestPanel promptContent={promptContent} variables={variablesMap} />
          </div>
        </div>

        <div className="bg-secondary rounded-lg h-full overflow-hidden">
          <div className="flex flex-col gap-3 min-h-0 overflow-auto p-4">
            <Tabs value={rightPanelTab} onValueChange={(value) => setRightPanelTab(value as any)}>
              <TabsList className="grid w-full grid-cols-4">
                <TabsTrigger value="variables">Variables</TabsTrigger>
                <TabsTrigger value="config">Config</TabsTrigger>
                <TabsTrigger value="examples">Examples</TabsTrigger>
                <TabsTrigger value="history">History</TabsTrigger>
              </TabsList>

              <TabsContent value="variables" className="mt-4 space-y-4">
                <VariablesEditor onChange={setVariables} variables={variables} />
                <PromptMetrics content={promptContent} />
              </TabsContent>

              <TabsContent value="config" className="mt-4">
                <ModelConfigPanel config={config} onChange={setConfig} />
              </TabsContent>

              <TabsContent value="examples" className="mt-4">
                <FewShotExampleBuilder examples={examples} onChange={setExamples} />
              </TabsContent>

              <TabsContent value="history" className="mt-4">
                <PromptVersionHistory onRestore={restoreVersion} versions={versions} />
              </TabsContent>
            </Tabs>
          </div>
        </div>
      </div>
    </div>
  )
}

import { useState } from "react"
import {
  Button,
  Card,
  Label,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Spinner,
  Textarea,
} from "@persona-framework/ui"
import { Play } from "lucide-react"
import { makeHttpClient } from '../../../../data/https'

const http = makeHttpClient('/api')

interface PromptTestPanelProps {
  promptContent: string
  variables: Record<string, string>
}

export function PromptTestPanel({ promptContent, variables }: PromptTestPanelProps) {
  const [selectedModel, setSelectedModel] = useState("claude-3-sonnet")
  const [testInput, setTestInput] = useState("")
  const [output, setOutput] = useState("")
  const [isRunning, setIsRunning] = useState(false)
  const [metadata, setMetadata] = useState<{
    duration: number
    tokensUsed: number
  } | null>(null)

  const runTest = async () => {
    setIsRunning(true)
    setOutput("")
    setMetadata(null)

    const startTime = Date.now()

    let processedPrompt = promptContent
    Object.entries(variables).forEach(([key, value]) => {
      processedPrompt = processedPrompt.replace(new RegExp(`{{${key}}}`, "g"), value)
    })

    try {
      const response = await http.post('/public/chat/PAIMON', {
        messages: [
          { role: 'system', content: processedPrompt },
          { role: 'user', content: testInput || 'Hello' }
        ]
      })

      const duration = Date.now() - startTime
      const completion = response.data

      setOutput(completion.message || completion.content || JSON.stringify(completion, null, 2))
      setMetadata({
        tokensUsed: completion.tokensUsed || completion.usage?.totalTokens || 0,
        duration
      })
    } catch (error: any) {
      const duration = Date.now() - startTime
      setOutput(`Error: ${error?.response?.data?.message || error?.message || 'Failed to execute prompt'}`)
      setMetadata({ tokensUsed: 0, duration })
    } finally {
      setIsRunning(false)
    }
  }

  return (
    <div className="flex flex-col gap-3 h-full">
      <Label className="font-semibold">Test Prompt</Label>

      <div className="flex items-end flex-wrap gap-2">
        <div className="flex-1 min-w-[200px]">
          <Label className="text-sm">Model</Label>
          <Select value={selectedModel} onValueChange={setSelectedModel}>
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="qwen2.5-coder:7b-instruct-q4_0">Qwen 2.5 Coder 7B</SelectItem>
              <SelectItem value="llama3.1:8b">Llama 3.1 8B</SelectItem>
              <SelectItem value="llama3.2:1b">Llama 3.2 1B</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <Button
          disabled={isRunning || !promptContent}
          onClick={runTest}
        >
          <Play className="mr-2 h-4 w-4" />
          Run Test
        </Button>
      </div>

      <div>
        <Label className="text-sm">Test Input</Label>
        <Textarea
          onChange={(e) => setTestInput(e.target.value)}
          placeholder="Enter test input..."
          rows={3}
          value={testInput}
          className="resize-y"
        />
      </div>

      <div className="flex-1 min-h-[200px]">
        <Label className="text-sm">Output</Label>
        <Card className="flex-1 overflow-auto p-3">
          {isRunning && (
            <div className="flex items-center gap-2">
              <Spinner size="sm" />
              <span className="text-muted-foreground">Running test...</span>
            </div>
          )}
          {!isRunning && !output && (
            <div className="text-muted-foreground">
              Configure your prompt and click "Run Test" to see results.
            </div>
          )}
          {!isRunning && output && (
            <>
              <div className="whitespace-pre-wrap">
                {output}
              </div>
              {metadata && (
                <div className="flex flex-wrap gap-4 text-sm text-muted-foreground mt-2">
                  <span>
                    Tokens:
                    {" "}
                    <strong>{metadata.tokensUsed}</strong>
                  </span>
                  <span>
                    Duration:
                    {" "}
                    <strong>
                      {metadata.duration}
                      ms
                    </strong>
                  </span>
                </div>
              )}
            </>
          )}
        </Card>
      </div>
    </div>
  )
}

