import { Input, Label, Slider, Textarea } from "@persona-framework/ui"
import type { PromptConfig } from "../../types"

interface ModelConfigPanelProps {
  config: PromptConfig
  onChange: (config: PromptConfig) => void
}

export function ModelConfigPanel({ config, onChange }: ModelConfigPanelProps) {
  return (
    <div className="flex flex-col gap-4">
      <div className="flex flex-col gap-2">
        <div className="flex flex-col gap-1">
          <Label className="font-semibold">
            Temperature
            {" "}
            <span className="text-muted-foreground font-semibold">{config.temperature.toFixed(2)}</span>
          </Label>
          <Slider
            max={2}
            min={0}
            onValueChange={([value]) => onChange({ ...config, temperature: value })}
            step={0.1}
            value={[config.temperature]}
          />
        </div>
      </div>

      <div className="flex flex-col gap-2">
        <Label className="font-semibold">Max Tokens</Label>
        <Input
          onChange={(e) => onChange({ ...config, maxTokens: Number.parseInt(e.target.value) || 0 })}
          type="number"
          value={config.maxTokens.toString()}
        />
      </div>

      <div className="flex flex-col gap-2">
        <div className="flex flex-col gap-1">
          <Label className="font-semibold">
            Top P
            {" "}
            <span className="text-muted-foreground font-semibold">{config.topP.toFixed(2)}</span>
          </Label>
          <Slider
            max={1}
            min={0}
            onValueChange={([value]) => onChange({ ...config, topP: value })}
            step={0.05}
            value={[config.topP]}
          />
        </div>
      </div>

      <div className="flex flex-col gap-2">
        <Label className="font-semibold">Stop Sequences</Label>
        <Textarea
          onChange={(e) => onChange({ ...config, stopSequences: e.target.value.split("\n").filter(Boolean) })}
          placeholder="One per line"
          rows={3}
          value={config.stopSequences.join("\n")}
          className="resize-y"
        />
      </div>
    </div>
  )
}

import { Card, Label } from "@persona-framework/ui"
import { History } from "lucide-react"
import type { PromptVersion } from "../../types"

interface PromptVersionHistoryProps {
  versions: PromptVersion[]
  onRestore: (version: PromptVersion) => void
}

export function PromptVersionHistory({ versions, onRestore }: PromptVersionHistoryProps) {
  return (
    <div className="flex flex-col gap-3">
      <div className="flex items-center justify-between gap-2">
        <Label className="font-semibold">Version History</Label>
        <History className="h-5 w-5" />
      </div>

      <div className="flex flex-col gap-2 max-h-[400px] overflow-auto">
        {versions.length === 0 && (
          <div className="text-muted-foreground p-4 text-center">
            No version history yet. Versions are saved automatically when you make changes.
          </div>
        )}
        {versions.map((version, index) => (
          <Card
            className="p-3 cursor-pointer transition-colors hover:bg-accent"
            key={version.id}
            onClick={() => onRestore(version)}
          >
            <div className="flex items-center justify-between mb-1">
              <Label className="font-semibold">
                Version
                {" "}
                {versions.length - index}
              </Label>
              <div className="text-xs text-muted-foreground">
                {new Date(version.timestamp).toLocaleString()}
              </div>
            </div>
            <div className="text-sm text-muted-foreground">
              {version.content.substring(0, 100)}
              {version.content.length > 100 ? "..." : ""}
            </div>
            <div className="text-xs text-muted-foreground mt-1">
              Temp:
              {" "}
              {version.config.temperature}
              {" "}
              | Max tokens:
              {" "}
              {version.config.maxTokens}
              {" "}
              | Variables:
              {" "}
              {version.variables.length}
            </div>
          </Card>
        ))}
      </div>
    </div>
  )
}

