import React from 'react'

interface Column<T> {
  key: string
  header: string
  width?: string
  render?: (item: T) => React.ReactNode
}

interface DataTableProps<T> {
  data: T[]
  columns: Column<T>[]
  keyExtractor: (item: T) => string
  onRowClick?: (item: T) => void
  emptyMessage?: string
  compact?: boolean
}

export function DataTable<T>({
  data,
  columns,
  keyExtractor,
  onRowClick,
  emptyMessage = 'No data available',
  compact = false,
}: DataTableProps<T>) {
  const cellPadding = compact ? 'px-3 py-1.5' : 'px-4 py-2.5'

  if (data.length === 0) {
    return (
      <div className="flex items-center justify-center h-32 text-[var(--text-muted)] text-sm">
        {emptyMessage}
      </div>
    )
  }

  return (
    <div className="overflow-auto">
      <table className="w-full text-sm">
        <thead>
          <tr className="border-b border-[var(--border-primary)]">
            {columns.map((col) => (
              <th
                key={col.key}
                className={`${cellPadding} text-left text-xs font-medium text-[var(--text-secondary)] uppercase tracking-wider`}
                style={{ width: col.width }}
              >
                {col.header}
              </th>
            ))}
          </tr>
        </thead>
        <tbody className="divide-y divide-[var(--border-subtle)]">
          {data.map((item) => (
            <tr
              key={keyExtractor(item)}
              onClick={() => onRowClick?.(item)}
              className={`
                ${onRowClick ? 'cursor-pointer hover:bg-[var(--bg-hover)]' : ''}
                transition-colors
              `}
            >
              {columns.map((col) => (
                <td key={col.key} className={`${cellPadding} text-[var(--text-primary)]`}>
                  {col.render
                    ? col.render(item)
                    : String((item as Record<string, unknown>)[col.key] ?? '')}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

