import React, { useRef, useState, useEffect } from 'react'
import { Button } from '@persona-framework/ui'
import { Textarea } from '@persona-framework/ui'
import { Loader2, Send, Plus, X, Copy, Edit, Check, Shield, Flame, FileText, Zap, AlertTriangle } from 'lucide-react'
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter'
import { vscDarkPlus } from 'react-syntax-highlighter/dist/esm/styles/prism'
import { makeHttpClient } from '../../../data/https'

const http = makeHttpClient('/api')

interface ChatMessage {
  id: string
  role: 'user' | 'assistant'
  content: string
  timestamp: number
  taskId?: string
  isError?: boolean
  originalUserMessage?: string // For retry functionality
}

interface ContextItem {
  type: 'file' | 'folder' | 'selection'
  name: string
  path?: string
  content?: string
}

interface IntelliJStyleChatProps {
  personaCode?: string
  sprintContext?: any
  onFileReference?: (path: string) => void
}

export function IntelliJStyleChat({ personaCode = 'PAIMON', onFileReference }: IntelliJStyleChatProps) {
  const [messages, setMessages] = useState<ChatMessage[]>([])
  const [input, setInput] = useState('')
  const [contextItems, setContextItems] = useState<ContextItem[]>([])
  const [isGenerating, setIsGenerating] = useState(false)
  const [conversationId, setConversationId] = useState<string | null>(null)
  const [executionMode, setExecutionMode] = useState<'plan' | 'execute'>('execute')
  const [strictMode, setStrictMode] = useState(false)
  const [braveMode, setBraveMode] = useState(false)
  const [editingMessageId, setEditingMessageId] = useState<string | null>(null)
  const [editText, setEditText] = useState('')
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const textareaRef = useRef<HTMLTextAreaElement>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  const readFileContent = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader()
      reader.onload = (e) => resolve(e.target?.result as string)
      reader.onerror = reject
      reader.readAsText(file)
    })
  }

  const handleAttachClick = () => {
    fileInputRef.current?.click()
  }

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files
    if (!files) return

    for (let i = 0; i < files.length; i++) {
      const file = files[i]
      try {
        const content = await readFileContent(file)
        setContextItems(prev => [...prev, {
          type: 'file',
          name: file.name,
          content: content
        }])
      } catch {
        // File read failed, skip this file
      }
    }

    if (fileInputRef.current) {
      fileInputRef.current.value = ''
    }
  }

  const handleSend = async () => {
    if (!input.trim() || isGenerating) return

    const userMessage: ChatMessage = {
      id: `msg-${Date.now()}`,
      role: 'user',
      content: input,
      timestamp: Date.now(),
    }

    setMessages(prev => [...prev, userMessage])
    setInput('')
    setIsGenerating(true)

    const assistantMessageId = `msg-${Date.now()}-assistant`
    const assistantMessage: ChatMessage = {
      id: assistantMessageId,
      role: 'assistant',
      content: '',
      timestamp: Date.now(),
    }
    setMessages(prev => [...prev, assistantMessage])

    try {
      const response = await http.post('/chat', {
        message: input,
        conversationId,
        personaCode,
        projectPath: '/home/user/development/projects/persona-framework',
        executionMode,
        strictMode,
        braveMode,
        openFiles: contextItems.filter(c => c.type === 'file').map(c => ({
          path: c.path || c.name,
          content: c.content,
          language: 'text'
        }))
      })

      const data = response.data

      if (data.conversationId) {
        setConversationId(data.conversationId)
      }

      setMessages(prev =>
        prev.map(msg =>
          msg.id === assistantMessageId
            ? { ...msg, content: data.response || 'No response received', taskId: data.taskId }
            : msg
        )
      )
    } catch (error) {
      setMessages(prev =>
        prev.map(msg =>
          msg.id === assistantMessageId
            ? {
                ...msg,
                content: error instanceof Error ? error.message : 'Failed to send message',
                isError: true,
                originalUserMessage: input || userMessage.content
              }
            : msg
        )
      )
    } finally {
      setIsGenerating(false)
    }
  }

  const handleEditMessage = (messageId: string, content: string) => {
    setEditingMessageId(messageId)
    setEditText(content)
  }

  const handleCancelEdit = () => {
    setEditingMessageId(null)
    setEditText('')
  }

  const handleRetry = (messageId: string, originalMessage: string) => {
    // Remove the error message
    setMessages(prev => prev.filter(msg => msg.id !== messageId))
    // Set input and trigger send
    setInput(originalMessage)
    setTimeout(() => handleSend(), 100)
  }

  const handleSaveEdit = async () => {
    if (!editingMessageId || !editText.trim()) return

    const messageIndex = messages.findIndex(msg => msg.id === editingMessageId)
    if (messageIndex === -1) return

    const updatedMessage = { ...messages[messageIndex], content: editText }
    const messagesToKeep = messages.slice(0, messageIndex)
    setMessages([...messagesToKeep, updatedMessage])

    setEditingMessageId(null)
    setEditText('')

    setInput(editText)
    setTimeout(() => handleSend(), 100)
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSend()
    }
  }

  const parseCodeBlocks = (content: string) => {
    const codeBlockRegex = /```(\w+)?\n([\s\S]*?)```/g
    const parts: Array<{ type: 'text' | 'code'; content: string; language?: string }> = []
    let lastIndex = 0
    let match: RegExpExecArray | null

    while ((match = codeBlockRegex.exec(content)) !== null) {
      if (match.index > lastIndex) {
        parts.push({
          type: 'text',
          content: content.substring(lastIndex, match.index),
        })
      }

      parts.push({
        type: 'code',
        content: match[2].trim(),
        language: match[1] || 'text',
      })

      lastIndex = match.index + match[0].length
    }

    if (lastIndex < content.length) {
      parts.push({
        type: 'text',
        content: content.substring(lastIndex),
      })
    }

    return parts.length > 0 ? parts : [{ type: 'text' as const, content }]
  }

  const removeContextItem = (index: number) => {
    setContextItems(prev => prev.filter((_, i) => i !== index))
  }

  const copyCode = (code: string) => {
    navigator.clipboard.writeText(code)
  }

  return (
    <div className="flex flex-col h-full bg-transparent">
      {contextItems.length > 0 && (
        <div className="flex gap-1.5 p-2 border-t border-b border-[#3c3c3c] bg-[#252525] flex-wrap min-h-[40px]">
          {contextItems.map((item, idx) => (
            <div key={idx} className="flex items-center gap-1 px-2 py-1 bg-[#3c3c3c] rounded-xl text-xs text-[#cccccc]">
              <span>{item.name}</span>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => removeContextItem(idx)}
                className="min-w-0 p-0.5 h-auto"
              >
                <X className="w-3 h-3" />
              </Button>
            </div>
          ))}
        </div>
      )}

      <div className="flex-1 overflow-y-auto p-3 flex flex-col gap-4 bg-transparent">
        {messages.length === 0 ? (
          <div className="flex items-center justify-center h-full text-center p-6">
            <div className="max-w-md">
              <div className="text-lg font-semibold text-[#cccccc] mb-2">AI Chat Assistant</div>
              {personaCode && (
                <div className="text-sm text-[#858585] mb-6">Persona: {personaCode}</div>
              )}

              <div className="text-sm text-[#858585] mb-4">Try one of these prompts:</div>

              <div className="flex flex-col gap-2">
                {[
                  'Explain how this codebase is structured',
                  'Help me fix the failing tests',
                  'Refactor this function to be more readable',
                  'Add error handling to the API calls',
                ].map((prompt, idx) => (
                  <button
                    key={idx}
                    onClick={() => setInput(prompt)}
                    className="text-left px-4 py-2.5 bg-[#2b2b2b] hover:bg-[#323232] border border-[#3c3c3c] hover:border-[#007acc] rounded-lg text-sm text-[#cccccc] transition-colors"
                  >
                    {prompt}
                  </button>
                ))}
              </div>

              <div className="text-xs text-[#666] mt-6">
                Or type your own question below
              </div>
            </div>
          </div>
        ) : (
          messages.map(msg => (
            <div key={msg.id}>
              {msg.role === 'user' ? (
                <div className="self-end max-w-[80%] flex flex-col gap-1">
                  {editingMessageId === msg.id ? (
                    <>
                      <textarea
                        className="w-full min-h-[60px] bg-[#1e1e1e] text-white border border-[#3c3c3c] rounded px-2 py-1.5 text-sm font-inherit resize-y"
                        value={editText}
                        onChange={e => setEditText(e.target.value)}
                        autoFocus
                        onKeyDown={e => {
                          if (e.key === 'Escape') handleCancelEdit()
                          else if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) handleSaveEdit()
                        }}
                      />
                      <div className="flex gap-1 justify-end mt-1">
                        <Button size="sm" onClick={handleSaveEdit}>
                          <Check className="w-3 h-3 mr-1" />
                          Save & Resend
                        </Button>
                        <Button variant="outline" size="sm" onClick={handleCancelEdit}>
                          Cancel
                        </Button>
                      </div>
                    </>
                  ) : (
                    <>
                      <div className="self-end max-w-[80%] bg-[#264f78] text-white px-3.5 py-2.5 rounded-xl break-words whitespace-pre-wrap">
                        {msg.content}
                        <div className="text-[11px] text-[#858585] mt-1">
                          {new Date(msg.timestamp).toLocaleTimeString()}
                        </div>
                      </div>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => handleEditMessage(msg.id, msg.content)}
                        className="self-end opacity-70"
                        title="Edit message"
                      >
                        <Edit className="w-3 h-3 mr-1" />
                        Edit
                      </Button>
                    </>
                  )}
                </div>
              ) : msg.isError ? (
                // Error message with retry option
                <div className="self-start max-w-[90%] p-3 bg-[#2b2b2b] border border-[#5a1d1d] rounded-lg">
                  <div className="flex items-start gap-2">
                    <AlertTriangle className="w-4 h-4 text-[#f48771] flex-shrink-0 mt-0.5" />
                    <div className="flex-1">
                      <div className="text-[#f48771] text-sm font-medium mb-1">Failed to send message</div>
                      <div className="text-[#cccccc] text-sm mb-3">{msg.content}</div>
                      <div className="flex gap-2">
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => msg.originalUserMessage && handleRetry(msg.id, msg.originalUserMessage)}
                          className="h-7 text-xs"
                        >
                          Retry
                        </Button>
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={() => setMessages(prev => prev.filter(m => m.id !== msg.id))}
                          className="h-7 text-xs"
                        >
                          Dismiss
                        </Button>
                      </div>
                    </div>
                  </div>
                </div>
              ) : (
                <div className="self-start max-w-[90%] flex flex-col gap-2">
                  {parseCodeBlocks(msg.content).map((part, idx) =>
                    part.type === 'text' ? (
                      <div key={idx} className="text-[#cccccc] leading-relaxed whitespace-pre-wrap break-words">
                        {part.content}
                      </div>
                    ) : (
                      <div key={idx} className="mt-2 mb-2 rounded-md overflow-hidden border border-[#3c3c3c]">
                        <div className="flex justify-between items-center px-3 py-1.5 bg-[#2d2d2d] border-b border-[#3c3c3c]">
                          <span className="text-xs text-[#858585]">
                            {part.language}
                          </span>
                          <div className="flex gap-1">
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => copyCode(part.content)}
                              title="Copy"
                            >
                              <Copy className="w-3 h-3" />
                            </Button>
                          </div>
                        </div>
                        <SyntaxHighlighter
                          language={part.language}
                          style={vscDarkPlus}
                          customStyle={{
                            margin: 0,
                            fontSize: '13px',
                            backgroundColor: '#1e1e1e',
                          }}
                        >
                          {part.content}
                        </SyntaxHighlighter>
                      </div>
                    )
                  )}
                  <div className="text-[11px] text-[#858585] mt-1">
                    {new Date(msg.timestamp).toLocaleTimeString()}
                    {msg.taskId && <span className="ml-2 text-[#4ade80]">Task: {msg.taskId.substring(0, 8)}</span>}
                  </div>
                </div>
              )}
            </div>
          ))
        )}
        {isGenerating && (
          <div className="self-start max-w-[90%] flex flex-col gap-2">
            <div className="flex items-center gap-2">
              <Loader2 className="w-4 h-4 animate-spin" />
              <span className="text-sm">Generating response...</span>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="flex flex-col p-0 gap-0 border-t border-[#3c3c3c] bg-[#252525]">
        {/* Mode toggles toolbar */}
        <div className="flex items-center gap-2 px-3 py-2 border-b border-[#3c3c3c] text-xs">
          <span className="text-[#858585] mr-1">Mode:</span>

          <button
            onClick={() => setExecutionMode(executionMode === 'plan' ? 'execute' : 'plan')}
            className={`flex items-center gap-1.5 px-2 py-1 rounded transition-colors ${
              executionMode === 'plan'
                ? 'bg-[#1e3a5f] text-[#60a5fa] border border-[#3b82f6]'
                : 'bg-[#2b2b2b] text-[#858585] border border-[#3c3c3c] hover:border-[#525252]'
            }`}
          >
            {executionMode === 'plan' ? <FileText className="w-3 h-3" /> : <Zap className="w-3 h-3" />}
            {executionMode === 'plan' ? 'Plan' : 'Execute'}
          </button>

          <button
            onClick={() => setStrictMode(!strictMode)}
            className={`flex items-center gap-1.5 px-2 py-1 rounded transition-colors ${
              strictMode
                ? 'bg-[#3d2e0a] text-[#f59e0b] border border-[#f59e0b]'
                : 'bg-[#2b2b2b] text-[#858585] border border-[#3c3c3c] hover:border-[#525252]'
            }`}
          >
            <AlertTriangle className="w-3 h-3" />
            {strictMode ? 'Strict' : 'Flexible'}
          </button>

          <button
            onClick={() => setBraveMode(!braveMode)}
            className={`flex items-center gap-1.5 px-2 py-1 rounded transition-colors ${
              braveMode
                ? 'bg-[#450a0a] text-[#f87171] border border-[#ef4444]'
                : 'bg-[#2b2b2b] text-[#858585] border border-[#3c3c3c] hover:border-[#525252]'
            }`}
          >
            {braveMode ? <Flame className="w-3 h-3" /> : <Shield className="w-3 h-3" />}
            {braveMode ? 'Auto-approve' : 'Safe'}
          </button>

          {braveMode && (
            <span className="text-[#f87171] text-[10px] ml-1">
              Risky commands will run without confirmation
            </span>
          )}
        </div>

        {/* Input area */}
        <div className="relative w-full">
          <div className="absolute left-2 bottom-2 z-10">
            <Button
              variant="ghost"
              size="sm"
              onClick={handleAttachClick}
              title="Attach files"
              className="min-w-0 text-[#858585] hover:text-white"
            >
              <Plus className="w-4 h-4" />
            </Button>
          </div>
          <input
            ref={fileInputRef}
            type="file"
            multiple
            onChange={handleFileChange}
            className="hidden"
          />
          <Textarea
            ref={textareaRef}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Enter to send • Shift+Enter for new line"
            className="w-full min-h-[90px] bg-[#1e1e1e] text-[#cccccc] border-none pl-9 pr-14 resize-none"
          />
          <div className="absolute right-2 bottom-2">
            <Button
              variant="ghost"
              size="sm"
              onClick={handleSend}
              disabled={!input.trim() || isGenerating}
              title="Send (Enter)"
              className={`min-w-0 ${input.trim() && !isGenerating ? 'text-[#4ade80] hover:text-[#86efac]' : 'text-[#858585]'}`}
            >
              <Send className="w-4 h-4" />
            </Button>
          </div>
        </div>
      </div>
    </div>
  )
}

