import React, { useState, useRef, useEffect, useMemo, useCallback } from 'react'
import { FolderOpen, MessageSquare, GitBranch, AlertTriangle, Command as CommandIcon, FileCode } from 'lucide-react'
import '@ui/styles/theme.css'
import {
  Toolbar, IconTray, TabBar, StatusBar, WelcomeScreen, PanelContainer,
  type PanelConfig, type Tab
} from '@ui/components/organisms'
import { ResizeHandle } from '@ui/components/molecules'
import { CodeEditor } from '@ui/components/CodeEditor'
import { CommandPalette, Command } from '@ui/components/CommandPalette'
import { Breadcrumbs } from '@ui/components/Breadcrumbs'
import { GoToLineDialog } from '@ui/components/GoToLineDialog'
import { MarkdownPreview } from '@ui/components/MarkdownPreview'
import { GitDiffViewer } from '@ui/components/GitDiffViewer'
import { GitBlameView } from '@ui/components/GitBlameView'
import { WorkspaceSymbolsDialog } from '@ui/components/WorkspaceSymbolsDialog'
import { makeHttpClient } from './data/https'
import {
  type PanelType, type ExtensionPanelType, type OpenTab,
  usePreferences, useTabManagement, useKeyboardShortcuts,
  createPanelRegistry
} from './wraith'

const http = makeHttpClient('/api')

export function Wraith() {
  const [conversationId, setConversationId] = useState<string | null>(null)
  const [isGenerating, setIsGenerating] = useState(false)
  const { preferences, updatePreferences, setPreferences, savePreferences } = usePreferences()

  const [isNarrow, setIsNarrow] = useState<boolean>(() => {
    if (typeof window === 'undefined') return false
    return window.innerWidth < 1024
  })

  const [commandPaletteOpen, setCommandPaletteOpen] = useState(false)
  const [recentFilesOpen, setRecentFilesOpen] = useState(false)
  const [goToLineOpen, setGoToLineOpen] = useState(false)
  const [symbolsDialogOpen, setSymbolsDialogOpen] = useState(false)

  // Responsive handling
  useEffect(() => {
    let resizeTimer: NodeJS.Timeout
    const handleResize = () => {
      clearTimeout(resizeTimer)
      resizeTimer = setTimeout(() => {
        const nowNarrow = window.innerWidth < 1024
        setIsNarrow(nowNarrow)
        if (nowNarrow && (preferences.leftExpanded || preferences.rightExpanded)) {
          updatePreferences({
            leftExpanded: false,
            rightExpanded: false,
            activeLeftPanel: null,
            activeRightPanel: null,
          })
        }
      }, 150)
    }
    window.addEventListener('resize', handleResize)
    return () => {
      clearTimeout(resizeTimer)
      window.removeEventListener('resize', handleResize)
    }
  }, [preferences.leftExpanded, preferences.rightExpanded, updatePreferences])

  // Chat message handler
  const handleSendMessage = useCallback(async (
    message: string,
    context: any[],
    onStreamUpdate?: (text: string) => void,
    options?: { executionMode?: 'plan' | 'execute'; strictMode?: boolean; braveMode?: boolean }
  ) => {
    setIsGenerating(true)
    let sprintContext: any = null

    try {
      const projectId = 1
      const sprintResponse = await http.get(`/nexus/sprints/project/${projectId}/active`)
      if (sprintResponse.ok) {
        const sprint = await sprintResponse.json()
        const statsResponse = await http.get(`/nexus/sprints/${sprint.id}/stats`)
        const stats = statsResponse.ok ? await statsResponse.json() : null
        const tasksResponse = await http.get(`/nexus/sprints/${sprint.id}/tasks`)
        const tasks = tasksResponse.ok ? await tasksResponse.json() : []
        sprintContext = { type: 'sprint', sprint, stats, tasks: tasks.slice(0, 10) }
      }
    } catch (e) {
      console.warn('Failed to fetch sprint context:', e)
    }

    const enhancedContext = sprintContext ? [sprintContext, ...context] : context

    return new Promise((resolve, reject) => {
      let accumulatedResponse = ''
      let metadata: any = null
      const url = `${window.location.origin}/api/chat/conversational-stream`

      fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          message,
          conversationId,
          projectPath: "/workspace/persona-framework",
          personaCode: "PAIMON",
          context: enhancedContext,
          executionMode: options?.executionMode || 'execute',
          strictMode: options?.strictMode || false,
          braveMode: options?.braveMode || false
        })
      }).then(response => {
        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`)
        const reader = response.body?.getReader()
        const decoder = new TextDecoder()
        if (!reader) throw new Error('No reader available')

        const readChunk = () => {
          reader.read().then(({ done, value }) => {
            if (done) {
              setIsGenerating(false)
              resolve({
                response: accumulatedResponse,
                conversationId: metadata?.conversationId || conversationId,
                taskSubmitted: metadata?.taskSubmitted || false,
                taskId: metadata?.taskId,
                usage: metadata?.usage
              })
              return
            }

            const chunk = decoder.decode(value, { stream: true })
            for (const line of chunk.split('\n')) {
              if (line.startsWith('data: ')) {
                const data = line.substring(6)
                if (data === '[DONE]') continue
                if (data.startsWith('[METADATA]')) {
                  try {
                    metadata = JSON.parse(data.substring(10))
                    if (metadata.conversationId) setConversationId(metadata.conversationId)
                  } catch (e) { console.error('Failed to parse metadata:', e) }
                  continue
                }
                if (data.startsWith('ERROR: ')) {
                  setIsGenerating(false)
                  reject(new Error(data.substring(7)))
                  return
                }
                accumulatedResponse += data
                onStreamUpdate?.(accumulatedResponse)
              }
            }
            readChunk()
          }).catch(err => { setIsGenerating(false); reject(err) })
        }
        readChunk()
      }).catch(err => { setIsGenerating(false); reject(err) })
    })
  }, [conversationId])

  // Tab management
  const {
    handleFileClick, closeTab, togglePinTab, openInSplit, closeSplit,
    closeSplitTab, openGitDiff, openGitBlame, navigateToNextTab, navigateToPrevTab
  } = useTabManagement({ preferences, updatePreferences })

  // Extension toggle
  const toggleExtension = useCallback((extId: ExtensionPanelType) => {
    const isEnabled = preferences.enabledExtensions.includes(extId)
    if (isEnabled) {
      updatePreferences({
        enabledExtensions: preferences.enabledExtensions.filter(e => e !== extId),
        leftPanels: preferences.leftPanels.filter(p => p !== extId),
        rightPanels: preferences.rightPanels.filter(p => p !== extId),
        activeLeftPanel: preferences.activeLeftPanel === extId ? null : preferences.activeLeftPanel,
        activeRightPanel: preferences.activeRightPanel === extId ? null : preferences.activeRightPanel,
      })
    } else {
      updatePreferences({ enabledExtensions: [...preferences.enabledExtensions, extId] })
    }
  }, [preferences, updatePreferences])

  // Panel registry
  const availablePanels = useMemo(() => createPanelRegistry({
    onFileClick: handleFileClick,
    onSendMessage: handleSendMessage,
    isGenerating,
    editorSettings: preferences.editorSettings,
    onSaveSettings: (settings) => updatePreferences({ editorSettings: settings }),
    enabledExtensions: preferences.enabledExtensions,
    onToggleExtension: toggleExtension,
  }), [handleFileClick, handleSendMessage, isGenerating, preferences.editorSettings, preferences.enabledExtensions, toggleExtension, updatePreferences])

  // Panel click handler
  const handleIconClick = useCallback((panel: PanelType, side: 'left' | 'right') => {
    setPreferences(prev => {
      const key = side === 'left' ? 'activeLeftPanel' : 'activeRightPanel'
      const expandKey = side === 'left' ? 'leftExpanded' : 'rightExpanded'
      const activePanel = prev[key]
      const isExpanded = prev[expandKey]

      if (activePanel === panel && isExpanded) {
        const newPrefs = { ...prev, [expandKey]: false, [key]: null }
        savePreferences(newPrefs)
        return newPrefs
      } else {
        const newPrefs = { ...prev, [expandKey]: true, [key]: panel }
        savePreferences(newPrefs)
        return newPrefs
      }
    })
  }, [setPreferences, savePreferences])

  // Keyboard shortcuts
  useKeyboardShortcuts({
    preferences,
    updatePreferences,
    onCommandPalette: () => setCommandPaletteOpen(true),
    onRecentFiles: () => setRecentFilesOpen(true),
    onSymbolsDialog: () => setSymbolsDialogOpen(true),
    onGoToLine: () => setGoToLineOpen(true),
    onIconClick: handleIconClick,
    closeTab,
    openGitDiff,
    navigateToNextTab,
    navigateToPrevTab,
  })

  // Panel management helpers
  const addPanelToSide = useCallback((panel: PanelType, side: 'left' | 'right') => {
    const key = side === 'left' ? 'leftPanels' : 'rightPanels'
    if (!preferences[key].includes(panel)) {
      updatePreferences({ [key]: [...preferences[key], panel] })
    }
  }, [preferences, updatePreferences])

  const collapsePanel = useCallback((side: 'left' | 'right') => {
    const key = side === 'left' ? 'activeLeftPanel' : 'activeRightPanel'
    const expandKey = side === 'left' ? 'leftExpanded' : 'rightExpanded'
    updatePreferences({ [expandKey]: false, [key]: null })
  }, [updatePreferences])

  // Resize handlers
  const handleLeftResize = useCallback((delta: number) => {
    updatePreferences({ leftWidth: Math.min(500, Math.max(200, preferences.leftWidth + delta)) })
  }, [preferences.leftWidth, updatePreferences])

  const handleRightResize = useCallback((delta: number) => {
    updatePreferences({ rightWidth: Math.min(500, Math.max(200, preferences.rightWidth + delta)) })
  }, [preferences.rightWidth, updatePreferences])

  // Tab content renderer
  const getTabContent = useCallback((tab: OpenTab): React.ReactNode => {
    switch (tab.type) {
      case 'file':
        return tab.filePath?.toLowerCase().endsWith('.md')
          ? <MarkdownPreview filePath={tab.filePath} />
          : <CodeEditor filePath={tab.filePath || null} settings={preferences.editorSettings} />
      case 'git-diff':
        return <GitDiffViewer filePath={tab.filePath || null} onClose={() => closeTab(tab.id)} />
      case 'git-blame':
        return <GitBlameView filePath={tab.filePath || null} onClose={() => closeTab(tab.id)} />
      default:
        return null
    }
  }, [preferences.editorSettings, closeTab])

  // Derived data for components
  const usedPanels = [...preferences.leftPanels, ...preferences.rightPanels]
  const availableToAdd = (Object.keys(availablePanels) as PanelType[]).filter(p => !usedPanels.includes(p))

  const leftPanelConfigs: PanelConfig[] = useMemo(() =>
    preferences.leftPanels.filter(p => availablePanels[p]).map(id => ({
      id, name: availablePanels[id]?.name || id, icon: availablePanels[id]?.icon || null,
    })), [preferences.leftPanels, availablePanels])

  const rightPanelConfigs: PanelConfig[] = useMemo(() =>
    preferences.rightPanels.filter(p => availablePanels[p]).map(id => ({
      id, name: availablePanels[id]?.name || id, icon: availablePanels[id]?.icon || null,
    })), [preferences.rightPanels, availablePanels])

  const tabsForBar: Tab[] = useMemo(() =>
    preferences.openTabs.map(tab => ({
      id: tab.id, title: tab.title, pinned: preferences.pinnedTabs.includes(tab.id),
    })), [preferences.openTabs, preferences.pinnedTabs])

  const welcomeActions = useMemo(() => [
    {
      id: 'open-workspace',
      icon: <FolderOpen className="h-6 w-6" />,
      title: 'Open Workspace',
      description: 'Browse project files',
      onClick: () => {
        if (!preferences.leftPanels.includes('workspace')) {
          updatePreferences({ leftPanels: [...preferences.leftPanels, 'workspace'] })
        }
        updatePreferences({ leftExpanded: true, activeLeftPanel: 'workspace' })
      },
    },
    {
      id: 'command-palette',
      icon: <CommandIcon className="h-6 w-6" />,
      title: 'Command Palette',
      description: 'Ctrl/Cmd + Shift + P',
      onClick: () => setCommandPaletteOpen(true),
    },
    {
      id: 'hydra-chat',
      icon: <MessageSquare className="h-6 w-6" />,
      title: 'Hydra Chat',
      description: 'AI-powered assistance',
      onClick: () => {
        if (!preferences.rightPanels.includes('chat')) {
          updatePreferences({ rightPanels: [...preferences.rightPanels, 'chat'] })
        }
        updatePreferences({ rightExpanded: true, activeRightPanel: 'chat' })
      },
    },
  ], [preferences.leftPanels, preferences.rightPanels, updatePreferences])

  // Command palette commands
  const commands: Command[] = useMemo(() => {
    const isMac = typeof navigator !== 'undefined' && navigator.platform.toUpperCase().indexOf('MAC') >= 0
    const mod = isMac ? 'Cmd' : 'Ctrl'
    const cmds: Command[] = []

    preferences.leftPanels.forEach((panel, idx) => {
      cmds.push({
        id: `toggle-left-${panel}`,
        title: `Toggle ${availablePanels[panel]?.name}`,
        category: 'Panels',
        shortcut: `${mod}+${idx + 1}`,
        action: () => handleIconClick(panel, 'left'),
      })
    })

    preferences.rightPanels.forEach((panel, idx) => {
      cmds.push({
        id: `toggle-right-${panel}`,
        title: `Toggle ${availablePanels[panel]?.name}`,
        category: 'Panels',
        shortcut: `${mod}+Shift+${idx + 1}`,
        action: () => handleIconClick(panel, 'right'),
      })
    })

    cmds.push(
      { id: 'toggle-left-sidebar', title: 'Toggle Left Sidebar', category: 'View', shortcut: `${mod}+B`,
        action: () => preferences.leftPanels.length > 0 && handleIconClick(preferences.activeLeftPanel || preferences.leftPanels[0], 'left') },
      { id: 'toggle-right-sidebar', title: 'Toggle Right Sidebar', category: 'View', shortcut: `${mod}+Shift+B`,
        action: () => preferences.rightPanels.length > 0 && handleIconClick(preferences.activeRightPanel || preferences.rightPanels[0], 'right') },
      { id: 'open-settings', title: 'Open Settings', category: 'View', shortcut: `${mod}+,`,
        action: () => { updatePreferences({ rightExpanded: true, activeRightPanel: 'settings' }) } },
      { id: 'open-search', title: 'Search in Files', category: 'Search', shortcut: `${mod}+Shift+F`,
        action: () => { updatePreferences({ leftExpanded: true, activeLeftPanel: 'search' }) } },
      { id: 'recent-files', title: 'View Recent Files', category: 'File', shortcut: `${mod}+E`,
        action: () => setRecentFilesOpen(true) },
      { id: 'workspace-symbols', title: 'Go to Symbol in Workspace', category: 'Navigation', shortcut: `${mod}+T`,
        action: () => setSymbolsDialogOpen(true) },
    )

    if (preferences.activeTabId) {
      cmds.push(
        { id: 'close-tab', title: 'Close Active Tab', category: 'Tabs', shortcut: `${mod}+W`,
          action: () => closeTab(preferences.activeTabId!) },
        { id: 'pin-tab', title: preferences.pinnedTabs.includes(preferences.activeTabId) ? 'Unpin Active Tab' : 'Pin Active Tab',
          category: 'Tabs', action: () => togglePinTab(preferences.activeTabId!) },
      )

      const activeTab = preferences.openTabs.find(t => t.id === preferences.activeTabId)
      if (activeTab?.type === 'file') {
        cmds.push({ id: 'go-to-line', title: 'Go to Line', category: 'Navigation', shortcut: `${mod}+G`,
          action: () => setGoToLineOpen(true) })
        if (activeTab.filePath) {
          cmds.push(
            { id: 'show-git-diff', title: 'Show Git Diff', category: 'Git', shortcut: `${mod}+Shift+D`,
              action: () => openGitDiff(activeTab.filePath!) },
            { id: 'show-git-blame', title: 'Show Git Blame', category: 'Git', shortcut: `${mod}+Alt+G`,
              action: () => openGitBlame(activeTab.filePath!) },
          )
        }
      }

      if (preferences.splitMode === 'none') {
        cmds.push(
          { id: 'split-vertical', title: 'Split Editor Vertically', category: 'View', action: () => openInSplit('vertical') },
          { id: 'split-horizontal', title: 'Split Editor Horizontally', category: 'View', action: () => openInSplit('horizontal') },
        )
      } else {
        cmds.push({ id: 'close-split', title: 'Close Split Editor', category: 'View', action: closeSplit })
      }
    }

    if (preferences.openTabs.length > 1) {
      cmds.push(
        { id: 'next-tab', title: 'Next Tab', category: 'Tabs', shortcut: `${mod}+Tab`, action: navigateToNextTab },
        { id: 'previous-tab', title: 'Previous Tab', category: 'Tabs', shortcut: `${mod}+Shift+Tab`, action: navigateToPrevTab },
      )
    }

    availableToAdd.forEach(panel => {
      cmds.push(
        { id: `add-left-${panel}`, title: `Add ${availablePanels[panel]?.name} to Left`, category: 'Panels',
          action: () => addPanelToSide(panel, 'left') },
        { id: `add-right-${panel}`, title: `Add ${availablePanels[panel]?.name} to Right`, category: 'Panels',
          action: () => addPanelToSide(panel, 'right') },
      )
    })

    return cmds
  }, [preferences, availablePanels, availableToAdd, handleIconClick, updatePreferences, closeTab, togglePinTab,
      openGitDiff, openGitBlame, openInSplit, closeSplit, navigateToNextTab, navigateToPrevTab, addPanelToSide])

  const recentFilesCommands: Command[] = useMemo(() =>
    preferences.recentFiles.map(file => ({
      id: `recent-${file.path}`,
      title: file.name,
      category: 'Recent Files',
      shortcut: file.path,
      action: () => handleFileClick(file.path),
    })), [preferences.recentFiles, handleFileClick])

  // Render
  return (
    <div className="flex flex-col h-full w-full max-w-[100vw] bg-[var(--bg-primary)] overflow-hidden">
      <Toolbar
        collapsed={preferences.toolbarCollapsed}
        onToggleCollapse={() => updatePreferences({ toolbarCollapsed: !preferences.toolbarCollapsed })}
        onCommandPalette={() => setCommandPaletteOpen(true)}
        availablePanels={availableToAdd.map(p => ({ id: p, name: availablePanels[p]?.name || p }))}
        onAddToLeft={(id) => addPanelToSide(id as PanelType, 'left')}
        onAddToRight={(id) => addPanelToSide(id as PanelType, 'right')}
        panelCount={usedPanels.length}
        tabCount={preferences.openTabs.length}
      />

      <div className={`flex flex-1 min-h-0 w-full max-w-[100vw] overflow-hidden ${isNarrow ? 'flex-col' : ''}`}>
        {preferences.leftPanels.length > 0 && (
          <IconTray panels={leftPanelConfigs} activePanel={preferences.activeLeftPanel} side="left" isNarrow={isNarrow}
            onPanelClick={(id) => handleIconClick(id as PanelType, 'left')} />
        )}

        {preferences.leftExpanded && preferences.activeLeftPanel && availablePanels[preferences.activeLeftPanel] && (
          <PanelContainer
            title={availablePanels[preferences.activeLeftPanel]?.name || ''}
            icon={availablePanels[preferences.activeLeftPanel]?.icon}
            side="left" width={preferences.leftWidth} isNarrow={isNarrow}
            onClose={() => collapsePanel('left')} onCollapse={() => collapsePanel('left')} onResize={handleLeftResize}
          >
            {availablePanels[preferences.activeLeftPanel]?.component}
          </PanelContainer>
        )}

        <div className="flex flex-col flex-1 min-w-0">
          {preferences.openTabs.length > 0 && (
            <TabBar tabs={tabsForBar} activeTabId={preferences.activeTabId}
              onTabClick={(id) => updatePreferences({ activeTabId: id })} onTabClose={closeTab} onTabPin={togglePinTab} />
          )}

          {preferences.activeTabId && (() => {
            const activeTab = preferences.openTabs.find(t => t.id === preferences.activeTabId)
            return activeTab?.type === 'file' && activeTab.filePath ? <Breadcrumbs filePath={activeTab.filePath} /> : null
          })()}

          {preferences.splitMode === 'none' ? (
            <div className="flex-1 overflow-auto bg-[var(--bg-primary)] transition-opacity duration-200">
              {preferences.activeTabId ? getTabContent(preferences.openTabs.find(t => t.id === preferences.activeTabId)!) : <WelcomeScreen actions={welcomeActions} />}
            </div>
          ) : (
            <div className={`flex flex-1 overflow-hidden ${preferences.splitMode === 'vertical' ? 'flex-row' : 'flex-col'}`}>
              <div className="flex flex-col flex-1 min-w-0 min-h-0">
                {preferences.splitTabs.length > 0 && (
                  <TabBar
                    tabs={preferences.splitTabs.map(t => ({ id: t.id, title: t.title, pinned: false }))}
                    activeTabId={preferences.activeSplitTabId}
                    onTabClick={(id) => updatePreferences({ activeSplitTabId: id })}
                    onTabClose={closeSplitTab} onTabPin={() => {}}
                  />
                )}
                <div className="flex-1 overflow-auto bg-[var(--bg-primary)]">
                  {preferences.activeSplitTabId && getTabContent(preferences.splitTabs.find(t => t.id === preferences.activeSplitTabId)!)}
                </div>
              </div>

              <ResizeHandle direction={preferences.splitMode === 'vertical' ? 'horizontal' : 'vertical'}
                onResize={(delta) => updatePreferences({ splitRatio: Math.min(80, Math.max(20, preferences.splitRatio + delta / 5)) })} />

              <div className="flex flex-col flex-1 min-w-0 min-h-0">
                {preferences.openTabs.length > 0 && (
                  <TabBar tabs={tabsForBar} activeTabId={preferences.activeTabId}
                    onTabClick={(id) => updatePreferences({ activeTabId: id })} onTabClose={closeTab} onTabPin={togglePinTab} />
                )}
                <div className="flex-1 overflow-auto bg-[var(--bg-primary)]">
                  {preferences.activeTabId ? getTabContent(preferences.openTabs.find(t => t.id === preferences.activeTabId)!) : (
                    <div className="flex items-center justify-center h-full text-[var(--text-muted)]"><FileCode className="h-8 w-8" /></div>
                  )}
                </div>
              </div>
            </div>
          )}
        </div>

        {preferences.rightExpanded && preferences.activeRightPanel && availablePanels[preferences.activeRightPanel] && (
          <PanelContainer
            title={availablePanels[preferences.activeRightPanel]?.name || ''}
            icon={availablePanels[preferences.activeRightPanel]?.icon}
            side="right" width={preferences.rightWidth} isNarrow={isNarrow}
            onClose={() => collapsePanel('right')} onCollapse={() => collapsePanel('right')} onResize={handleRightResize}
          >
            {availablePanels[preferences.activeRightPanel]?.component}
          </PanelContainer>
        )}

        {preferences.rightPanels.length > 0 && (
          <IconTray panels={rightPanelConfigs} activePanel={preferences.activeRightPanel} side="right" isNarrow={isNarrow}
            onPanelClick={(id) => handleIconClick(id as PanelType, 'right')} />
        )}
      </div>

      <StatusBar
        leftItems={[
          { id: 'source-control', icon: <GitBranch className="h-3.5 w-3.5" />,
            onClick: () => updatePreferences({ leftExpanded: true, activeLeftPanel: 'source-control' }), title: 'Source Control' },
          { id: 'problems', icon: <AlertTriangle className="h-3.5 w-3.5" />,
            onClick: () => updatePreferences({ rightExpanded: true, activeRightPanel: 'problems' }), title: 'Problems' },
          ...(() => {
            const activeTab = preferences.openTabs.find(t => t.id === preferences.activeTabId)
            return activeTab?.type === 'file' && activeTab.filePath
              ? [{ id: 'file-path', label: activeTab.filePath, title: activeTab.filePath }] : []
          })(),
        ]}
        rightItems={[
          { id: 'indentation', label: `${preferences.editorSettings.insertSpaces ? 'Spaces' : 'Tabs'}: ${preferences.editorSettings.tabSize}` },
          { id: 'encoding', label: 'UTF-8' },
        ]}
      />

      <CommandPalette open={commandPaletteOpen} onClose={() => setCommandPaletteOpen(false)} commands={commands} />
      <CommandPalette open={recentFilesOpen} onClose={() => setRecentFilesOpen(false)} commands={recentFilesCommands} />
      <GoToLineDialog open={goToLineOpen} onClose={() => setGoToLineOpen(false)} onGoToLine={(line) => console.log('Go to line:', line)} />
      <WorkspaceSymbolsDialog open={symbolsDialogOpen} onClose={() => setSymbolsDialogOpen(false)} onNavigate={handleFileClick} />
    </div>
  )
}

export default Wraith

