import React from 'react'
import {
  FolderOpen, MessageSquare, Terminal as TerminalIcon,
  GitBranch, Settings, Search, AlertTriangle,
  Puzzle, Server, Bug, Hammer, FlaskConical,
  Activity, ScrollText, Sparkles, Palette, Wrench,
  Bookmark, CheckSquare, Package, Send, Database, Zap
} from 'lucide-react'
import { IntelliJStyleChat } from '@domains/chat'
import { TerminalPanel } from '@domains/terminal/components/TerminalPanel'
import { DevOpsStudio } from '@domains/devops'
import {
  WorkspacePanel, SettingsPanel, SearchPanel, SourceControlPanel, ProblemsPanel,
  SprintPanel, DebuggerPanel, BuildPanel, TestExplorerPanel, LogsPanel,
  AgentToolsPanel, ComponentBrowserPanel, BookmarksPanel, TodoTrackerPanel,
  EnvironmentManagerPanel, DependencyViewerPanel, RestClientPanel,
  DatabaseExplorerPanel, AICodeReviewPanel,
  type EditorSettings
} from '@ui/components/panels'
import { ErrorBoundary } from '@ui/components/ErrorBoundary'
import { PromptDesigner } from '@domains/prompts/components/PromptDesigner/PromptDesigner'
import { ExtensionsPanel as ExtensionsPanelComponent, type Extension as UIExtension } from '@ui/components/organisms'
import type { PanelRegistry, ExtensionPanelType } from '../types'
import { AVAILABLE_EXTENSIONS } from './extensions'

// Wrap panel components with error boundary for resilience
function withPanelErrorBoundary(component: React.ReactNode, panelName: string) {
  return (
    <ErrorBoundary
      onError={(error) => {
        // Could send to error reporting service
        if (process.env.NODE_ENV === 'development') {
          console.warn(`[${panelName}] Panel error:`, error.message)
        }
      }}
    >
      {component}
    </ErrorBoundary>
  )
}

interface CreatePanelRegistryOptions {
  onFileClick: (filePath: string) => void
  onSendMessage: (message: string, context: any[], onStreamUpdate?: (text: string) => void, options?: any) => Promise<any>
  isGenerating: boolean
  editorSettings: EditorSettings
  onSaveSettings: (settings: EditorSettings) => void
  enabledExtensions: ExtensionPanelType[]
  onToggleExtension: (id: ExtensionPanelType) => void
}

export function createPanelRegistry({
  onFileClick,
  onSendMessage,
  isGenerating,
  editorSettings,
  onSaveSettings,
  enabledExtensions,
  onToggleExtension,
}: CreatePanelRegistryOptions): PanelRegistry {
  const extensionsForUI: UIExtension[] = AVAILABLE_EXTENSIONS.map(ext => ({
    id: ext.id,
    name: ext.name,
    description: ext.description,
    icon: ext.icon,
    category: ext.category,
  }))

  const panels: PanelRegistry = {
    // Core panels - always available
    workspace: {
      name: 'Files',
      icon: <FolderOpen className="h-5 w-5" />,
      component: withPanelErrorBoundary(<WorkspacePanel onFileClick={onFileClick} />, 'Workspace'),
    },
    search: {
      name: 'Search',
      icon: <Search className="h-5 w-5" />,
      component: withPanelErrorBoundary(<SearchPanel onFileClick={onFileClick} />, 'Search'),
    },
    'source-control': {
      name: 'Git',
      icon: <GitBranch className="h-5 w-5" />,
      component: withPanelErrorBoundary(<SourceControlPanel />, 'Source Control'),
    },
    terminal: {
      name: 'Terminal',
      icon: <TerminalIcon className="h-5 w-5" />,
      component: withPanelErrorBoundary(<TerminalPanel />, 'Terminal'),
    },
    chat: {
      name: 'AI Chat',
      icon: <MessageSquare className="h-5 w-5" />,
      component: withPanelErrorBoundary(<IntelliJStyleChat onSendMessage={onSendMessage} isGenerating={isGenerating} />, 'AI Chat'),
    },
    problems: {
      name: 'Problems',
      icon: <AlertTriangle className="h-5 w-5" />,
      component: withPanelErrorBoundary(<ProblemsPanel />, 'Problems'),
    },
    settings: {
      name: 'Settings',
      icon: <Settings className="h-5 w-5" />,
      component: withPanelErrorBoundary(<SettingsPanel settings={editorSettings} onSave={onSaveSettings} />, 'Settings'),
    },
    extensions: {
      name: 'Extensions',
      icon: <Puzzle className="h-5 w-5" />,
      component: withPanelErrorBoundary(
        <ExtensionsPanelComponent
          extensions={extensionsForUI}
          enabledExtensions={enabledExtensions}
          onToggleExtension={(id) => onToggleExtension(id as ExtensionPanelType)}
        />,
        'Extensions'
      ),
    },
  }

  // Add enabled extension panels (all wrapped with error boundaries)
  if (enabledExtensions.includes('devops-studio')) {
