import { useState, useEffect } from "react"
import { HomePage } from "./pages/HomePage"
import { LoginPage } from "./pages/LoginPage"
import { OAuthCallbackPage } from './auth'
import Wraith from "./Wraith"

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(() => {
    const token = localStorage.getItem('wraith_access_token')
    return !!token
  })
  const [showHomepage, setShowHomepage] = useState(() => {
    const dismissed = localStorage.getItem('wraith_homepage_dismissed')
    return dismissed !== 'true'
  })
  const [currentPath, setCurrentPath] = useState(window.location.pathname)

  const handleLoginSuccess = () => {
    setIsAuthenticated(true)
  }

  // When user becomes authenticated, hide homepage and mark as dismissed
  useEffect(() => {
    if (isAuthenticated) {
      setShowHomepage(false)
      localStorage.setItem('wraith_homepage_dismissed', 'true')
    }
  }, [isAuthenticated])

  // Handle route changes
  useEffect(() => {
    const handleLocationChange = () => {
      setCurrentPath(window.location.pathname)
    }

    window.addEventListener('popstate', handleLocationChange)
    return () => window.removeEventListener('popstate', handleLocationChange)
  }, [])

  // Listen for OAuth success messages from popup
  useEffect(() => {
    const handleMessage = (event: MessageEvent) => {
      if (event.origin === window.location.origin && event.data?.type === 'OAUTH_SUCCESS') {
        // OAuth completed, check for token
        const token = localStorage.getItem('wraith_access_token')
        if (token) {
          setIsAuthenticated(true)
        }
      }
    }

    window.addEventListener('message', handleMessage)
    return () => window.removeEventListener('message', handleMessage)
  }, [])

  const handleGetStarted = () => {
    setShowHomepage(false)
    localStorage.setItem('wraith_homepage_dismissed', 'true')
  }

  // Handle OAuth callback route
  if (currentPath === '/auth/oauth/callback') {
    return <OAuthCallbackPage />
  }

  // Check if we're on OAuth callback route - never show homepage for this
  const isOAuthCallback = currentPath === '/auth/oauth/callback'

  // Show homepage ONLY if not authenticated AND user hasn't dismissed it AND not on OAuth callback
  if (!isAuthenticated && showHomepage && !isOAuthCallback) {
    return <HomePage onGetStarted={handleGetStarted} />
  }

  if (!isAuthenticated) {
    return <LoginPage onSuccess={handleLoginSuccess} />
  }

  return <Wraith />
}

export default App

