function parseOAuthCallback(url: string) {
  const urlObj = new URL(url)
  const params = new URLSearchParams(urlObj.search)

  return {
    accessToken: params.get('access_token'),
    refreshToken: params.get('refresh_token'),
    tokenType: params.get('token_type'),
    error: params.get('error'),
    errorMessage: params.get('error_description') || params.get('error_message'),
  }
}

function getFileIcon(fileName: string): FileIconConfig {
  // Check exact filename match first
  if (FILENAME_ICONS[fileName]) {
    return FILENAME_ICONS[fileName]
  }

  // Check for extension
  const lastDot = fileName.lastIndexOf('.')
  if (lastDot !== -1) {
    const ext = fileName.slice(lastDot).toLowerCase()

    // Check for .d.ts special case
    if (fileName.endsWith('.d.ts')) {
      return EXTENSION_ICONS['.d.ts']
    }

    if (EXTENSION_ICONS[ext]) {
      return EXTENSION_ICONS[ext]
    }
  }

  return DEFAULT_ICON
}

function getLanguageByPath(filePath: string): LanguageConfig {
  const fileName = filePath.split('/').pop() || ''
  const lowerFileName = fileName.toLowerCase()

  // Check special file names
  if (lowerFileName === 'dockerfile') return LANGUAGE_REGISTRY.dockerfile
  if (lowerFileName === 'makefile') return LANGUAGE_REGISTRY.makefile

  // Check by extension
  const ext = '.' + filePath.split('.').pop()?.toLowerCase()

  for (const lang of Object.values(LANGUAGE_REGISTRY)) {
    if (lang.extensions.some((e) => e === ext || fileName.endsWith(e))) {
      return lang
    }
  }

  return LANGUAGE_REGISTRY.plaintext
}

function getLSPSupportedLanguages(): LanguageConfig[] {
  return Object.values(LANGUAGE_REGISTRY).filter((lang) => lang.supportsLSP)
}

function getDebuggableLanguages(): LanguageConfig[] {
  return Object.values(LANGUAGE_REGISTRY).filter((lang) => lang.supportsDebug)
}

function getBuildableLanguages(): LanguageConfig[] {
  return Object.values(LANGUAGE_REGISTRY).filter((lang) => lang.supportsBuild)
}

function getMonacoLanguage(filePath: string): string {
  return getLanguageByPath(filePath).monacoLanguage
}

function withErrorBoundary<P extends object>(
  WrappedComponent: React.ComponentType<P>,
  name?: string
) {
  return function WithErrorBoundary(props: P) {
    return (
      <ErrorBoundary>
        <WrappedComponent {...props} />
      </ErrorBoundary>
    )
  }
}

function withAnnouncer<P extends object>(
  WrappedComponent: React.ComponentType<P & { announcer: AnnouncerContextType }>
) {
  return function WithAnnouncer(props: P) {
    const announcer = useAnnouncer()
    return <WrappedComponent {...props} announcer={announcer} />
  }
}

function getStoredProjectId(): number {
  try {
    const stored = localStorage.getItem(STORAGE_KEY)
    if (stored) {
      const parsed = parseInt(stored, 10)
      if (!isNaN(parsed) && parsed > 0) return parsed
    }
  } catch {
    // Ignore storage errors
  }
  return 1 // Default project ID
}

function loadEnvironments(): Environment[] {
  try {
    const stored = localStorage.getItem(STORAGE_KEY)
    if (stored) {
      const parsed = JSON.parse(stored)
      if (Array.isArray(parsed)) return parsed
    }
  } catch {
    // Invalid storage
  }
  return getDefaultEnvironments()
}

function saveEnvironments(envs: Environment[]) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(envs))
  } catch {
    // Storage unavailable
  }
}

function getDefaultEnvironments(): Environment[] {
  return [
    {
      id: 'dev',
      name: 'Development',
      type: 'development',
      isActive: true,
      variables: [
        { key: 'API_URL', value: 'http://localhost:3000', isSecret: false },
        { key: 'DEBUG', value: 'true', isSecret: false },
      ],
    },
    {
      id: 'staging',
      name: 'Staging',
      type: 'staging',
      isActive: false,
      variables: [
        { key: 'API_URL', value: 'https://staging.example.com', isSecret: false },
        { key: 'DEBUG', value: 'false', isSecret: false },
      ],
    },
    {
      id: 'prod',
      name: 'Production',
      type: 'production',
      isActive: false,
      variables: [
        { key: 'API_URL', value: 'https://api.example.com', isSecret: false },
        { key: 'API_KEY', value: 'sk-prod-xxxxx', isSecret: true },
      ],
    },
  ]
}

function loadConnections(): DatabaseConnection[] {
  try {
    const stored = localStorage.getItem(CONNECTIONS_KEY)
    if (stored) {
      const parsed = JSON.parse(stored)
      if (Array.isArray(parsed)) {
        return parsed.map(c => ({ ...c, isConnected: false }))
      }
    }
  } catch {
    // Invalid storage
  }
  return []
}

function saveConnections(connections: DatabaseConnection[]) {
  try {
    const toSave = connections.map(c => ({ ...c, isConnected: false, password: '' }))
    localStorage.setItem(CONNECTIONS_KEY, JSON.stringify(toSave))
  } catch {
    // Storage unavailable
  }
}

function loadBookmarks(): BookmarkItem[] {
