function loadHistory(): CodeReview[] {
  try {
    const stored = localStorage.getItem(HISTORY_KEY)
    if (stored) {
      const parsed = JSON.parse(stored)
      if (Array.isArray(parsed)) return parsed.slice(0, 20)
    }
  } catch {
