    localStorage.setItem(HISTORY_KEY, JSON.stringify(history.slice(0, 20)))
  } catch {
    // Storage unavailable
  }
}

function createKeyValuePair(): KeyValuePair {
  return { id: crypto.randomUUID(), key: '', value: '', enabled: true }
}

function getStatusColor(status: number): string {
  if (status >= 200 && status < 300) return 'text-[#00ff7f]'
  if (status >= 300 && status < 400) return 'text-[#5bcefa]'
  if (status >= 400 && status < 500) return 'text-[#ffd700]'
  return 'text-[#f48771]'
}

function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}

function createKeyValuePair(): KeyValuePair {
  return { id: crypto.randomUUID(), key: '', value: '', enabled: true }
}

function escapeString(str: string, quote: string = "'"): string {
  return str.replace(new RegExp(quote, 'g'), '\\' + quote)
}

function buildUrl(request: HttpRequest): string {
  let url = request.url

  // Replace path variables
  request.pathVariables.filter(p => p.enabled).forEach(p => {
    url = url.replace(`:${p.key}`, p.value).replace(`{${p.key}}`, p.value)
  })

  // Add query params
  const queryParams = request.queryParams.filter(p => p.enabled && p.key)
  if (queryParams.length > 0) {
    const params = new URLSearchParams()
    queryParams.forEach(p => params.append(p.key, p.value))
    url += (url.includes('?') ? '&' : '?') + params.toString()
  }

  return url
}

function getHeaders(request: HttpRequest): Record<string, string> {
  const headers: Record<string, string> = {}

  // Add regular headers
  request.headers.filter(h => h.enabled && h.key).forEach(h => {
    headers[h.key] = h.value
  })

  // Add auth headers
  if (request.auth.type === 'bearer' && request.auth.bearer?.token) {
    headers['Authorization'] = `Bearer ${request.auth.bearer.token}`
  } else if (request.auth.type === 'basic' && request.auth.basic) {
    const encoded = btoa(`${request.auth.basic.username}:${request.auth.basic.password}`)
    headers['Authorization'] = `Basic ${encoded}`
  } else if (request.auth.type === 'api-key' && request.auth.apiKey?.addTo === 'header') {
    headers[request.auth.apiKey.key] = request.auth.apiKey.value
  }

  // Add content-type for body
  if (request.body.type === 'json') {
    headers['Content-Type'] = 'application/json'
  } else if (request.body.type === 'x-www-form-urlencoded') {
    headers['Content-Type'] = 'application/x-www-form-urlencoded'
  } else if (request.body.type === 'graphql') {
    headers['Content-Type'] = 'application/json'
  }

  return headers
}

function getBody(request: HttpRequest): string | null {
  switch (request.body.type) {
    case 'json':
      return request.body.json || null
    case 'raw':
      return request.body.raw || null
    case 'graphql':
      if (request.body.graphql) {
        return JSON.stringify({
          query: request.body.graphql.query,
          variables: request.body.graphql.variables ? JSON.parse(request.body.graphql.variables) : undefined,
          operationName: request.body.graphql.operationName || undefined,
        })
      }
      return null
    case 'x-www-form-urlencoded':
      if (request.body.urlencoded) {
        const params = new URLSearchParams()
        request.body.urlencoded.filter(p => p.enabled).forEach(p => params.append(p.key, p.value))
        return params.toString()
      }
      return null
    default:
      return null
  }
}

function generateCurl(request: HttpRequest): string {
  const url = buildUrl(request)
  const headers = getHeaders(request)
  const body = getBody(request)

  let curl = `curl -X ${request.method} '${escapeString(url)}'`

  Object.entries(headers).forEach(([key, value]) => {
    curl += ` \\\n  -H '${escapeString(key)}: ${escapeString(value)}'`
  })

  if (body) {
    curl += ` \\\n  -d '${escapeString(body)}'`
  }

  return curl
}

function generateFetch(request: HttpRequest): string {
  const url = buildUrl(request)
  const headers = getHeaders(request)
  const body = getBody(request)

  let code = `const response = await fetch('${escapeString(url)}', {\n`
  code += `  method: '${request.method}',\n`

  if (Object.keys(headers).length > 0) {
    code += `  headers: {\n`
    Object.entries(headers).forEach(([key, value]) => {
      code += `    '${escapeString(key)}': '${escapeString(value)}',\n`
    })
    code += `  },\n`
  }

  if (body) {
    if (request.body.type === 'json' || request.body.type === 'graphql') {
      code += `  body: JSON.stringify(${body}),\n`
    } else {
      code += `  body: '${escapeString(body)}',\n`
    }
  }

  code += `});\n\n`
  code += `const data = await response.json();`

  return code
}

function generateAxios(request: HttpRequest): string {
  const url = buildUrl(request)
  const headers = getHeaders(request)
  const body = getBody(request)

  let code = `const response = await axios({\n`
  code += `  method: '${request.method.toLowerCase()}',\n`
  code += `  url: '${escapeString(url)}',\n`

  if (Object.keys(headers).length > 0) {
    code += `  headers: {\n`
    Object.entries(headers).forEach(([key, value]) => {
      code += `    '${escapeString(key)}': '${escapeString(value)}',\n`
    })
    code += `  },\n`
  }

  if (body) {
    if (request.body.type === 'json' || request.body.type === 'graphql') {
      code += `  data: ${body},\n`
    } else {
      code += `  data: '${escapeString(body)}',\n`
    }
  }

  code += `});`

  return code
}

function generatePython(request: HttpRequest): string {
  const url = buildUrl(request)
  const headers = getHeaders(request)
  const body = getBody(request)

  let code = `import requests\n\n`
  code += `response = requests.${request.method.toLowerCase()}(\n`
  code += `    '${escapeString(url, "'")}',\n`

  if (Object.keys(headers).length > 0) {
    code += `    headers={\n`
    Object.entries(headers).forEach(([key, value]) => {
      code += `        '${escapeString(key, "'")}': '${escapeString(value, "'")}',\n`
    })
    code += `    },\n`
  }

  if (body) {
    if (request.body.type === 'json' || request.body.type === 'graphql') {
      code += `    json=${body},\n`
    } else {
      code += `    data='${escapeString(body, "'")}',\n`
    }
  }

  code += `)\n\n`
  code += `print(response.json())`

  return code
}

function generateGo(request: HttpRequest): string {
  const url = buildUrl(request)
  const headers = getHeaders(request)
  const body = getBody(request)

  let code = `package main\n\n`
  code += `import (\n\t"bytes"\n\t"encoding/json"\n\t"fmt"\n\t"io"\n\t"net/http"\n)\n\n`
  code += `func main() {\n`

  if (body) {
    code += `\tpayload := []byte(\`${body}\`)\n`
    code += `\treq, err := http.NewRequest("${request.method}", "${url}", bytes.NewBuffer(payload))\n`
  } else {
    code += `\treq, err := http.NewRequest("${request.method}", "${url}", nil)\n`
  }

  code += `\tif err != nil {\n\t\tpanic(err)\n\t}\n\n`

  Object.entries(headers).forEach(([key, value]) => {
    code += `\treq.Header.Set("${key}", "${value}")\n`
  })

  code += `\n\tclient := &http.Client{}\n`
  code += `\tresp, err := client.Do(req)\n`
  code += `\tif err != nil {\n\t\tpanic(err)\n\t}\n`
  code += `\tdefer resp.Body.Close()\n\n`
  code += `\tbody, _ := io.ReadAll(resp.Body)\n`
  code += `\tfmt.Println(string(body))\n`
  code += `}\n`

  return code
}

function generateRust(request: HttpRequest): string {
  const url = buildUrl(request)
  const headers = getHeaders(request)
  const body = getBody(request)

  let code = `use reqwest;\n\n`
  code += `#[tokio::main]\n`
  code += `async fn main() -> Result<(), Box<dyn std::error::Error>> {\n`
  code += `    let client = reqwest::Client::new();\n`
  code += `    let response = client\n`
  code += `        .${request.method.toLowerCase()}("${url}")\n`

  Object.entries(headers).forEach(([key, value]) => {
    code += `        .header("${key}", "${value}")\n`
  })

  if (body) {
    code += `        .body(r#"${body}"#)\n`
  }

  code += `        .send()\n`
  code += `        .await?;\n\n`
  code += `    println!("{}", response.text().await?);\n`
  code += `    Ok(())\n`
  code += `}\n`

  return code
}

function getAllCodeSnippets(request: HttpRequest): CodeSnippet[] {
  return [
    { language: 'curl', label: 'cURL', code: generateCurl(request) },
    { language: 'javascript', label: 'JavaScript (fetch)', code: generateFetch(request) },
    { language: 'javascript', label: 'JavaScript (axios)', code: generateAxios(request) },
    { language: 'python', label: 'Python (requests)', code: generatePython(request) },
    { language: 'go', label: 'Go', code: generateGo(request) },
