  ]
}

function generateFromEndpoints(
  endpoints: DiscoveredEndpoint[],
  options: GenerateOptions
): OpenAPISpec {
  const spec: OpenAPISpec = {
    openapi: '3.0.3',
    info: {
      title: options.title,
      version: options.version,
      description: options.description,
    },
    servers: options.serverUrl ? [{ url: options.serverUrl }] : [],
    paths: {},
    components: {
      schemas: {},
      securitySchemes: {
        bearerAuth: {
          type: 'http',
          scheme: 'bearer',
          bearerFormat: 'JWT',
        },
        apiKey: {
          type: 'apiKey',
          in: 'header',
          name: 'X-API-Key',
        },
      },
    },
  }

  // Group endpoints by path
  const pathGroups = new Map<string, DiscoveredEndpoint[]>()
  endpoints.forEach(ep => {
    const normalized = normalizePath(ep.path)
    if (!pathGroups.has(normalized)) {
      pathGroups.set(normalized, [])
    }
    pathGroups.get(normalized)!.push(ep)
  })

  // Convert to OpenAPI paths
  pathGroups.forEach((eps, path) => {
    const pathItem: Record<string, OpenAPIOperation> = {}

    eps.forEach(ep => {
      const method = ep.method.toLowerCase()
      const operation: OpenAPIOperation = {
        summary: ep.description || `${ep.method} ${ep.path}`,
        operationId: ep.handler || `${method}${path.replace(/[^a-zA-Z0-9]/g, '')}`,
        tags: ep.tags || [extractTagFromPath(path)],
        parameters: [],
        responses: {
          '200': { description: 'Successful response' },
          '400': { description: 'Bad request' },
          '401': { description: 'Unauthorized' },
          '404': { description: 'Not found' },
          '500': { description: 'Internal server error' },
        },
      }

      // Add path parameters
      if (ep.params) {
        ep.params.forEach(param => {
          operation.parameters!.push({
            name: param,
            in: 'path',
            required: true,
            schema: { type: 'string' },
          })
        })
      }

      // Add query parameters
      if (ep.queryParams) {
        ep.queryParams.forEach(param => {
          operation.parameters!.push({
            name: param,
            in: 'query',
            required: false,
            schema: { type: 'string' },
          })
        })
      }

      // Add request body for POST/PUT/PATCH
      if (['post', 'put', 'patch'].includes(method)) {
        operation.requestBody = {
          required: true,
          content: {
            'application/json': {
              schema: ep.bodySchema || { type: 'object' },
            },
          },
        }
      }

      pathItem[method] = operation
    })

    spec.paths[path] = pathItem
  })

  return spec
}

function generateFromCollection(
  collection: Collection,
  options: GenerateOptions
): OpenAPISpec {
  const endpoints = flattenCollection(collection.items)
  return generateFromEndpoints(
    endpoints.map(req => requestToEndpoint(req)),
    options
  )
}

function flattenCollection(items: (CollectionFolder | SavedRequest)[]): SavedRequest[] {
  const requests: SavedRequest[] = []

  items.forEach(item => {
    if ('request' in item) {
      requests.push(item)
    } else if ('items' in item) {
      requests.push(...flattenCollection(item.items))
    }
  })

  return requests
}

function normalizePath(path: string): string {
  return path
    .replace(/:(\w+)/g, '{$1}')     // :param -> {param}
    .replace(/<(\w+)>/g, '{$1}')    // <param> -> {param}
    .replace(/\/+/g, '/')           // Remove duplicate slashes
    .replace(/\/$/, '') || '/'      // Remove trailing slash
}

function extractTagFromPath(path: string): string {
  const parts = path.split('/').filter(Boolean)
  // Skip 'api' prefix if present
  const startIndex = parts[0]?.toLowerCase() === 'api' ? 1 : 0
  return parts[startIndex] || 'default'
}

function generateTypes(spec: OpenAPISpec): string {
  let types = '// Auto-generated TypeScript types from OpenAPI spec\n\n'

  if (spec.components?.schemas) {
    Object.entries(spec.components.schemas).forEach(([name, schema]) => {
      types += generateTypeFromSchema(name, schema as Record<string, unknown>)
      types += '\n\n'
    })
  }

  // Generate request/response types for each operation
  Object.entries(spec.paths).forEach(([path, methods]) => {
    Object.entries(methods).forEach(([method, op]) => {
      const operation = op as OpenAPIOperation
      const baseName = operation.operationId || `${method}${path.replace(/[^a-zA-Z0-9]/g, '')}`

      // Request type
      if (operation.requestBody) {
        const content = operation.requestBody.content
        const schema = content['application/json']?.schema
        if (schema) {
          types += `export interface ${capitalize(baseName)}Request ${schemaToType(schema as Record<string, unknown>)}\n\n`
        }
      }

      // Response type
      const successResponse = operation.responses['200'] || operation.responses['201']
      if (successResponse?.content) {
        const schema = successResponse.content['application/json']?.schema
        if (schema) {
          types += `export interface ${capitalize(baseName)}Response ${schemaToType(schema as Record<string, unknown>)}\n\n`
        }
      }
    })
  })

  return types
}

function generateTypeFromSchema(name: string, schema: Record<string, unknown>): string {
  if (schema.type === 'object') {
    return `export interface ${name} ${schemaToType(schema)}`
  }
  return `export type ${name} = ${schemaToTypeValue(schema)}`
}

function schemaToType(schema: Record<string, unknown>): string {
  if (schema.type !== 'object') {
    return schemaToTypeValue(schema)
  }

  const properties = schema.properties as Record<string, unknown> | undefined
  if (!properties) return '{}'

  const required = (schema.required as string[]) || []
  const lines: string[] = []

  Object.entries(properties).forEach(([key, propSchema]) => {
    const isRequired = required.includes(key)
    const typeValue = schemaToTypeValue(propSchema as Record<string, unknown>)
    lines.push(`  ${key}${isRequired ? '' : '?'}: ${typeValue}`)
  })

  return `{\n${lines.join('\n')}\n}`
}

function schemaToTypeValue(schema: Record<string, unknown>): string {
  const type = schema.type as string

  switch (type) {
    case 'string':
      if (schema.enum) {
        return (schema.enum as string[]).map(v => `'${v}'`).join(' | ')
      }
      return 'string'
    case 'number':
    case 'integer':
      return 'number'
    case 'boolean':
      return 'boolean'
    case 'array':
      const items = schema.items as Record<string, unknown>
      return `${schemaToTypeValue(items)}[]`
    case 'object':
      return schemaToType(schema)
    default:
      return 'unknown'
  }
}

function capitalize(str: string): string {
  return str.charAt(0).toUpperCase() + str.slice(1)
}

function specToYaml(spec: OpenAPISpec): string {
  return JSON.stringify(spec, null, 2)
    .replace(/"/g, '')
    .replace(/,\n/g, '\n')
    .replace(/{\n/g, '\n')
    .replace(/}\n/g, '\n')
    .replace(/\[\n/g, '\n  - ')
    .replace(/\]/g, '')
}

function specToJson(spec: OpenAPISpec): string {
  return JSON.stringify(spec, null, 2)
}

function importFromOpenAPI(spec: OpenAPISpec | string): DiscoveredEndpoint[] {
  const parsed: OpenAPISpec = typeof spec === 'string' ? JSON.parse(spec) : spec
  const endpoints: DiscoveredEndpoint[] = []

  Object.entries(parsed.paths).forEach(([path, methods]) => {
    Object.entries(methods).forEach(([method, op]) => {
      const operation = op as OpenAPIOperation

      endpoints.push({
        method: method.toUpperCase() as HttpMethod,
        path,
        file: 'openapi',
        line: 0,
        handler: operation.operationId,
        description: operation.summary || operation.description,
        tags: operation.tags,
        params: operation.parameters
          ?.filter(p => p.in === 'path')
          .map(p => p.name),
        queryParams: operation.parameters
          ?.filter(p => p.in === 'query')
          .map(p => p.name),
      })
    })
  })

  return endpoints
}

function validateJson(value: string): { valid: boolean; error?: string } {
  if (!value.trim()) {
    return { valid: true }
  }

  try {
    JSON.parse(value)
    return { valid: true }
  } catch (err) {
    return {
      valid: false,
      error: err instanceof Error ? err.message : 'Invalid JSON',
    }
  }
}

function formatJson(value: string): string {
