}

function extractPathParams(path: string): string[] {
  const params: string[] = []
  // Match :param, {param}, <param>
  const matches = path.matchAll(/[:{}](\w+)[}>]?/g)
  for (const match of matches) {
    params.push(match[1])
  }
  return params
}

function extractNextJsPath(filePath: string): string {
  // app/api/users/[id]/route.ts -> /api/users/:id
  const match = filePath.match(/app\/(.*)\/route\.(ts|js)$/)
  if (!match) return ''

  let path = '/' + match[1]
  // Convert [param] to :param
  path = path.replace(/\[\.\.\.(\w+)\]/g, '*$1')  // [...param] -> *param (catch-all)
  path = path.replace(/\[(\w+)\]/g, ':$1')        // [param] -> :param
  return path
}

