async function scanFile(filePath: string, content: string): Promise<DiscoveredEndpoint[]> {
  const endpoints: DiscoveredEndpoint[] = []
  const lines = content.split('\n')

  // Detect framework from content
  let framework: keyof typeof FRAMEWORK_PATTERNS | null = null

  if (content.includes('express') || content.includes('Router()')) {
    framework = 'express'
  } else if (content.includes('fastify')) {
    framework = 'fastify'
  } else if (content.includes('@Controller') || content.includes('@nestjs')) {
    framework = 'nestjs'
  } else if (filePath.match(/app\/.*\/route\.(ts|js)$/)) {
    framework = 'nextjs'
  } else if (content.includes('Hono')) {
    framework = 'hono'
  } else if (content.includes('@app.route') || content.includes('Flask')) {
    framework = 'flask'
  } else if (content.includes('gin.') || content.includes('gin.Default')) {
    framework = 'gin'
  } else if (content.includes('fiber.')) {
    framework = 'fiber'
  } else if (content.includes('@GetMapping') || content.includes('@PostMapping')) {
    framework = 'springboot'
  }

  if (!framework) return endpoints

  // Handle Next.js app router
  if (framework === 'nextjs') {
    const path = extractNextJsPath(filePath)
    const pattern = FRAMEWORK_PATTERNS.nextjs.routePattern

    let match
    while ((match = pattern.exec(content)) !== null) {
      const method = match[1].toUpperCase() as HttpMethod
      const lineNumber = content.substring(0, match.index).split('\n').length

      endpoints.push({
        method,
        path,
        file: filePath,
        line: lineNumber,
        handler: method,
        params: extractPathParams(path),
      })
    }
    return endpoints
  }

  // Handle NestJS with controller prefix
  if (framework === 'nestjs') {
    let controllerPrefix = ''
    const controllerMatch = FRAMEWORK_PATTERNS.nestjs.controllerPattern?.exec(content)
    if (controllerMatch) {
      controllerPrefix = controllerMatch[1]
    }

    const pattern = FRAMEWORK_PATTERNS.nestjs.routePattern
    let match
    while ((match = pattern.exec(content)) !== null) {
      const method = match[1].toUpperCase() as HttpMethod
      const routePath = match[2] || ''
      const fullPath = '/' + [controllerPrefix, routePath].filter(Boolean).join('/')
      const lineNumber = content.substring(0, match.index).split('\n').length

      endpoints.push({
        method,
        path: fullPath.replace(/\/+/g, '/'),
        file: filePath,
        line: lineNumber,
        params: extractPathParams(fullPath),
      })
    }
    return endpoints
  }

  // Handle other frameworks with standard route patterns
  const frameworkConfig = FRAMEWORK_PATTERNS[framework]
  if ('routePattern' in frameworkConfig) {
    const pattern = frameworkConfig.routePattern
    let match
    while ((match = pattern.exec(content)) !== null) {
      const methodKey = match[1].toLowerCase()
      const path = match[2]
      const method = ('methodMap' in frameworkConfig ? frameworkConfig.methodMap[methodKey] : methodKey.toUpperCase()) as HttpMethod
      const lineNumber = content.substring(0, match.index).split('\n').length

      endpoints.push({
        method,
        path,
        file: filePath,
        line: lineNumber,
        params: extractPathParams(path),
      })
    }
  }

  return endpoints
}

function groupEndpointsByTag(endpoints: DiscoveredEndpoint[]): Record<string, DiscoveredEndpoint[]> {
