function buildFormData(items: FormDataItem[]): FormData {
  const formData = new FormData()

  items
    .filter((item) => item.enabled && item.key)
    .forEach((item) => {
      if (item.type === 'file' && item.file) {
        formData.append(item.key, item.file)
      } else {
