function createApiClient(config: ApiClientConfig): AxiosInstance {
  const client = axios.create({
    baseURL: config.baseURL.replace(/\/+$/, ''),
    timeout: config.timeout || 20_000,
  })

  axiosRetry(client, {
    retries: 2,
    retryDelay: axiosRetry.exponentialDelay,
    retryCondition: (error) => {
      // Don't retry on auth errors
      if (error.response?.status === 401 || error.response?.status === 403) {
        return false
      }
      return axiosRetry.isNetworkOrIdempotentRequestError(error)
    },
  })

  if (config.getToken) {
    client.interceptors.request.use(async (requestConfig) => {
      const token = typeof config.getToken === 'function'
        ? await config.getToken()
        : undefined

      if (token) {
        requestConfig.headers.Authorization = token.startsWith('Bearer ')
          ? token
          : `Bearer ${token}`
      }
      return requestConfig
    })

    // Response interceptor with token refresh
    let isRefreshing = false
    let failedQueue: Array<{ resolve: (token: string) => void; reject: (error: any) => void }> = []

    client.interceptors.response.use(
      (response) => response,
      async (error) => {
        const originalRequest = error.config as InternalAxiosRequestConfig & { _retry?: boolean }

        if (error.response?.status === 401 && !originalRequest._retry) {
          if (isRefreshing) {
            return new Promise((resolve, reject) => {
              failedQueue.push({ resolve, reject })
            }).then((token) => {
              originalRequest.headers.Authorization = `Bearer ${token}`
              return client(originalRequest)
            })
          }

          originalRequest._retry = true
          isRefreshing = true

          try {
            const refreshToken = localStorage.getItem(STORAGE_KEYS.REFRESH_TOKEN)
            if (!refreshToken) {
              throw new Error('No refresh token available')
            }

            const response = await axios.post(
              `${config.baseURL}/auth/refresh`,
              { refreshToken },
              { headers: { 'Content-Type': 'application/json' } }
            )

            const newToken = response.data.token || response.data.accessToken
            const newRefreshToken = response.data.refreshToken

            localStorage.setItem(STORAGE_KEYS.ACCESS_TOKEN, newToken)
            if (newRefreshToken) {
              localStorage.setItem(STORAGE_KEYS.REFRESH_TOKEN, newRefreshToken)
            }

            failedQueue.forEach(({ resolve }) => resolve(newToken))
            failedQueue = []

            originalRequest.headers.Authorization = `Bearer ${newToken}`
            return client(originalRequest)
          } catch (refreshError) {
            failedQueue.forEach(({ reject }) => reject(refreshError))
            failedQueue = []

            localStorage.removeItem(STORAGE_KEYS.ACCESS_TOKEN)
            localStorage.removeItem(STORAGE_KEYS.REFRESH_TOKEN)
            localStorage.removeItem(STORAGE_KEYS.USER)
            window.location.href = '/login'
            return Promise.reject(refreshError)
          } finally {
            isRefreshing = false
          }
        }

        return Promise.reject(error)
      }
    )
  }

  return client
}

function getDefaultApiClient(): AxiosInstance {
  if (defaultClient) {
    return defaultClient
  }

  defaultClient = createApiClient({
    baseURL: 'http://localhost:8989/api',
    getToken: () => {
      return localStorage.getItem(STORAGE_KEYS.ACCESS_TOKEN) || undefined
    },
  })
  return defaultClient
}

function setDefaultApiClient(client: AxiosInstance): void {
  defaultClient = client
}

function isApiError(error: unknown): error is AxiosError {
  return error instanceof Error && 'isAxiosError' in error
}

function parseApiError(error: unknown): ApiError {
  if (isApiError(error)) {
    return {
      message: error.response?.data?.message || error.message || 'Unknown error',
      code: error.code,
      status: error.response?.status,
      details: error.response?.data,
    }
  }

  if (error instanceof Error) {
    return {
      message: error.message,
    }
  }

  return {
    message: 'An unexpected error occurred',
  }
}

function createApiError(message: string, status?: number): ApiError {
  return {
    message,
    status,
  }
}

