(): Preferences => {
  try {
    const stored = localStorage.getItem(STORAGE_KEY)
    if (stored) {
      const parsed = JSON.parse(stored)
      const defaults = getDefaultPreferences()
      return {
        leftPanels: Array.isArray(parsed.leftPanels) ? parsed.leftPanels : defaults.leftPanels,
        rightPanels: Array.isArray(parsed.rightPanels) ? parsed.rightPanels : defaults.rightPanels,
        openTabs: Array.isArray(parsed.openTabs) ? parsed.openTabs : defaults.openTabs,
        activeTabId: parsed.activeTabId ?? defaults.activeTabId,
        leftExpanded: parsed.leftExpanded ?? defaults.leftExpanded,
        rightExpanded: parsed.rightExpanded ?? defaults.rightExpanded,
        activeLeftPanel: parsed.activeLeftPanel ?? defaults.activeLeftPanel,
        activeRightPanel: parsed.activeRightPanel ?? defaults.activeRightPanel,
        leftWidth: parsed.leftWidth || defaults.leftWidth,
        rightWidth: parsed.rightWidth || defaults.rightWidth,
        toolbarCollapsed: parsed.toolbarCollapsed ?? defaults.toolbarCollapsed,
        pinnedTabs: Array.isArray(parsed.pinnedTabs) ? parsed.pinnedTabs : defaults.pinnedTabs,
        recentFiles: Array.isArray(parsed.recentFiles) ? parsed.recentFiles : defaults.recentFiles,
        splitMode: parsed.splitMode || defaults.splitMode,
        splitTabs: Array.isArray(parsed.splitTabs) ? parsed.splitTabs : defaults.splitTabs,
        activeSplitTabId: parsed.activeSplitTabId ?? defaults.activeSplitTabId,
        splitRatio: parsed.splitRatio || defaults.splitRatio,
        editorSettings: parsed.editorSettings ? { ...defaults.editorSettings, ...parsed.editorSettings } : defaults.editorSettings,
        enabledExtensions: Array.isArray(parsed.enabledExtensions) ? parsed.enabledExtensions : defaults.enabledExtensions,
      }
    }
  } catch (e) {
    console.error('Failed to load preferences', e)
  }
  return getDefaultPreferences()
}

(prefs: Preferences) => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(prefs))
  } catch (e) {
    console.error('Failed to save preferences', e)
  }
}

function makeHttpClient(apiBaseUrl: string = '/api') {
  const http = axios.create({
    baseURL: (apiBaseUrl || '/api').replace(/\/+$/, ''),
    timeout: 20_000,
  })
  axiosRetry(http, { retries: 2, retryDelay: axiosRetry.exponentialDelay })

  http.interceptors.request.use(async (config) => {
    // Get token from Wraith's localStorage
    const token = localStorage.getItem('wraith_access_token')
    if (token) {
      const tokenType = localStorage.getItem('wraith_token_type') || 'Bearer'
      config.headers.Authorization = `${tokenType} ${token}`
    }
    return config
  })
  return http
}
